vector <int> adj[100010];

int dp[100010][2];

void dfs(int i, int par){
    bool mk = false;
    for(auto j: adj[i]){
        if(j == par) continue;
        mk = true;
        dfs(j, i);
    }
    if(mk == 0){
        dp[i][0] = dp[i][1] = 1;
    }
    else{
        int sm = 0, co = 0;
        for(auto j: adj[i]){
            if(j == par) continue;
            sm += dp[j][1];
            co++;
        }
        dp[i][0] = sm + 1;
        for(auto j: adj[i]){
            if(j == par) continue;
            dp[i][0] = min(dp[i][0], sm - dp[j][1] + dp[j][0]);
        }
        int mn1 = 1e7, mn2 = 1e7;
        for(auto j: adj[i]){
            if(j == par) continue;
            if(dp[j][0] - dp[j][1] <= mn1){
                mn2 = mn1;
                mn1 = dp[j][0] - dp[j][1];
            }
            else if(dp[j][0] - dp[j][1] < mn2){
                mn2 = dp[j][0] - dp[j][1];
            }
        }
        if(mn1 == 1e7 or mn2 == 1e7) dp[i][1] = dp[i][0];
        else dp[i][1] = sm + mn1 + mn2 - 1;
        dp[i][1] = min(dp[i][0], dp[i][1]);
    }
}

