int main(){
  int n;cin>>n;
  vector<int> edge[n];
  for(int i=1;i<n;i++){
    int u,v;cin>>u>>v;
    edge[u].push_back(v);
    edge[v].push_back(u);
  }
  vector<int> parent(n,-1),son[n];
  queue<int> que;
  que.push(0);
  while(que.size()){
    int p=que.front();que.pop();
    for(int q:edge[p]){
      if(parent[p]==q)continue;
      parent[q]=p;
      son[p].push_back(q);
      que.push(q);
    }
  }
  vector<int> res(n),ant(n,0),tant(n,0);
  int ans=0;
  for(int i=0;i<n;i++){
    res[i]=son[i].size();
    if(!res[i])que.push(i);
  }
  while(que.size()){
    int p=que.front();que.pop();//cout<<"P"<<p<<endl;
    int cnt=0;
    for(int q:son[p]){
      if(ant[q])ant[p]=1;
      else cnt++;
    }
    if(cnt>1){
      for(int q:son[p]){
        if(!ant[q])ant[q]=tant[q]=1,ans++,cnt--;
        if(cnt==1)break;
      }
      ant[p]=1;
    }
    if(~parent[p])if(--res[parent[p]]==0)que.push(parent[p]);
  }
  int f=0;
  if(son[0].size()==1){
    int p=son[0][0];
    for(int q:son[p])if(!ant[q])f=1;
  }
  if(son[0].size()==2){
    int a=son[0][0],b=son[0][1];assert(ant[a]||ant[b]);
    if(!ant[a]&&!tant[b])for(int q:son[b])if(!ant[q])f=1;
    if(!ant[b]&&!tant[a])for(int q:son[a])if(!ant[q])f=1;
  }
  ans+=f;
  //for(int i=0;i<n;i++)cout<<ant[i]<<" ";cout<<endl;
  cout<<max(ans,1)<<endl;
}

