int n;
vector <int> e[N];
int flag[N],tot[N];
void dfs(int x,int pre){
	For(i,0,(int)e[x].size()-1)
		if (e[x][i]==pre){
			swap(e[x][i],e[x].back());
			e[x].pop_back();
			break;
		}
	for (auto y : e[x])
		dfs(y,x);
	if (e[x].size()==0)
		flag[x]=1;
	else if (e[x].size()==1){
		flag[x]=flag[e[x][0]];
		tot[x]=tot[e[x][0]];
	}
	else {
		flag[x]=0;
		tot[x]=0;
		int cnt=0;
		for (auto y : e[x]){
			tot[x]+=tot[y];
			if (tot[y])
				cnt++;
		}
		tot[x]+=(int)e[x].size()-1-cnt;
	}
}
