    }
    auto solve = [&](auto&& rec, int node, int prev) -> int {
        int n = 0;
        bool z = false;
        for (auto next : G[node]) if (next != prev) {
            int m = rec(rec, next, node);
            if (!z && m == 0) z = true;
            else n += max(1, m);
        }
        return n;
    };
    for (int s = 0; s < N; s++) {
        if (G[s].size() != 1) {
            cout << max(1, solve(solve, s, -1)) << '\n';
            return 0;
        }
    }
    cout << 1 << '\n';
    return 0;
}

