//根付き木を作る。parentVectorに親nodeの番号が入る。
//parentVector[root] = -1
//treeRankVectorにはnodeのrankが入る。rootのrankは0
vector<ll> par;
vector<ll> treeRank;
void makeRootedTree(vector<ll> &parentVector, vector<ll> &treeRankVector, ll vecSize, ll root) {
    parentVector = vector<ll>(vecSize);
    treeRankVector = vector<ll>(vecSize);
    assert(root < (ll)parentVector.size());
    parentVector[root] = -1;
    treeRankVector[root] = 0;
    queue<ll> que;
    que.push(root);
    while (!que.empty()) {
        ll node = que.front();
        que.pop();
        REP (i, 0, G[node].size()) {
            edge e = G[node][i];
            if (e.to != parentVector[node]) {
                parentVector[e.to] = node;
                treeRankVector[e.to] = treeRankVector[node] + 1;
                que.push(e.to);
            }
        }
    }
}

ll ans = 0;
vector<bool> ant;
vector<bool> lastPlus;
//根付き木の葉から根に向かって何か処理をする
void leafToRoot(vector<ll> &parentVector, ll root) {
    ant = vector<bool>(parentVector.size(), false);
    lastPlus = vector<bool>(parentVector.size(), true);
    queue<ll> que;
    vector<ll> used(parentVector.size());
    fill(used.begin(), used.end(), 0);
    REP(i, 0, parentVector.size()) {
        if (i != root && G[i].size() == 1) {
            que.push(i);
            used[i] = 1;
        }
    }
    while (!que.empty()) {
        ll node = que.front();
        que.pop();

        //rootも含めて子だけのときに何かやりたいときはここに書く
        if (G[node].size() >= 3) {
            ll num = 0;
            REP(i, 0, G[node].size()) {
                edge e = G[node][i];
                if (e.to != par[node] && ant[e.to]) {
                    num++;
                }
            }
            if (num == G[node].size() - 1) {
                lastPlus[node] = false;
            } else {
                ans += G[node].size() - 2 - num;
                lastPlus[node] = true;
            }
            ant[node] = true;
        } else if (G[node].size() == 2) {
            REP(i, 0, G[node].size()) {
                edge e = G[node][i];
                if (e.to != par[node]) {
                    ant[node] = ant[e.to];
                    lastPlus[node] = lastPlus[e.to];
                }
            }
        }

        if (node == root) {
            if (lastPlus[node]) {
                ans++;
            }
            break;
        }
        ll parent = parentVector[node];
        used[parent]++;

        //ここに書く

        if ((parent == root && used[parent] == (ll)G[parent].size()) ||
            (parent != root && used[parent] == (ll)G[parent].size() - 1)) {
            que.push(parent);
        }
    }
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    ll N;
    cin >> N;
    V = N;
    REP(i, 0, N - 1) {
        ll a, b;
        cin >> a >> b;
        addedge(a, b, 1);
        addedge(b, a, 1);
    }
    ll root = -1;
    REP(i, 0, N) {
        if (G[i].size() == 1) {
            root = i;
            break;
        }
    }
    makeRootedTree(par, treeRank, N, root);
    leafToRoot(par, root);
    cout << ans << endl;
}

