int dfs(const GraphI& g, int i, int par) {
	int ans = 0, zero = 0;
	int s = 0;
	for(auto& p : g.e[i]) {
		int j = p.first;
		if(j != par) {
			int a = dfs(g, j, i);
			ans += a;
			if(a == 0) ++zero;
			++s;
			root[i] = root[j];
		}
