bool debug=false;

int n;
vector<int> nei[100005];
int dp[100005];

void dfs(int r,int p){
	int sm=0,nz=0;
	for(int i=0;i<nei[r].size();i++){
		if(nei[r][i]!=p){
			dfs(nei[r][i],r);
			sm+=dp[nei[r][i]];
			nz+=(dp[nei[r][i]]!=0);
		}
	}

	sm+=max(int(nei[r].size())-(p!=-1)-nz-1,0);
	dp[r]=sm;
}
int main(int argc,char* argv[]){
	scanf("%d",&n);
	for(int i=0;i<n-1;i++){
		int a,b;
		scanf("%d%d",&a,&b);
		nei[a].push_back(b);
		nei[b].push_back(a);
	}

	int mx=0;
	for(int i=1;i<n;i++){
		if(nei[i].size()>nei[mx].size()){
			mx=i;
		}
	}

	dfs(mx,-1);

	printf("%d",dp[mx]);
	return 0;
}

