const int N=100000+10;

int _r;char _c;

int read()
{
	while(!isdigit(_c=getchar()));
	_r=_c-48;
	while(isdigit(_c=getchar()))
		_r=_r*10-48+_c;
	return _r;
}

int n,d[N],rt,dp[N];
int fir[N],nxt[N<<1],to[N<<1],tote;

void dfs(int u,int fa=rt)
{
	int i,v,fl(1);
	for(i=fir[u];i;i=nxt[i])if((v=to[i])!=fa)
	{
		dfs(v,u);
		if(!dp[v])
		{
			if(fl)
				fl=0;
			else
				++dp[u];
		}
		else
			dp[u]+=dp[v];
	}
}

int main()
{
	n=read();
	int i,u,v;
	for(i=1;i<n;++i)
	{
		u=read()+1;v=read()+1;
		to[++tote]=v;nxt[tote]=fir[u];fir[u]=tote;
		to[++tote]=u;nxt[tote]=fir[v];fir[v]=tote;
		++d[u];++d[v];
	}
	for(i=1;i<=n&&!rt;++i)if(d[i]>2)
		rt=i;
	if(!rt)
		printf("1");
	else
	{
		dfs(rt);
		printf("%d",dp[rt]);
	}
	return 0;
}

