int n;
vector<int> g[100000];

bool isPath() {
	REP(i, 0, n) {
		if (g[i].size() > 2) return false;
	}
	return true;
}

int rec(int from, int prev) {
	int sum = 0;
	int child = 0;
	int cnt = 0;
	for (int to : g[from]) {
		if (to == prev) continue;
		int res = rec(to, from);

		sum += res;
		++child;
		if (res == 0) {
			++cnt;
		}
	}

	sum += max(0, cnt - 1);
	return sum;
}

int main() {
	cin >> n;
	REP(i, 1, n) {
		int a, b;
		cin >> a >> b;
		g[a].push_back(b);
		g[b].push_back(a);
	}

	if (isPath()) {
		assert(0);
		cout << 1 << endl;
	} else {
		cout << rec(0, -1) + (g[0].size() == 1) << endl;
	}
	return 0;
}

