const int MAXN = 100005;

int n, m;
vector<int> ord;
vector<int> gph[MAXN];
int dp[MAXN], pdp[MAXN], par[MAXN], cz[MAXN];

void dfs(int x, int p){
	ord.push_back(x);
	par[x] = p;
	for(auto &i : gph[x]){
		if(i != p) dfs(i, x);
	}
}

int main(){
	cin >> n;
	for(int i=0; i<n-1; i++){
		int s, e;
		scanf("%d %d",&s,&e);
		gph[s].push_back(e);
		gph[e].push_back(s);
	}
	dfs(0, -1);
	for(int i=ord.size()-1; i>=0; i--){
		int x = ord[i];
		for(auto &j : gph[x]){
			if(par[x] == j) continue;
			dp[x] += dp[j];
			if(dp[j] == 0) cz[x]++;
		}
		dp[x] += max(cz[x] - 1, 0);
	}
	for(int i=1; i<ord.size(); i++){
		int x = ord[i];
		int new_zero_count = cz[par[x]] - (dp[x] == 0);
		if(par[x] != 0 && pdp[par[x]] == 0) new_zero_count++;
		pdp[x] = dp[par[x]] - max(cz[par[x]] - 1, 0) - dp[x];
		pdp[x] += pdp[par[x]];
		pdp[x] += max(new_zero_count - 1, 0);
	}
	int ret = 1e9;
	for(int i=0; i<n; i++){
		int ans = 1;
		int count_zero = 0;
		for(auto &j : gph[i]){
			if(par[i] == j){
				ans += pdp[i];
				if(pdp[i] == 0) count_zero++;
			}
			else{
				ans += dp[j];
				if(dp[j] == 0) count_zero++;
			}
		}
		ans += max(count_zero - 1, 0);
		ret = min(ret, ans);
	}
	cout << ret << endl;
}

