const int N = 1e5 + 100;

vector<int> G[N];
int dp[N];
int res = 0;
int first = -1;
bool DP(int u, int fa) {
    dp[u] = u;
    int all = 0, sel = 0;
    for(int v : G[u]) {
        if(v == fa) continue;
        all ++;
        int c = DP(v, u);
        sel += c;
        if(c == 0) dp[u] = dp[v]; 
    }


    if(all > sel + 1) {
        res += all - (sel + 1);
        if(first == -1) first = dp[u];
        return true;
    } else {
        if(sel) return true;
        else return false;
    }
}

int main() {
    int n;
    cin >> n;
    for(int i = 1; i < n; i ++) {
        int u, v;
        scanf("%d %d", &u, &v);
        u ++, v ++;
        G[u].push_back(v);
        G[v].push_back(u);
    }

    DP(1, 1);
    int ans = res;
    res = 0;
    if(first != -1) {
        DP(first, first);
        ans = min(ans, res);
    }
    cout << ans + 1 << endl;
}

