using namespace std;
const int MAXN = 200002;
int sz[MAXN],kill[MAXN];
vector<int> tree[MAXN];
void dfs(int here,int dad){
    sz[here] = 1;
    for(int i=0;i<tree[here].size();i++){
        int there = tree[here][i];
        if(dad == there || kill[there]) continue;
        dfs(there,here);
        sz[here] += sz[there];
    }
}
int getcentroid(int here,int dad,int cap){
    for(int i=0;i<tree[here].size();i++){
        int there = tree[here][i];
        if(dad == there || kill[there]) continue;
        if(sz[there] > cap)return getcentroid(there,dad,cap);
    }
    return here;
}
int can = 0;
void solve(int here,int dad,map<int,int> &in){
    for(int i=0;i<tree[here].size() && can;i++){
        int there = tree[here][i];
        if(there == dad || kill[there]) continue;
        in[there]++; in[here]++;
        if(in[there] > 2 || in[here] > 2){
            can = 0;
            return;
        }
        solve(there,here,in);
    }
}
int ans = 0;
void decompose(int root){
    /*
    map<int,int> in;
    can = 1;
    solve(root,-1,in);
    if(can)return;
     */
    dfs(root,-1);
    ans++;
    int cen = getcentroid(root,-1,sz[root]/2); //앞으로 모든 center로 처리해야됨
    kill[cen] = 1;
    vector<int> L,R;
    for(int i=0;i<tree[cen].size();i++){
        int there =tree[cen][i];
        if(kill[there]) continue;
        can = 1;
        map<int,int> in;
        solve(there,-1,in);
        if(can)L.push_back(there);
        else R.push_back(there);
        //decompose(there);
    }
    if(L.size() == 0 && R.size() == 0){
        return;
    }
    if(R.size() == 0){
        ans++; return;
    }
    for(auto x:R){
        decompose(x);
    }
}
