int dfs(int parent, int now) {
	if (parent != -1 && G[now].size() == 1) {
		return 0;
	}
	int res = 0;
	int cnt0 = 0;
	for (int i = 0; i < G[now].size(); i++) {
		if (G[now][i] == parent) {
			continue;
		}
		int temp = dfs(now, G[now][i]);
