#define MP make_pair
#define PB push_back
#define FOR(i,a,b) for(int i = (a); i < (b); ++i)
#define RFOR(i,b,a) for(int i = (b) - 1; i >= (a); --i)
#define REP(i, t) FOR(i,0,t)
#define ALL(a) a.begin(), a.end()
#define SZ(a) (int)((a).size())

const LL MOD = 1000000007;
const int INF = 1000000007;
const LL LINF = 1LL * INF * INF;
const int MAXN = 100007;
const LD EPS = 1e-7;

vector <int> g[MAXN];
PII E[MAXN];
bool used[MAXN][2];
int DP[MAXN][2], ans = INF;
map <PII, int> M;

void dfs(int v, int p = -1)
{
	int e1 = M[MP(v, p)];
	if (p > -1)
		used[e1][E[e1].first == v] = true;
	int sum = 0, sons = 0, emp = 0;
	REP(i, SZ(g[v]))
	{
		int to = g[v][i], e = M[MP(v, to)];
		if (to == p)
			continue;
		++sons;
		if (!used[e][E[e].first == to])
			dfs(to, v);
		sum += DP[e][E[e].first == to];
		emp += !DP[e][E[e].first == to];
	}
	if (p > -1)
		DP[e1][E[e1].first == v] = sum + max(0, emp - 1);
	else
		ans = min(ans, sum + max(1, emp));
}

