const ll INF = 2e18;


vector<int>G[100010];
int dp[100010][2];
bool vis[100010][2];
int func(int n,int pre, bool flag) {
	if (vis[n][flag])return dp[n][flag];
	int deg = G[n].size();
	if (deg == 1) {
		if (flag) {
			dp[n][flag] = 1;
		}
		else dp[n][flag] = 0;
	}
	else if (deg == 2) {
		if (flag) {
			ll res = INF;
			for (auto chi : G[n]) {
				if (chi == pre)continue;
				res = min(res, func(chi,n, 0) + 1);
				res = min(res, func(chi, n, 1));
			}
			dp[n][flag] = res;
		}
		else {
			ll res = INF;
			for (auto chi : G[n]) {
				if (chi == pre)continue;
				res = min(res, func(chi, n, 0));
			}
			dp[n][flag] = res;
		}
	}
	else {
		if (!flag) {
			dp[n][flag] = INF;
			vis[n][flag] = true;
			return INF;
		}
		ll sum = 0;
		for (auto chi : G[n]) {
			if (chi == pre)continue;
			sum += func(chi, n, 1);
		}
		ll res = INF;
		for (auto chi : G[n]) {
			if (chi == pre)continue;
			res = min(res, sum - func(chi, n, 1) + min(func(chi, n, 1), func(chi, n, 0)));
		}
		dp[n][flag] = res;
	}
	vis[n][flag] = true;
	//pe(n); pe(flag); print(dp[n][flag]);
	return dp[n][flag];
}

void solve() {
	int N; cin >> N;
	REP(i, N) {
		dp[i][0] = INF;
		dp[i][1] = INF;
	}
	REP(i, N - 1) {
		int u, v; cin >> u >> v;
		G[u].push_back(v);
		G[v].push_back(u);
	}
	int par = 0;
	int mx = 0;
	REP(i, N) {
		if (G[i].size() > mx) {
			mx = G[i].size();
			par = i;
		}
	}
	ll ans = func(par, par, 1);
	print(ans);
}


