int modpow(int n, int k, int MOD) {
	int ans = 1; n %= MOD;
	while (k > 0) {
	  if (k & 1) ans = (ans*n) % MOD;
	  k >>= 1; n = (n*n) % MOD;
	}
	return ans;
}

