const int N = (int) 1e5 + 123;

int n;
vector<int> g[N];
bool isb[N], need[N];
int dp[N];

void dfs(int v, int f = -1) {
    int deg = 0;
    int repr = -1;
    for (int u : g[v]) {
        if (u == f) continue;
        deg++;
        repr = u;
        dfs(u, v);
    }

    isb[v] = (deg == 0 || (deg == 1 && isb[repr]));
    if (isb[v]) {
        need[v] = 1;
        return;
    }

    int cnt = 0;
    int cnt2 = 0;

    for (int u : g[v]) {
        if (u == f) continue;
        if (isb[u]) {
            cnt++;
        } else {
            dp[v] += dp[u];
            cnt2++;
        }
    }

    need[v] = (cnt2 == 1 && cnt <= 1);
    dp[v] += max(0, cnt - 1);
}

