        y = p[x][i];
        r1 = min(dp[y][0][1],dp[y][1][1]) -dp[y][1][0];
        dp[x][0][1] = min(dp[x][0][1],r-r1);
    }
    if(pp == -1){

        if(ch[x].size() > 2){
