            dp[x][1][1] = min(dp[x][1][1],r+min(dp[y][1][0],dp[y][1][1]) - dp[y][1][1]);
        //    r1 += dp[y][1][1];
        }
    }
    dp[x][0][1] = max(dp[x][0][1],1LL);
