int dfs(int v, int prev)
{
	if(G[v].size() == 1) return 0;

	int ret, sum = 0, cnt = 0;
	for(int i = 0; i < G[v].size(); i++){
		if(G[v][i] == prev) continue;
		ret = dfs(G[v][i], v);
		sum += ret;
		if(ret > 0) cnt++;
	}

	if(prev != -1){
		if(G[v].size()-2 >= cnt) sum += (G[v].size()-2)-cnt;
	}else{
		if(G[v].size()-1 >= cnt) sum += (G[v].size()-1)-cnt;
	}
	return sum;
}

