#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using pii = pair<int, int>;

constexpr int INF = 1e9;
constexpr ll INFLL = 1e18;

void dfs(vector<vector<int>> const& g, int v, int p, vector<vector<int>>& dp) {
    int const d = g[v].size();
    if(d == 1) { // leaf
        dp[v][0] = 0;
        dp[v][1] = 1;
        return;
    }

    int sum = 0;
    for(auto to : g[v]) {
        if(to != p) {
            dfs(g, to, v, dp);
            sum += dp[to][1];
        }
    }
    if(sum >= INF) {
        cout << v << endl;
    }
    for(auto to : g[v]) {
        if(to != p) {
            if(d == 2) { // par and a child
                dp[v][0] = dp[to][0];
                dp[v][1] = dp[to][1];
            } else {
                dp[v][1] = min({dp[v][1], sum - dp[to][1] + dp[to][0], sum});
            }
        }
    }
}

int main() {
    int N; cin >> N;
    vector<vector<int>> g(N);
    for(int i = 0; i < N - 1; ++i) {
        int x, y; cin >> x >> y;
        g[x].push_back(y);
        g[y].push_back(x);
    }
    int r = -1;
    for(int i = 0; i < N; ++i) {
        if(g[i].size() >= 3) r = i;
    }
    if(r == -1) { // path
        cout << 1 << endl;
        return 0;
    }

    vector<vector<int>> dp(N, vector<int>(2, INF));
    dfs(g, r, -1, dp);
    cout << dp[r][1] << endl;
}

