    }

    for(int i = 0; i < n; i++)
        if(adj[i].size() >= 3)
            r = i;

    if(r < 0)
        return cout << 1 << '\n', 0;

    dfs(r);
    cout << dp[r][1] << '\n';
    return 0;
}

