using namespace std;
vector <int> g[100010];
vector <int> tree[100010];
int chain[100010];
int dp[2][100010];

void dfs(int x, int par) {
	for(auto i : g[x]) {
		if(i - par) {
			tree[x].push_back(i);
			dfs(i, x);
		}
	}
}

void traverse(int x) {
	if(tree[x].size() == 1) {
		chain[x] = chain[tree[x][0]];
	} else if (tree[x].empty()) {
		chain[x] = 1;
		dp[1][x] = 1;
		dp[0][x] = 1;
	}
	int opt = 0;
	for(auto i : tree[x]) {
		traverse(i);
		dp[0][x] += dp[1][i];
		dp[1][x] += dp[1][i];
		if(chain[i] == 1) {
			opt = max(opt, dp[1][i]);
		}
	}
	if(tree[x].size() == 2) {
		if(chain[tree[x][0]]) {
			dp[1][x] = min(dp[1][x], dp[0][tree[x][1]]);
		}
		if(chain[tree[x][1]]) {
			dp[1][x] = min(dp[1][x], dp[0][tree[x][0]]);
		}
	} else if (tree[x].size() > 2) {
		dp[1][x] -= opt;
	}
	// cout << x << " " << dp[1][x] << " " << dp[0][x] << endl;
}
