bool used[MAXN];

P dfs(int t){
    int cnt = 0;
    used[t] = true;
    P res;

    for(int v : V[t]){
        if(used[v]) continue;
        P d = dfs(v);
        cnt ++;
        res.first += d.first;
        res.second += d.second;
    }
    if(cnt == 0) return P(1,0);
    if(res.first == 1 && res.second == 0) return res;
    if(res.first > 0) res.first--;
    res.second += res.first;
    return P(0, res.second);
}

