inline void dfs(int x,int fa=0) { 
	for(auto i : S[x]) if( i != fa ) { 
		dfs(i,x);
		if( f[i] ) f[x] |= 1;
		else g[x]++;
	}
	if( g[x] > 1 ) ans += g[x] - 1, g[x] = 1, f[x] |= 1;
