long long int N, M, K, H, W, L, R;

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> N;
	vector<vector<pair<int,int>>>edge(N);
	for (int i = 1; i < N; i++) {
		cin >> L >> R;
		edge[L].push_back({ R,1 });
		edge[R].push_back({ L,1 });
	}
	for (int i = 0; i < N; i++) {
		sort(edge[i].begin(), edge[i].end());
	}
	int leaf = 0;
	for (int i = 0; i < N; i++) {
		M += max(0, (int)edge[i].size() - 1);
		if (edge[i].size() == 1) {
			leaf = i;
		}
	}
	vector<int>cost(N);
	for (int i = 0; i < N; i++) {
		cost[i] = edge[i].size() - 1;
	}
	while (1) {
		vector<int>dis(N, INT_MAX);
		dis[leaf] = 0;
		queue<pair<int, bool>>Q;
		Q.push({ leaf,true });
		while (!Q.empty()) {
			int cn = Q.front().first;
			bool zero = Q.front().second;
			Q.pop();
			for (auto i : edge[cn]) {
				if (zero) {
					if (cost[i.first]) {
						if (dis[i.first] > dis[cn] + i.second) {
							dis[i.first] = dis[cn] + i.second;
							Q.push({ i.first ,!(cost[i.first] - i.second) });
						}
					}
					else {
						if (dis[i.first] > dis[cn]) {
							dis[i.first] = dis[cn];
							Q.push({ i.first ,true });
						}
					}
				}
				else {
					if (cost[i.first]) {
						if (dis[i.first] > dis[cn] + 2 * i.second) {
							dis[i.first] = dis[cn] + 2 * i.second;
							Q.push({ i.first ,!(cost[i.first] - 2 * i.second) });
						}
					}
					else {
						if (dis[i.first] > dis[cn] + i.second) {
							dis[i.first] = dis[cn] + i.second;
							Q.push({ i.first ,true });
						}
					}
				}
			}
		}
		int leaves = 0;
		for (int i = 0; i < N; i++) {
			if (dis[leaves] < dis[i]) {
				leaves = i;
			}
		}
		Q.push({ leaves,true });
		for (int i = 0; i < N; i++) {
			dis[i] = INT_MAX;
		}
		dis[leaves] = 0;
		vector<int>bef(N);
		vector<int>gain(N);
		while (!Q.empty()) {
			int cn = Q.front().first;
			bool zero = Q.front().second;
			Q.pop();
			for (auto i : edge[cn]) {
				if (zero) {
					if (cost[i.first]) {
						if (dis[i.first] > dis[cn] + i.second) {
							dis[i.first] = dis[cn] + i.second;
							bef[i.first] = cn;
							gain[i.first] = i.second;
							Q.push({ i.first ,!(cost[i.first] - i.second) });
						}
					}
					else {
						if (dis[i.first] > dis[cn]) {
							dis[i.first] = dis[cn];
							bef[i.first] = cn;
							gain[i.first] = i.second;
							Q.push({ i.first ,true });
						}
					}
				}
				else {
					if (cost[i.first]) {
						if (dis[i.first] > dis[cn] + 2 * i.second) {
							dis[i.first] = dis[cn] + 2 * i.second;
							bef[i.first] = cn;
							gain[i.first] = i.second;
							Q.push({ i.first ,!(cost[i.first] - i.second) });
						}
					}
					else {
						if (dis[i.first] > dis[cn] + i.second) {
							dis[i.first] = dis[cn] + i.second;
							bef[i.first] = cn;
							gain[i.first] = i.second;
							Q.push({ i.first ,true });
						}
					}
				}
			}
		}
		int terminal = 0;
		for (int i = 0; i < N; i++) {
			if (dis[i] > dis[terminal]) {
				terminal = i;
			}
		}
		if (dis[terminal] < 3) {
			for (int i = 0; i < N; i++) {
				K += cost[i];
			}
			break;
		}
		K += 2;
		while (terminal != leaves) {
		//	cout << "terminal " << terminal << " gain " << gain[terminal] << endl;
			if (gain[terminal]) {
				cost[terminal] = max(0, cost[terminal] - 1);
				cost[bef[terminal]] = max(0, cost[bef[terminal]] - 1);
				L = 0;
				R = edge[terminal].size();
				while (R - L > 1) {
					int mid = (R + L + 1) / 2;
					if (edge[terminal][mid].first <= bef[terminal]) {
						L = mid;
					}
