int dfs(int v, int pr)
{
    int ans = 0;
    bool ok = false;
    int tau = 0;
    bamb[v] = 1;
    for (int u : g[v])
        if (u != pr)
        {
            tau++;
            int t = dfs(u, v);
            if (!bamb[u])
                bamb[v] = 0;
            else
                ok = true;
            ans += t;
        }
    if (tau == 1 && !ok && ans == 1)
        return 2;
    if (tau > 1)
        bamb[v] = 0;
    if (tau == 0 || (tau == 1 && ok))
        return 1;
    if (ok)
        ans--;
    if (ans == 1 && tau == 2)
    {
        bool ok = true;
        for (int u : g[v])
            if (u != pr && !bamb[u])
                ok = false;
        if (!ok)
            return 2;
    }
    return ans;
}

