  	check[i] = false;
    exist[i] = true;
  }
  int start = -1;
  rep(i,n){
  	if(G[i].size() >= 3){
  		start = i;
  		break;
  	}
  }
  if(start == -1){
    cout<<1<<endl;
    return 0;
  }
  minimize(start);
  exist[start] = true;
  ll ans = 0;
  rep(i,n){
    rep(j,G[i].size()){
      cerr<<G[i][j]<<" ";
    }
    cerr<<endl;
  }
  rep(j,n){
    check[j] = !exist[j];
  }
  queue<int> q;
  q.push(start);
  while(q.size() > 0){
    int i = q.front();q.pop();
