    check[i] = true;
    rep(j,G[i].size()){
      q.push(G[i][j]);
    }
  	if(G[i].size() <= 1){
  		continue;
  	}
    int count = 0;
  	rep(j,G[i].size()){
  		int next = G[i][j];
  		if(G[next].size() == 1 && exist[next]){
        count++;
      }
  	}
    ans += max(0, count-1);
  }
  cerr<<"hoge"<<endl;
  cout<<ans<<endl;
  return 0;
}

