ll dfs( ll v, ll p = -1 ) {
  ll ret = 0;
  ll leaf = 0;

  for( auto u : G[v] ) if( u != p ) {
    ll x = dfs( u, v );

    if( !x )
      ++leaf;

    ret += x;
  }

  if( leaf > 1 ) {
    ret += leaf-1;
  }

  return ret;
}

