int dp[maxn];
int ans;

void dfs(int x,int prev)
{
	for(int i=0;i<v[x].size();i++)
	{
		int son=v[x][i];
		if(son!=prev)
		{
			dfs(son,x);
		}
	}
	vector<int>tmp;
	int sum=0;
	for(int i=0;i<v[x].size();i++)
	{
		int son=v[x][i];
		if(son!=prev)
		{
			tmp.push_back(dp[son]);
			sum+=dp[son];
		}
	}
	//dp[x]有可能为0 
	int add=0;
	for(int i=0;i<tmp.size();i++)
	{
		if(!tmp[i])add++;
	}
	dp[x]=sum+max(add-1,0); //add-1可能<0 
}

