const int N = 1e5+7;

int n, curr, ans = inf;

VI G[N];

bitset<N> path;

int cost[N];
int p[N];

void dfs(int v)
{
	path[v] = 1;
	int cnt = 0;

	for(auto it:G[v])
	{
		if(it!=p[v])
		{
			p[it] = v;
			dfs(it);
			++cnt;

			if(!path[it])
				path[v] = 0;
			else
				++cost[v];
		}
	}

	curr += max(0, cost[v]-1);

	if(cnt>1)
		path[v] = 0;
}

void go(int v)
{
	ans = min(ans, curr+1);

	for(auto it:G[v])
	{
		if(it!=p[v])
		{
			curr -= max(0, cost[v]-1);

			if(path[it])
				--cost[v];

			curr += max(0, cost[v]-1);

			go(it);

			curr -= max(0, cost[v]-1);

			if(path[it])
				++cost[v];

			curr += max(0, cost[v]-1);
		}
	}
}

int32_t main()
{
	ios_base::sync_with_stdio(0);
