	cin >> n;

	for(int i = 1; i < n; ++i)
	{
		int a, b;
		cin >> a >> b;
		++a;
		++b;
		G[a].pb(b);
		G[b].pb(a);
	}

	int r = 1;

	for(int i = 2; i <= n; ++i)
	{
		if(G[i].size()>G[r].size())
			r = i;
	}

	if(G[r].size()<=2)
	{
		cout << 1;
		exit(0);
	}

	dfs(r);
	go(r);

	cout << ans;
}

