struct Data{
	int ud, ld, cnt;
	bool f;
	Data(int ud, int ld, int cnt, bool f):ud(ud), ld(ld), cnt(cnt), f(f){}

	Data operator+(const Data& d){
		ud = min(ud, d.ud);
		ld = max(ld, d.ld);
		cnt += d.cnt;
		if(ld-ud >= 1 && cnt >= 2)
			f = 1;
		return Data(ud, ld, cnt, f);
	}

	bool operator<(const Data& d2) const{
		return ld-ud > d2.ld-d2.ud;
	}
};

int N;
vector<int> G[114514];
int lc[114514] = {};

Data dfs1(int v, int p, int d){
	if(G[v].size()-(p != -1) == 0)
		return Data(d, d, 1, 1);
	if(G[v].size()-(p != -1) == 1){
		Data ret = dfs1(G[v][G[v][0] == p], v, d+1);
		if(ret.ud == d+1)
			ret.ud = d;
		if(lc[G[v][G[v][0]==p]])
			ret.f = 0;
		return ret;
	}
	Data ret(INF, -INF, 0, 0);
	vector<Data> vs;
	REP(i, G[v].size()){
		if(G[v][i] == p) continue;
		Data a = dfs1(G[v][i], v, d+1);
		a.f = 0;
		if(a.ud == d+1)
			vs.push_back(a);
		else
			ret = ret+a;
	}
	sort(all(vs));
	REP(i, vs.size()-1)
		ret = ret+vs[i];
	lc[v] = vs.size();
	return ret;
}

