#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1e5 + 5;

int N;
vector <int> E[MAXN];
int dep[MAXN], parent[MAXN];
set <int> ch[MAXN];

struct cmp {
	bool operator()(const int &lhs, const int &rhs) const {
		if (dep[lhs] != dep[rhs])
			return dep[lhs] > dep[rhs];
		return lhs < rhs;
	}
};

set <int, cmp> S;

void load() {
	scanf("%d", &N);
	for (int i = 1; i < N; i++) {
		int a, b;
		scanf("%d%d", &a, &b);
		a++; b++;
		E[a].push_back(b);
		E[b].push_back(a);
	}
}

void dfs(int x, int p, int d) {
	dep[x] = d;
	parent[x] = p;
	for (auto it : E[x])
		if (it != p) {
			dfs(it, x, d + 1);
			ch[x].insert(it);
		}
}

int solve() {
	int root = 0;
	for (int i = 1; i <= N; i++)	
		if (E[i].size() > 2)
			root = i;

	if (!root)
		return 1;

	dfs(root, 0, 0);

	for (int i = 1; i <= N; i++)
		S.insert(i);

	int sol = 0;
	while (!S.empty()) {
		int x = *S.begin();
		S.erase(x);
		if (x == root)
			break;
		int dad = parent[x];
		if (ch[dad].size() == 1)
			continue;
		sol += (int)ch[dad].size() - 1;
		for (auto it : ch[dad])
			if (S.count(it))
				S.erase(it);
		ch[dad].clear();
		S.erase(dad);
		if (dad != root) 
			ch[parent[dad]].erase(dad);
	}

	return sol;
}

int main() {
	load();
	printf("%d\n", solve());
	return 0;
}

