bool isPath()
{
	int cnt = 0;
	for (int i = 0; i < n; i++)
	{
		if (deg[i] == 1)
		{
			cnt++;
		}
		if (deg[i] > 2)
		{
			root = i;
			return false;
		}
		if (deg[i] == 2)
		{
			root = i;
		}
	}
	return cnt == 2;
}

void dfs(int v)
{
	mark[v] = true;
	vector<int> child;
	for (int i = 0; i < graph[v].size(); i++)
	{
		int u = graph[v][i];
		if (!mark[u])
		{
			dfs(u);
			child.push_back(u);
		}
	}
	int cnt = 0;
	for (int i = 0; i < child.size(); i++)
	{
		dp[v] += dp[child[i]];
		if (dp[child[i]])
		{
			cnt++;
		}
	}
	if (cnt < (int)child.size() - 1)
	{
		dp[v] += (int)child.size() - 1 - cnt;
	}
}



