// Problem Specific Parameter:
const int limit = 100010;
vector<int> graph[limit];
int deg[limit];
bool del[limit];

void dfs(int v, int p) {
	if (deg[v] >= 3) return;
	del[v] = true;
	for (auto &v2 : graph[v]) {
		if (v2 == p) continue;
		dfs(v2, v);
	}
}

int a[limit], b[limit];

int main(void) {
	int n;
	cin >> n;

	rep(i, n - 1) {
		cin >> a[i] >> b[i];
		graph[a[i]].push_back(b[i]);
		graph[b[i]].push_back(a[i]);
		deg[a[i]]++, deg[b[i]]++;
	}

	rep(v, n) {
		if (deg[v] != 1) continue;
		dfs(v, -1);
	}

	rep(v, n) graph[v].clear();

	rep(i, n - 1) {
		if (del[a[i]] or del[b[i]]) continue;
		graph[a[i]].push_back(b[i]);
		graph[b[i]].push_back(a[i]);
	}

	int ans = 0;
	rep(v, n) {
		if (deg[v] <= 2) continue;
		const int val = max<int>(0, deg[v] - 1 - graph[v].size());
		ans += val;
	}

	chmax(ans, 1);
	cout << ans << endl;

	return 0;
}

