using namespace std;
int n,ans;
vector<int>s[N];
int root,h[N],f[N],g[N];
void dfs(int x,int fa)
{
	for(auto i:s[x])
	{
		if(i!=fa)
		{
			dfs(i,x);
			f[x]|=f[i];
			if(!f[i])g[x]++;
		}
	}
	if(g[x]>1)ans+=g[x]-1,f[x]=1;
	return ;
}
void dffs(int x,int fa)
{
	for(auto i:s[x])
	{
		if(i!=fa)
		{
			h[i]=h[x]+1;
			dffs(i,x);
		}
	}
	if(h[x]>h[root])root=x;
}
int main()
{
	scanf("%d",&n);
	for(int i=0;i<=n-2;i++)
	{
		int t1,t2;scanf("%d%d",&t1,&t2);
		t1++;t2++;
		s[t1].push_back(t2);
		s[t2].push_back(t1);
	}
	dffs(1,-1);
	dfs(root,-1);
	cout<<ans+1<<endl;
	return 0;
}

