int N;
map<int, vector<int>> edges;

vector<int> dp1, dp2;

int dfs1(int now, int prv)
{
    vector<int> tmp;
    for (auto nxt : edges[now]) if (nxt != prv)
    {
        tmp.push_back(dfs1(nxt, now));
    }
    int n_zero = 0, ans = 0;
    for (auto v : tmp)
    {
        ans += v;
        if (v == 0) n_zero++;
    }
    return dp1[now] = ans + max(n_zero - 1, 0);
}

void dfs2(int now, int prv)
{
    vector<int> n, v;
    int n_zero = 0;
    for (auto nxt : edges[now])
    {
        n.push_back(nxt);
        if (nxt != prv)
        {
            v.push_back(dp1[nxt]);
            if (dp1[nxt] == 0) n_zero++;
        }
        else
        {
            v.push_back(dp2[nxt]);
            if (dp2[nxt] == 0) n_zero++;
        }
    }
    int tot = accumulate(ALL(v), 0);
    REP(i, n.size()) if (n[i] != prv)
    {
        dp2[n[i]] = tot - v[i] + max(n_zero - (dp1[n[i]] == 0), 0);
    }
    for (auto nxt : edges[now]) if (nxt != prv) dfs2(nxt, now);
}

int main()
{
    cin >> N;
    REP(_, N - 1)
    {
        int a, b;
        cin >> a >> b;
        edges[a].push_back(b);
        edges[b].push_back(a);
    }
    dp1.resize(N);
    dfs1(0, -1);
    dp2.resize(N);
    dfs2(0, -1);
    int anx = 10000000;
    FOR(i, 0, N)
    {
        mmin(anx, dp1[i] + dp2[i] + 1);
    }
    cout << anx << endl;
}

