    if (key == inf)ss << " *|";
    else {
        ss << std::right << std::setw(2) << key;
        ss << "|";
    }
    rep(w, -W, W)ss << std::right << std::setw(4) << w;
    ss << "" << endl;
    rep(w, W * 8 + 3)ss << "_";
    ss << "" << endl;
    rep(h, -H, H) {
        ss << std::right << std::setw(2) << h << "|";
        int NW = min(sz(a[h]), 6ll);
        rep(w, -NW, NW) { if (abs(a[h][w]) == linf) ss << "   e" << ""; else ss << std::right << std::setw(4) << a[h][w]; }
        ss << "" << endl;
    }
    return ss.str();
