int par_[MAX_N];
int flag_netsukigi[MAX_N];
void make_netsukigi(int r){
    rep(i,MAX_N){
        G[i].clear();
        par_[i] = 0;
        flag_netsukigi[i] = 0;
    }
    queue<int> que;
    que.push(r);
    flag_netsukigi[r] = 1;
    par_[r] = -1;

    while(que.size() > 0){
        int x = que.front();
        que.pop();
        flag_netsukigi[x] = 1;
        rep(i,pre_G[x].size()){
            if(flag_netsukigi[pre_G[x][i]] == 0){
                par_[pre_G[x][i]] = x;
                G[x].push_back(pre_G[x][i]);
                que.push(pre_G[x][i]);
            }
        }
    }
}

int main() {
    int n;
    cin >> n;

    rep(i,n-1){
        int a, b;
        scanf("%d%d", &a, &b);
        pre_G[a].push_back(b);
        pre_G[b].push_back(a);
    }
    int start = -1;
    rep(i,n){
        if(pre_G[i].size()==1){
            start = i;
            break;
        }
    }

    make_netsukigi(start);
    int ans = 1;

    queue<int> que;
    int ari[n] = {};
    int son[n] = {};
    int nashi[n] = {};
    rep(i,n){
        son[i] = G[i].size();
        if(i == start) continue;
        if(son[i] == 0){
            que.push(i);
        }
    }

    while(que.size()){
        int x = que.front();
        que.pop();
        if(G[x].size()>=2){
            ans += max(0, nashi[x]-1);
            ari[x] = 1;
        }
        if(x == start)break;
        son[par_[x]]--;
        if(son[par_[x]] == 0) que.push(par_[x]);
        if(ari[x] == 0) nashi[par_[x]]++;
    }

    cout << ans << endl;
    return 0;
