int sch(int now, int prev, const vector<vector<int>> &tr, vector<bool> &zeroable, const vector<int> &d) {
  if(d[now] == 1) {
    zeroable[now] = true;
    return 1;
  }
  int su = 0, ma = 0;
  for(int i=0;i<SZ(tr[now]);++i) {
    int nxt = tr[now][i];
    if(nxt == prev) continue;
    if(d[now] == 2) zeroable[now] = zeroable[nxt];
    int res = sch(nxt, now, tr, zeroable, d);
    su += res;
    if(zeroable[nxt]) chmax(ma, res);
  }
  return (su - ma ? su - ma : su);
}

