int dfs(int now, int par) {
  int res = 0, len;
  vector<int> v;
  for (auto to : g[now])
    if (to != par) v.push_back(dfs(to, now));
  len = v.size();
  sort(v.begin(), v.end());
  if (len >= 2)
    for (int i = 1; i < len; ++i) v[i] = max(v[i], 1);
  for (auto p : v) res += p;
  return dp[now] = res;
}

int reroot(int now, int par) {
  int res = 0, one = 1e8, two = 1e8, len = g[now].size(), sum = 0, bf = dp[now];
  vector<int> id;
  for (int i = 0; i < len; ++i) {
    id.push_back(g[now][i]);
    sum += dp[g[now][i]];
  }
  sort(id.begin(), id.end(), [](int l, int r) { return dp[l] < dp[r]; });
  for (int i = 0; i < len; ++i) res += max(dp[id[i]], (int)(i != 0));
  sum = res;
  if (len == 2) sum = dp[id[0]] + dp[id[1]];
  for (int i = 0; i < len; ++i) {
    int to = g[now][i];
    if (to == par) continue;
    if (len == 1)
      dp[now] = 0;
    else if (len == 2)
      dp[now] = sum - dp[to];
    else {
      if (i == 0)
        dp[now] = sum - max(dp[to], 1) + dp[to];
      else
        dp[now] = sum - dp[to];
    }
    res = min(res, reroot(to, now));
  }
  dp[now] = bf;
  return res;
}

