    int max_at = -1, max_br = -1;
    rep(i, N) {
        if (br[i] > max_br) { max_at = i; max_br = br[i]; }
    }

    queue<int> q;
    vector<int> ord;
    q.push(max_at);
    vector<int> parent(N, -1), children(N, 0);
    vector<bool> visited(N, false);
    while(!q.empty()) {
        int u = q.front(); q.pop();
        visited[u] = true;
        ord.pb(u);
        for (int v : ne[u]) {
            if (visited[v]) continue;
            q.push(v);
            parent[v] = u;
            ++children[u];
        }
    }
#ifdef DEBUG
