    cout << "parent:" << parent << endl;
    cout << "children:" << children << endl;
#endif

    vector<int> val(N, 0);
    vector<vector<ii>> escal(N);
    rep(u, N) if (children[u] == 0) { val[u] = 1; escal[u].pb(ii(1, 0)); }
