    for (int i=N-1; i>=0; --i) {
        int v = ord[i];
        val[v] = 0;
        int l = 0;
        for (auto p : escal[v]) {
            val[v] += p.first;
            if (p.second == 1) l = 1;
        }
        if (children[v] >= 2) {
            for (ii p : escal[v]) {
                if (p.first == 1 && p.second == 0) {
                    val[v]--; break;
                }
            }
        }

        int u = parent[v];
        if (u != -1) {
            escal[u].pb(ii(val[v], (children[v]>=2)?1:l));
        }
    }
#ifdef DEBUG
    cout << endl;
    cout << "escal:" << escal << endl;
    cout << "val:" << val << endl;
#endif
    cout << val[max_at] << endl;

    return 0;
}

