int lca(int u , int v){
    if(h[u] < h[v])swap(u,v);
    for(int i = 0 ; (1 << i) <= (h[u] - h[v]) ; ++i){
        if(((h[u] - h[v]) >> i) & 1){
            u = P[u][i];
        }
    }
    if(u == v)return u;
    for(int i = logn - 1 ; i >= 0 ; --i){
        if(P[u][i] != P[v][i])u = P[u][i] , v = P[v][i];
    }
    return P[u][0];
}

