        g.add_edge(b, a);
    }
    if(n == 2){
        cout << 1 << endl;
        return 0;
    }
    Tree t;
    for(int i = 0; i < n; i++){
        if((int)g.g[i].size() >= 2){
            t.init(g, i);
            break;
        }
    }
    vector<P> v(n);
    for(int i = 0; i < n; i++) v[i] = P(t.dpt[i], i);
    sort(v.begin(), v.end(), greater<P>());
    bool b[100002];
    int ans = 0;
    for(int i = 0; i < n; i++){
        int u = v[i].second;
        if((int)t.t[u].size() == 0) b[u] = true;
        else if((int)t.t[u].size() == 1){
            if(b[t.t[u][0]]) b[u] = true;
            else b[u] = false;
        }
        else{
            int s = 0;
            for(int v : t.t[u]) if(b[v]) s++;
            ans += max(0, s - 1);
            b[u] = false;
        }
    }
    cout << ans << endl;
}

