    auto dfs = [&](auto&& self, const int s, const int p) -> void {
        int sum = 0, min = 0;
        for (const int to : T[s]) {
            if (to == p) { continue; }
            self(self, to, s);
            sum += dp1[to];
            if (dp0[to] != N) { chmin(min, dp0[to] - dp1[to]); }
        }
        const int nxt = sum + min;
        if (nxt == 0) {
            dp0[s] = nxt, dp1[s] = nxt + 1;
        } else {
            chmin(dp1[s], nxt);
        }
    };
