int DFS(int u, int p) {
	bool isZeroSubTree = false;
	for (auto v : Adj[u]) {
		if (v != p) {
			dp[u] += DFS(v, u);
			if (dp[v] == 0) {
				if (!isZeroSubTree) isZeroSubTree = true;
				else dp[u]++;
			}
		}
	}
	return dp[u];
}

