int get_leaf(int v, int p) {
  for (int u : adj[v])
    if (u != p)
      return get_leaf(u, v);
  return v;
}

int get_first_ant(int v, int p) {
  int nc = 0;
  for (int u : adj[v])
    if (u != p) {
      ++nc;
      int res = get_first_ant(u, v);
      if (res != -1)
        return res;
    }
  if (nc >= 2)
    return get_leaf((adj[v][0] != p ? adj[v][0] : adj[v][1]), v);
  return -1;
}

int solve(int v, int p) {
  int result = 0;
  int nc_without_ant = 0;
  for (int u : adj[v])
    if (u != p) {
      int res = solve(u, v);
      result += res;
      if (res == 0) ++nc_without_ant;
    }
  if (nc_without_ant >= 2)
    result += nc_without_ant - 1;
  return result;
}

