#include <bits/stdc++.h>
using namespace std;

const int N = 1e5 + 5;
const int INF = 1e9 + 5;
vector<int> adj[N];
int dp[N][2], vis[N][2];
int memo[N][2];
int n, ans, vis_id;
vector<int> _t, _d;

int solve(int idx, int flag) {
	if (idx == _t.size()) {
		if (_t.size() > 1 || !flag)
			return 0;
		return INF;
	}

	int &ret = dp[idx][flag];
	if (vis[idx][flag] == vis_id)
		return ret;
	vis[idx][flag] = vis_id;
	ret = INF;
	if (!flag) {
		ret = min(solve(idx + 1, 0) + _t[idx], solve(idx + 1, 1) + _d[idx]);
	} else {
		ret = solve(idx + 1, flag) + _t[idx];
	}
	return ret = min(ret, INF);
}

int dfs(int u, int par, int flag) {

	int &ret = memo[u][flag];
	if (~ret)
		return ret;

	vector<int> t, d;
	for (int nxt : adj[u]) {
		if (nxt == par)
			continue;
		t.push_back(dfs(nxt, u, 1));
		d.push_back(dfs(nxt, u, 0));
	}

	if (t.size() == 0)
		return ret = flag;

	if (!flag) {
		if (d.size() > 1)
			return ret = INF;
		return ret = d[0];
	}

	_t = t;
	_d = d;
	vis_id++;
	return ret = solve(0, 0);
}

int main() {

	memset(memo, -1, sizeof memo);
	int a, b;
	scanf("%d", &n);
	for (int i = 1; i < n; i++) {
		scanf("%d%d", &a, &b);
		adj[a].push_back(b);
		adj[b].push_back(a);
	}

	int best = 0, mx = adj[0].size();

	for (int i = 0; i < n; i++) {
		if (adj[i].size() > best) {
			best = i;
			mx = adj[i].size();

		}
	}

	printf("%d\n", max(1, dfs(best, -1, 1)));

	return 0;
}

