    for (int i=1; i<=n; ++i) if (g[i].size()>=3){
	    r=i;
	    break;
	}
    //cerr<<"RR"<<r<<endl;
    calc(r,0);
    //for (int i=1; i<=n; ++i) cout<<dp[i]<<" "; cout<<endl;
    dark(r,0);
