{
	scanf("%d",&n);
	int x,y;
	for(int i=1;i<n;i++)
	{
		scanf("%d %d",&x,&y);
		AddEdge(x,y);
		d[x]++,d[y]++;
	}
	for(int i=0;i<n;i++)
	{
		if(d[i]>=3)
		{
			root=i;
			break;
		}
	}
	if(root>MAXN)
	{
		printf("1\n");
		return 0;
	}
	dfs(root);
	printf("%d\n",dp[root]);
}

