        return st.size() == idist.size();

    }

    int solve() {
        int ans = N;
        for (int bit = 1; bit < 1 << N; ++bit) {
            if (check(bit)) {
                int tmp = __pop_count((unsigned) bit);
                chmin(ans, tmp);
            }
        }
        cout << ans << endl;
        return ans;
    }


};

vector<vector<Int>> make_tree(Int N) {
    UnionFind uf(N);
    vector<pair<int, int>> edge;
    for (int i = 0; i + 1 < N; ++i) {
        int x = 0, y = 0;
        while (uf.same(x, y)) {
            x = rand() % N;
            y = rand() % N;
        }
        uf.unite(x, y);
        edge.emplace_back(x, y);

    }

    vector<vector<Int>> tree(N);
    for (auto e : edge) {
        tree[e.first].push_back(e.second);
        tree[e.second].push_back(e.first);
    }

    return tree;
}

