	int c = 0, k = 0;
	for (int i = 0; i < e[v].size(); i++) {
		int w = e[v][i];
		if (w == p) continue;
		dfs(w, v);
		if (dp[w]) {
			k += dp[w];
		} else {
			c++;
		}
	}
	int cn = e[v].size();
	dp[v] = k;
	if (c > 0) {
		dp[v] += c - 1;
	} else {
		p = v;
	}
}
int dfs2(int v, int p = -1) {
	int c = 0, f = 0;
	for (int i = 0; i < e[v].size(); i++) {
		int w = e[v][i];
		if (w == p) continue;
		if (e[v].size() <= 2) {
			return dfs2(w, v);
		} else {
			f |= !dp[w];
		}
	}
	return c == 0 || f;
}
