int N;
vector<int> G[MAX_N];
int D[MAX_N];
int ans = 0;

int loop(int v, int p) {
	vi vp;
	rep(i, 0, sz(G[v])) {
		int n = G[v][i];
		if(n == p) continue;
		vp.pb(loop(n, v));
	}
	if(sz(vp) == 1) {
		return vp[0];
	}
	else if(sz(vp) >= 2) {
		int res = 0;
		rep(i, 0, sz(vp)) {
			res += vp[i] ^ 1;
		}
		ans += max(res - 1, 0);
		return 1;
	}
	else return 0;
}

