		D[a]++; D[b]++;
	}
	int root = -1;
	rep(i, 0, N) {
		if(D[i] >= 3) {
			root = i;
			break;
		}
	}
	if(root == -1) {
		cout << 1 << "\n";
	}
	else {
		loop(root, -1);
		cout << ans << "\n";
	}
}

