const int N = 1e5 + 10;
VI e[N];
int dp[N][2], leaf[N];

void dfs(int now, int past){
    leaf[now] = 1;
    int l = 0, d = 0;
    for (int next : e[now]){
        if (next == past) continue;
        dfs(next, now);
        leaf[now] &= leaf[next];
        if (leaf[next]) l++;
        d++;
    }
    if (d > 1) leaf[now] = 0;
    if (leaf[now]) return;
    for (int next : e[now]){
        if (next == past) continue;
        if (leaf[next]){
            dp[now][0]++;
            dp[now][1]++;
        }else{
            dp[now][0] += dp[next][1];
            dp[now][1] += dp[next][1];
        }
    }
    if (l) dp[now][1]--;
}

