vector<vi> dp;
ll calc(ll x, ll t){
    if (dp[x][t] !=-1)return dp[x][t];
    if (ch[x].size() == 0){
        dp[x][t] = t;
        return t;
    }
    if (ch[x].size()==1){
        dp[x][t] = calc(ch[x][0],t);
        return dp[x][t];
    }
    ll totsum = 0;
    for(auto c : ch[x]){
        totsum += calc(c,1);
    }
    ll rans = totsum;
    for(auto c : ch[x]){
        rans = min(rans, totsum-calc(c,1)+calc(c,0));
    }
    dp[x][t] = rans;
    return rans;
}


