int sz[maxn], par[maxn];
void dfs(int c, int p){
    par[c] = p;
    sz[c] = 1;
    for(int nxt : tr[c]){
        if(nxt == p) continue;
        dfs(nxt, c);
        sz[c] += sz[nxt];
    }
}
int solve(int c, int p){
    int leaves = 0, trr = 0;
    for(int nxt : tr[c]){
        if(nxt == p) continue;
        if(tr[nxt].size() == 1) leaves += 1;
        else trr += solve(nxt, c);
    }
    if(leaves > 1 || trr > 0) leaves--;
    return leaves + trr;
}
