const int Maxn = 100005;

int n;
vector <int> neigh[Maxn];
int root;
int dp[Maxn];

bool Solve(int v, int p = -1)
{
	int lins = 0, tot = 0;
	for (int i = 0; i < neigh[v].size(); i++) {
		int u = neigh[v][i];
		if (u == p) continue;
		tot++;
		lins += Solve(u, v);
		dp[v] += dp[u];
	}
	if (tot == 0 || tot == 1 && lins == 1) return true;
	if (lins > 0) dp[v] += lins - 1;
	return false;
}

