		neigh[b].push_back(a);
	}
	if (n == 2) { printf("1\n"); return 0; }
	root = 0;
	for (int i = 1; i < n; i++)
		if (neigh[i].size() > neigh[root].size()) root = i;
	Solve(root);
	printf("%d\n", dp[root]);
	return 0;
}

