void dfs1(int cur, int prev){
    vec[cur].erase(prev);
    is_linear[cur] = (vec[cur].size() <= 1);
    for(auto& next : vec[cur]) dfs1(next, cur), is_linear[cur] = (is_linear[cur] && is_linear[next]); }

