int find_v(vector<vector<int>> const& g, int v, int p) {
    if(g[v].size() > 2) {
        return v;
    } else if(g[v].size() == 1 && p != -1) {
        return v;
    } else {
        for(auto to : g[v]) {
            if(to != p) {
                return find_v(g, to, v);
            }
        }
    }
    return -1;
}

void dfs(vector<vector<int>> const& g, int v, int p, vector<int>& h, int d) {
    h[v] = d;
    for(auto to : g[v]) {
        if(to != p) {
            dfs(g, to, v, h, d + 1);
        }
    }
}

bool dfs2(vector<vector<int>> const& g, int v, int p, vector<bool>& put) {
    bool res = put[v];
    for(auto to : g[v]) {
        if(to != p) {
            res |= dfs2(g, to, v, put);
        }
    }
    return res;
}

int main() {
    int N; cin >> N;
    if(N == 1) {
        cout << 1 << endl;
        return 0;
    }
    vector<vector<int>> g(N);
    for(int i = 0; i < N - 1; ++i) {
        int a, b; cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    vector<int> leaf;
    for(int i = 0; i < N; ++i) {
        if(g[i].size() == 1) leaf.push_back(i);
    }
    int s = find_v(g, leaf[0], -1);
    if(g[s].size() == 1) {
        cout << 1 << endl;
        return 0;
    }
    vector<int> h(N);
    dfs(g, s, -1, h, 0);
    map<int, vector<int>> cnt;
    for(auto l : leaf) {
        cnt[h[l]].push_back(l);
    }
    int ans = 0;
    vector<bool> put(N);
    for(auto& p : cnt) {
        ans += p.second.size() - 1;
        for(int i = 0; i < (int)p.second.size() - 1; ++i) {
            put[p.second[i]] = true;
        }
    }
    dfs2(g, s, -1, put);
    for(auto to : g[s]) {
        ans += !put[to];
    }
    cout << ans - 1 << endl;
}

