#include <bits/stdc++.h>

using namespace std;

const int N = 100010;

int n;
int tot = -1, head[N];
struct Edge {
    int p, nxt;
    Edge(int p = 0, int nxt = 0) : p(p), nxt(nxt) {}
} edge[N * 2];
inline void Add(int u, int v) {
    edge[++tot] = Edge(v, head[u]);
    head[u] = tot;
    return;
}

int f[N], g[N], c[N];

void DFS1(int u, int fa) {
    for (int i = head[u]; ~i; i = edge[i].nxt) {
        int v = edge[i].p;
        if (v == fa) continue;
        DFS1(v, u);
        if (f[v]) g[u] += f[v];
        else ++c[u];
    }
    f[u] = g[u] + max(c[u] - 1, 0);
    return;
}

int res;

void DFS2(int u, int fa, int ff) {
    if (fa) res = min(res, g[u] + ff + max(c[u] + !ff - 1, 0));
    else res = min(res, f[u]);
    for (int i = head[u]; ~i; i = edge[i].nxt) {
        int v = edge[i].p;
        if (v == fa) continue;
        if (fa) DFS2(v, u, g[u] - f[v] + ff + max(c[u] - !f[v] + !ff - 1, 0));
        else DFS2(v, u, g[u] - f[v] + max(c[u] - !f[v] - 1, 0));
    }
    return;
}

int main() {
    scanf("%d", &n);
    if (n == 1) {
        puts("0");
        return 0;
    }
    memset(head, -1, sizeof(head));
    for (int i = 1; i < n; ++i) {
        int u, v;
        scanf("%d%d", &u, &v);
        ++u;
        ++v;
        Add(u, v);
        Add(v, u);
    }
    DFS1(1, 0);
    res = n;
    DFS2(1, 0, 0);
    printf("%d\n", res + 1);
    return 0;
}

