void dfs_par(int u)
{
	for (int v : edge[u])
	{
		if (v == parent[u])
		{
			continue;
		}
		parent[v] = u;
		dfs_par(v);
	}
}
void solve(int u)
{
	int lines = 0;
	for (int v : edge[u])
	{
		if (v == parent[u])
		{
			continue;
		}
		if (line[v])
		{
			lines++;
		}
		else
		{
			solve(v);
		}
	}
//	cerr << u << ' ' << lines << endl;
	ans += max(0, lines - 1);
}

