    }
    return -1;
}

int dfs(int s, int prev){
    int need = edge[s].size() - 1;
    int res = 0;
    if(s != prev){
        need--;
    }

    for(auto v: edge[s]){
        if(v == prev){
            continue;
        }
        int tmp = dfs(v, s);
        if(tmp > 0){
            need--;
        }
        res += tmp;
    }
    if(need > 0){
        res += need;
        if(root2 == -1){
            root2 = dfs2(s, prev);
        }
    }
    return res;
}

