const int N = 100005;
bool visited[N];
bool linear[N];
vector<int> v[N];
int ans[N], parent[N];

void dfs(int u)
{
    int pt, cnt = 0;
    ans[u] = 0;
    visited[u] = true;
    linear[u] = false;
    int lchild = 0;
    for(int i = 0; i<v[u].size(); i++)
    {
        pt = v[u][i];
        if(pt != parent[u])
        {
            cnt++;
            parent[pt] = u;
            dfs(pt);
            ans[u] += ans[pt];
            if(linear[pt])
                lchild++;
        }   
    }
    if(cnt == 0) // leaf
    {
        linear[u] = true;
        ans[u] = 1;
    }
    if(cnt == 1)
    {
        for(int i = 0; i<v[u].size(); i++)
        {
            pt = v[u][i];
            if(pt != parent[u])
                linear[u] = linear[pt];
        }
    }
    if(lchild > 1)
        ans[u]--;

    // cout << u-1 << " " << ans[u] << "\n";
    return;

}

