  // For performance.  We should not use C-style stdio functions
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
#endif
  cout << setprecision(20);

  int N; cin >> N;
  vector<int> A(N-1), B(N-1);
  vector<vector<int>> nbr(N);

  for (int i = 0; i < N-1; i++) {
    int a, b; cin >> a >> b;
    A.at(i) = a;
    B.at(i) = b;
    nbr.at(a).push_back(b);
    nbr.at(b).push_back(a);
  }

  auto branch = [&](int nd) -> int {
    auto nxt = [&](int& node, int& source) -> void {
      for (int x : nbr.at(node)) {
	if (x != source) {
	  source = node;
	  node = x;
	  return;
	}
      }
      throw MyException();
    };
    int src = -1;
    while (nbr.at(nd).size() <= 2) nxt(nd, src);
    return nd;
  };

  vector<int> brnum(N);
  int ans = 0;
  try {
    for (int i = 0; i < N; i++) {
      if (nbr.at(i).size() > 1) continue;
      int j = branch(i);
      brnum.at(j)++;
    }
    for (int i = 0; i < N; i++) {
      if (brnum.at(i) >= 2) ans += brnum.at(i) - 1;
    }
  } catch(const MyException& e) {
    ans = 1;
  }
  cout << ans << endl;

  return 0;
}

