void Calculate_Depth(vector<vector<int>>&edge, vector<int>&depth, int stnode) {
	depth[stnode] = 0;
	queue<int>Q;
	Q.push(stnode);
	while (!Q.empty()) {
		int cn = Q.front();
		Q.pop();
		for (auto i : edge[cn]) {
			if (depth[i] > depth[cn] + 1) {
				depth[i] = depth[cn] + 1;
				Q.push(i);
			}
		}
	}
	return;
}

void Search(vector<vector<int>>&edge, vector<int>&depth, int node, vector<int>&dp) {
	int sum = 0;
	int no = 0;
	for (auto i : edge[node]) {
		if (depth[i] < depth[node])continue;
		Search(edge, depth, i, dp);
		if (dp[i])sum += dp[i];
		else no++;
	}
	dp[node] = sum + max(0, no - 1);
}

