	Search(edge, depth, 0, dp);
	for (int i = 1; i < N; i++) {
		if (dp[0] == dp[i]) {
			dp[0]++;
			break;
		}
	}
	dp[0] = max(dp[0], 1);
	cout << dp[0] << endl;
	return 0;
}

