constexpr ll INF = (1LL << 30) - 1LL;
constexpr ll LINF = (1LL << 60) - 1LL;
constexpr ll MOD = 1e9 + 7;
template <typename T> void chmin(T &a, T b) { a = min(a, b); }
template <typename T> void chmax(T &a, T b) { a = max(a, b); }
vector<vector<int>> G;
vector<int> dp, sum, co;
void build(int i, int p) {
    for (auto &e : G[i]) {
        if (e == p) {
            continue;
        }
        build(e, i);
        sum[i] += dp[e];
        co[i] += (dp[e] == 0);
    }
    dp[i] = sum[i] + max(0, co[i] - 1);
}
int ans;
void calc(int i, int p) {
    // cout << i << " " << dp[i] << endl;
    chmin(ans, dp[i] + 1);
    for (auto &e : G[i]) {
        if (e == p) {
            continue;
        }
        int tdi = dp[i];
        int nsum = sum[i] - dp[e];
        int nco = co[i] - (dp[e] == 0);
        dp[i] = nsum + max(0, nco - 1);
        sum[e] += dp[i];
        co[e] += (dp[i] == 0);
        dp[e] = sum[e] + max(0, co[e] - 1);
        calc(e, i);
        dp[i] = tdi;
    }
}
