tuple<int,bool> dfs(const vector<vecint>& g,
    int i, int p = -1) {
  int res = 0;
  bool ok = true;
  int cch = 0;
  int ccz = 0;
  for (auto&& to : g[i]) {
    if (to == p) continue;
    ++cch;
    int cr, cz;
    tie(cr, cz) = dfs(g, to, i);
    if (!cz) ok = false;
    else {
      ++ccz;
      if (ccz > 1) ++cr;
    }
    res += cr;
  }
  if (cch > 1) ok = false;
  return make_tuple(res, ok);
}

