vector<int> edge[100010];
int dp[100010][2];
bool visited[100010][2];

int dfs(int from, int par, bool ant) {
	if(visited[from][ant]) {
		return dp[from][ant];
	}
	visited[from][ant] = true;
	if(edge[from].size() <= 2) {
		dp[from][ant] = ant;
		return dp[from][ant];
	}
	if(ant) {
		int sum = 0;
		for(int to : edge[from]) {
			if(to == par) continue;
			sum += dfs(to, from, true);
		}
		int ret = 1e9;
		for(int to : edge[from]) {
			if(to == par) continue;
			ret = min(ret, sum - dfs(to, from, true) + dfs(to, from, false));
		}
		dp[from][ant] = ret;
	} else {
		int ret = 0;
		for(int to : edge[from]) {
			if(to == par) continue;
			ret += dfs(to, from, false);
		}
		dp[from][ant] = ret;
	}
	return dp[from][ant];
}

