template <typename T,typename F0,typename F1>
struct rerooting{
	F0 func0;
	F1 func1;
	T init_value;

	vector<T> v;
	vector<T> ans;
	vector<bool> visited;

	rerooting(vector<vector<int>> &E,F0 f0,F1 f1,T iv):func0(f0),func1(f1){
		init_value = iv;
		v.resize(E.size());
		ans.resize(E.size());
		visited.resize(E.size(),false);
		for(int i=0;i<E.size();i++){
			if(visited[i])continue;
			dfs(E,i,-1);
			redfs(E,i,-1,init_value);
		}
	}

	void dfs(vector<vector<int>> &E,int now,int p){
		v[now] = init_value;
		for(int i=0;i<E[now].size();i++){
			int to = E[now][i];
			if(to==p)continue;
			dfs(E,to,now);
			v[now] = func0(v[now],v[to]);
		}
		v[now] = func1(v[now],now,p);
		visited[now]=true;
	}

	void redfs(vector<vector<int>> &E,int now,int p,T pv){
		vector<T> S(E[now].size(),init_value);
		if(S.size()>1){
			for(int i=S.size()-2;i>=0;i--){
				int to = E[now][i+1];
				T x = v[to];
				if(to==p)x = pv;
				S[i] = func0(x,S[i+1]);
			}
		}

		T temp = init_value;
		for(int i=0;i<E[now].size();i++){
			int to = E[now][i];
			if(to!=p){
				redfs(E,to,now,func1(func0(temp,S[i]),now,to));
				temp = func0(temp,v[to]);
			}
			else{
				temp = func0(temp,pv);
			}
		}
		ans[now] = func1(temp,now,p);
	}

};


int main(){

	int N;
	cin>>N;

	vector<vector<int>> E(N,vector<int>());
	vector<int> cnt(N,0);

	for(int i=0;i<N-1;i++){
		int a,b;
		cin>>a>>b;
		E[a].push_back(b);
		E[b].push_back(a);
		cnt[a]++;
		cnt[b]++;
	}

	auto f0 = [](pair<int,int> a,pair<int,int> b){
		a.first += b.first;
		a.second += b.second;
		if(b.first==0){
			if(a.second==0){
				a.second++;
			}
			else{
				a.first++;
			}
		}
		return a;
	};

	auto f1 = [](pair<int,int> a,int ind,int p){
		return make_pair(a.first,0);
	};

	rerooting<pair<int,int>,decltype(f0),decltype(f1)> rr(E,f0,f1,{0,0});

	int ans = 1000000;

	for(int i=0;i<N;i++){
		if(cnt[i]==1){
			ans = min(ans,rr.ans[i].first+1);
		}
	}

	cout<<ans<<endl;


