#include<bits/stdc++.h>
using namespace std;

const int MAXN = 100010;

inline int read() {
	int x = 0, f = 1;
	char ch = getchar();
	for(; !isdigit(ch); ch = getchar()) if(ch=='-') f=-1;
	for(; isdigit(ch); ch = getchar()) x = (x*10)+(ch^48);
	return x * f;
}

int n, st[MAXN], to[MAXN<<1];
int nxt[MAXN<<1], e;
inline void Add(int u, int v) {
	to[++e] = v, nxt[e] = st[u];
	st[u] = e;
}

int dp[MAXN], deg[MAXN];
bool isc[MAXN];

void dfs(int u, int fa) {
	int i, sn = 0;
	for(i = st[u]; i; i = nxt[i]) {
		if(to[i] == fa) continue;
		dfs(to[i], u), sn++;
	}
	if(sn == 0) dp[u] = isc[u] = 1;
	else if(sn == 1) {
		for(i = st[u]; i; i = nxt[i]) {
			if(to[i] == fa) continue;
			dp[u] = dp[to[i]];
			isc[u] = isc[to[i]];
		}
	}
	else {
		for(i = st[u]; i; i = nxt[i]) {
			if(to[i] == fa) continue;
			isc[u] |= isc[to[i]];
			dp[u] += dp[to[i]];
		}
		if(isc[u]) dp[u]--, isc[u] = false;
	}
}

int root;

int main() {

	int i;
	n = read();
	for(i = 1; i < n; i++) {
		int u = read()+1, v = read()+1;
		Add(u, v), Add(v, u);
		deg[u]++, deg[v]++;
	}
	for(i = 1; i <= n; i++)
		if(deg[i] >= 3) { root = i; break; }
	if(i > n) {
		printf("1\n");
		return 0;
	}
	dfs(root, 0);
	printf("%d\n", dp[root]);
	return 0;
}

