		printf("%d\n", 1);
		return 0;
	}
	vector<int> v[100000];
	for(int i=0; i<n-1; i++){
		int a, b;
		scanf("%d %d", &a, &b);
		v[a].push_back(b);
		v[b].push_back(a);
	}
	int i0=-1;
	for(int i=0; i<n; i++){
		if(v[i].size()>2){
			i0=i;
			break;
		}
	}
	if(i0==-1){
		printf("%d\n", 1);
	}
	int d[100000];
	fill(d, d+n, -1);
	d[i0]=0;
	queue<int> que;
	que.push(i0);
	while(!que.empty()){
		int x=que.front();
		que.pop();
		for(int i=0; i<v[x].size(); i++){
			if(d[v[x][i]]<0){
				d[v[x][i]]=d[x]+1;
				que.push(v[x][i]);
			}
		}
	}
	vector<P> dist;
	for(int i=0; i<n; i++){
		dist.push_back(P(-d[i], i));
	}
	sort(dist.begin(), dist.end());
	int e[100000]={};
	int ans=0;
	for(int i=0; i<n; i++){
		int x=dist[i].second;
		int count=0;
		for(int j=0; j<v[x].size(); j++){
			if(d[v[x][j]]<d[x]) continue;
			if(e[v[x][j]]==1){
				e[x]=1;
				continue;
			}
			count++;
		}
		if(count>1){
			ans+=(count-1);
			e[x]=1;
		}
	}
	printf("%d\n", ans);
	return 0;
}

