int isLine(int pos,int pre,bool init = 0){
  static int mem[N],used[N]={};
  if(init) {memset(used,0,sizeof(used));return 0;}
  if(G[pos].size() > 2) return 0;
  if(pre != -1 && G[pos].size() == 1) return 1;
  if(used[pos]++) return mem[pos];
  if(G[pos][0] != pre) return mem[pos] = isLine(G[pos][0],pos);
  if(G[pos][1] != pre) return mem[pos] = isLine(G[pos][1],pos);
  assert(0);
}

int root;
int dfs(int pos,int pre){
  int line = 0;
   int res = 0;
   for(int to:G[pos]){
     if(to == pre) continue;
     if(isLine(to,pos)) line++;
     else res += dfs(to,pos);
   }
   if(pos == root && G[pos].size() == 2 && line == 1) res ++;
   else if(line >= 2) res += line-1;
   return res;
}

