pair<int, int> dfs(int cur, int pre, vector<vector<int>>& g) {
	int ret = 0, cnt = 0;
	for (auto& next : g[cur]) {
		if (next == pre) continue;
		auto p = dfs(next, cur, g);
		ret += p.first;
		cnt += p.first != 0;
	}
	int inc = max(0, (int)g[cur].size() - 2 - cnt);
	// cout << cur << ": " << inc << endl;
	return make_pair(ret + inc, inc);
}

