void dfs(int v,int p){
    int childs = 0;
    used[v] = true;
    for(int i=0;i<(int)g[v].size();i++){
        int to = g[v][i];
        if(to == p)continue;
        dfs(to , v);
        used[v] &= used[to];
        childs++;
    }
    if(childs > 1){
        used[v] = false;
    }
}

