// root is not leaf!!!

int single_leafs[MAX_N];
bool have_radio[MAX_N];


void clear() {
  ans = 0;
  memset ( single_leafs , 0 , sizeof single_leafs );
  memset ( have_radio , 0 , sizeof have_radio );
}

void DFS( int v , int p = -1 ) {


  int soons_cnt = 0;

  for ( auto x : neib[v] ) {
    if ( x != p ) {
      soons_cnt++;
      DFS ( x , v );
      have_radio[v] = have_radio[v] or have_radio[x];

      if ( !have_radio[x] and ( single_leafs[x] == 1 ) )
        single_leafs[v] += single_leafs[x];
    }
  }

  if ( soons_cnt == 0 ) {
    // this is leaf
    single_leafs[v] = 1;
  }


  //cout << "DFS(" << v << "," << p <<  ") " << single_leafs[v] << " sl;ans " << ans << endl;

  if ( single_leafs[v] > 1 ) {
    ans += single_leafs[v] - 1;
    single_leafs[v] = 0;
    have_radio[v] = true;
  }

}

