inline void Add(int x, int y) {
    a[++tot] = y; ne[tot] = fi[x]; fi[x] = tot;
}
inline void Dp(int x, int fa) {
    int cnt = 0;
    for (int i = fi[x]; i; i = ne[i]) if (a[i] != fa) {
        Dp(a[i], x);
        ++cnt;
    }
    if (cnt == 0) {
        f[x] = 0;
    } else if (cnt == 1) {
        for (int i = fi[x]; i; i = ne[i]) if (a[i] != fa) f[x] = f[a[i]];
    } else {
        bool have_lian_son = 0;
        for (int i = fi[x]; i; i = ne[i]) if (a[i] != fa) {
            f[x] += max(f[a[i]], 1);
            if (!f[a[i]]) have_lian_son = 1;
        }
        f[x] -= have_lian_son;
    }
}
