void dfs(int now, int lst)
{
	for (int i = 0; i < SZ(nei[now]); i++)
	{
		int j = nei[now][i];
		if (j == lst)continue;
		dfs(j, now);
	}
	vector<int> t;
	int s = 0;
	for (int i = 0; i < SZ(nei[now]); i++)
	{
		int j = nei[now][i];
		if (j == lst)continue;
		t.pb(dp[j]);
		s += dp[j];
	}
	if (lst != -1)
	{
		int c = 0;
		for (int i = 0; i < SZ(t); i++)if (!t[i])c++;
		dp[now] = s + max(c - 1, 0);
	}
	else
	{
		int c = 0;
		for (int i = 0; i < SZ(t); i++)if (!t[i])c++;
		dp[now] = s + max(c - 1, 0);
	}
}

