int dfs(int v,int p){
  // cout<<v<<' '<<p<<endl;
  int ch=g[v].size()-(p>=0);
  int res=0;
  pth[v]=2;
  int nonpaths=0;
  for(int w:g[v]){
    if(w==p) continue;
    int k=dfs(w,v);
    if(!pth[w]) pth[v]=0;
    if(!pth[w]) nonpaths++;
    pth[v]--;
    res+=k;
  }
  pth[v]=(pth[v]>=1);
  if(res==0) res=1;
  if((nonpaths || v==0) && ch>=2) res--;

  // cout<<v<<' '<<res<<'\n';
  return res;
}

