int n,head[100005],tot,ans,son[100005],vis[100005],q;
struct edge
{
	int v,nxt;
}edg[200005];
void addedg(int u,int v)
{
	edg[tot].v = v;
	edg[tot].nxt = head[u];
	head[u] = tot++;
	++son[u];
}
void dfs(int k,int fa)
{
	int temp = 0,x = 0;
	for(int i = head[k];i != -1;i = edg[i].nxt)
	{
		if(edg[i].v != fa)
		{
			dfs(edg[i].v,k);
			if(!vis[edg[i].v])
				++temp;
			else if(vis[edg[i].v] == 1)
			{
				vis[k] = 2;
				q = 1;
				++x;
			}
			else
			{
				++x;
				vis[k] = 2;
				q = 1;
			}
		}
	}
	if(temp >= 2)
	{
		ans += temp-1;
		vis[k] = 1;
		q = 0;
	}
	if(x >= 2)
		q = 0;

}
int main()
{
	while(~scanf("%d",&n))
	{
		int u,v;
		memset(head,-1,sizeof(int)*(n+1));
		memset(son,0,sizeof(int)*(n+1));
		tot = 0;
		for(int i = 1;i < n;++i)
		{
			scanf("%d%d",&u,&v);
			addedg(u,v);
			addedg(v,u);
			vis[i] = 0;
		}
		vis[0] = 0;
		ans = 0;
		q = 0;
		int root=-1;
		for(int i = 0;i < n;++i)
			if(son[i] != 1)
			{
				root = i;
				break;
			}
		if(root!=-1)
		{
			dfs(root,root);
			printf("%d\n",ans+q);
		}
		else
			printf("1\n");
	}
	return 0;
}

