int dfs(const GraphI& g, int i, int par) {
	int ans = 0, zero = 0;
	for(auto& p : g.e[i]) {
		int j = p.first;
		if(j != par) {
			int a = dfs(g, j, i);
			ans += a;
			if(a == 0) ++zero;
		}
	}
	return ans + max(zero - 1, 0ll);
}

