#include <cassert>
#include <cstdio>
#include <vector>

using namespace std;

int
main()
{
    int N;
    assert(scanf("%d", &N) == 1);
    vector<int> trav[N];
    int M = N - 1;
    for (int i = 0; i < M; i++) {
        int n1, n2;
        assert(scanf("%d %d", &n1, &n2) == 2);
        trav[n1].push_back(n2);
        trav[n2].push_back(n1);
    }

    // If there is a branch and it has two or more leaves,
    // we need a antenna.
    vector<int> leafy_path(N, 0);
    for (int i = 0; i < N; i++) {
        // Find a tip of a leaf.
        if (trav[i].size() == 0)
            leafy_path[i] = 2;
        if (trav[i].size() != 1)
            continue;
        // Trace it to the branch point.
        int prev = i;
        int cur = trav[i][0];
        while (trav[cur].size() == 2) {
            if (trav[cur][0] == prev) {
                prev = cur;
                cur = trav[cur][1];
            } else {
                prev = cur;
                cur = trav[cur][0];
            }
        }
        // Count leafy path on the branch.
        if (trav[cur].size() == 1) {
            // Non-branching path is special.
            // Treat the yonger node as a branch point.
            if (i < cur)
                leafy_path[i] = 2;
        } else {
            leafy_path[cur]++;
        }
    }

    // Count the answer.
    int ans = 0;
    for (int i = 0; i < N; i++) {
        if (leafy_path[i] >= 2)
            ans += leafy_path[i] - 1;
    }
    printf("%d\n", ans);
}

