// 移動元と行先と辺のコストを記録する構造体
template <typename T>
struct Edge {
    int from, to;
    T cost;
    Edge(int s, T d) : to(s), cost(d) {}
    Edge(int f, int s, T d) : from(f), to(s), cost(d) {}

    bool operator<(const Edge &e) const {
        return cost < e.cost;
    }
    bool operator>(const Edge &e) const {
        return cost > e.cost;
    }
};

template <typename T>
using Graph = vector< vector< Edge<T> > >;

template <typename T>
void getDeepest(pair<int, T> &n, vector< vector< Edge<T> > > &G, int p, int prev, T cost) {
    int ok = true;
    for(auto x : G[p]) {
        if(x.to != prev) {
            ok = false;
            getDeepest(n, G, x.to, p, cost+x.cost);
        }
    }
    if(ok && n.second < cost) {
        n.first = p;
        n.second = cost;
    }
}

// 補足: これを使用すると木の直径が求められる。
// 1. 適当な頂点を選びDFSを適用する
// 2. 1 で返ってきた頂点に対してDFSを適用する
// 3. 1 で返った頂点と 2 で返った頂点が直径の候補の一つになる。

// 使用例
// この場合は p.fr と r.fr が直径の候補の一つであり、その大きさは r.sc である。

int depth[100010], used[100010], parent[100010], cnt[100010];
Graph<int> G;

void reset_array() {
    memset(depth, 0, sizeof(depth));
    memset(used, 0, sizeof(used));
    memset(parent, 0, sizeof(parent));
    memset(cnt, 0, sizeof(cnt));
}

void init(int cur, int d=0, int prev=-1) {
    depth[cur] = d;
    parent[cur] = prev;
    cnt[d]++;
    for(auto e : G[cur]) {
        if(e.to == prev) continue;
        init(e.to, d+1, cur);
    }
}

int solve() {
    int max_height = 0;
    int ans = 1;

    bool ok = false;
    rep(i,0,100010) if(cnt[i]) {
        max_height = i;
        ok |= (cnt[i] > 1);
    }

    if(!ok) {
        return 1;
    }

    while(1) {
        int height = max_height;
        ans++;
        while(height >= 0) {
            if(--cnt[height] <= 1 && max_height == height) {
                max_height--;
            }
            height--;
        }
        if(max_height <= 0) break;
    }
    return ans;
}

signed main() {
    int N; cin >> N;
    G.resize(N);

    rep(i,0,N-1) {
        int a, b; cin >> a >> b;
        G[a].push_back(Edge<int>(b, 1));
        G[b].push_back(Edge<int>(a, 1));
    }

    pii p = pii(0, 0), r = pii(0, 0);
    getDeepest<int>(p, G, 0, -1, 0);
    getDeepest<int>(r, G, p.first, -1, 0);

    int ans = INF;
    reset_array();
    init(r.first);
    ans = min(ans, solve());

    reset_array();
    init(p.first);
    ans = min(ans, solve());
    cout << ans << endl;
    return 0;
}

