    if(dub[x] > dub[bst])
        bst = x;
    for(int i = 0;i<v[x].size();i++)
        if(v[x][i] != lst)
            findroot(v[x][i], x);
}

void findlan(int x,int lst){
    lan[x] = 0;
    int lncnt = 0,a = 0,b = 0;
    for(int i = 0;i<v[x].size();i++){
        if(v[x][i] == lst) continue;
        findlan(v[x][i], x);
        a += lan[v[x][i]];b++;
    }
    if(a == 1 && b == 1) lan[x] = 1;
    if(b == 0) lan[x] = 1;
}

int solve(int x,int lst){
    int lncnt = 0,ret = 0;
    for(int i = 0;i<v[x].size();i++){
        if(v[x][i] == lst) continue;
        if(lan[v[x][i]]) lncnt++;
        else ret += solve(v[x][i], x);
    }
    if(lncnt) lncnt--;
    return ret + lncnt;
}

