const int MAXcomb = 200010;
ll fac[MAXcomb], finv[MAXcomb], inv[MAXcomb];
//facはn!,finvは1/n!
//invは逆元
void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAXcomb; i++){
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
        finv[i] = finv[i-1] * inv[i] % MOD;
    }
}
ll comb(int n, int k){
    if(n < k) return 0;
    if(n < 0 || k < 0) return 0;
    return fac[n] * finv[k] % MOD * finv[n-k] % MOD;
}

vector<ll> E[100010];
ll solve(ll now, ll from){
  ll res = 0;
  ll dont = 0;
  for(ll to : E[now]){
    if(to == from) continue;
    ll add = solve(to, now);
    res += add;
    if(add == 0) dont++;
  }
  ll c = E[now].size() - 1;
  if(dont >= 2){
    res += (dont-1);
  }
  return res;
}

