ll const MAX = 1e5 + 5;

vvll G(MAX);
vll dp(MAX);
vll visited(MAX);


void dfs(ll cur) {
	visited[cur] = 1;
	ll non_antena = 0;
	ll cnt = 0;
	for (auto next : G[cur]) {
		if (visited[next] == 1) {
			continue;
		}
		dfs(next);
		cnt += dp[next];
		if (dp[next] == 0) {
			non_antena++;
		}
	}
	if (non_antena > 1) {
		cnt += non_antena - 1;
	}
	dp[cur] = cnt;
	//cout << cur << " " << cnt << endl;
}

int main() {
