		G[a].push_back(b);
		G[b].push_back(a);
	}
	ll start = -1;
	REP(i, 0, n - 1) {
		if (SIZE(G[i]) >= 3) {
			start = i;
		}
	}	
	if (start == -1) {
		cout << 1 << endl;
		return 0;
	}

	dfs(start);
	if (dp[start] == 0) {
		cout << 1 << endl;
	}
	else {
		cout << dp[start] << endl;
	}
}

