int dfs (int now, int par) {
	int ch = 0, dpt = 0;
	for (auto nex : adj[now]) {
		if (nex==par) continue;
		dpt += dfs (nex,now);
		ch++;
	}
	ch--;
	if (ch) {
		if (dpt<ch) {
			ans += ch-dpt;
			dpt = ch;
		} else if (now==root && dpt==1 && ch==1) ans++;
	} else if (now==root) ans++;
	if (dpt) return 1;
	else return 0;
}

