constexpr lint mod = 1000000007;
constexpr lint INF = mod * mod;
constexpr int MAX = 100010;

int n;
vector<int> G[MAX];
int dp[MAX][2];

void dfs(int v, int pv){
    if((int)G[v].size() == 1){
        dp[v][0] = 0;
        dp[v][1] = 1;
        return;
    }
    else if((int)G[v].size() == 2){
        for(int nv: G[v])if(nv != pv){
            dfs(nv, v);
            if(dp[nv][0] == 0){
                dp[v][0] = 0;
                dp[v][1] = 1;
            }
            else{
                dp[v][1] = dp[nv][1];
            }
        }
        return;
    }
    int sum = 0, diff_min = mod;
    for(auto nv: G[v])if(nv != pv){
        dfs(nv, v);
        sum += dp[nv][1];
        chmin(diff_min, dp[nv][0] - dp[nv][1]);
    }
    dp[v][1] = min(sum, sum + diff_min);
    return;
}

