		return memo[v] = 0;

	for (auto i : g[v])
		if (i != p)
			return memo[v] = dfs0(i, v);

	return memo[v] = 1;
}

int dfs2(int v, int p = -1)
{
	int res = 0;
	bool ye = 0;
	for (auto i : g[v])
		if (i != p)
			ye |= dfs0(i, v);

	int cnt = 0;
	for (auto i : g[v])
	{
		if (i == p)
			continue;

		if (memo[i] == 1)
			continue;

		++cnt;
	}

	for (auto i : g[v])
	{
		if (i == p)
			continue;

		if (memo[i] == 1)
			continue;

		res += max(1, dfs2(i, v));
	}

	res -= ye;
	return res;
}

int dfs(int v, int p = -1)
{
