void dfs(int v, int par = -1) {
  dp[v][1] = 0;
  dp[v][0] = 0;
  kosong[v] = 1;
  int child = 0;
  for (int u : g[v]) if (u != par) {
    dfs(u, v);
    int one = dp[v][1] + dp[u][1], zero = dp[v][0] + dp[u][1];
    if (kosong[u])
      one = min(one, dp[v][0]);
    dp[v][1] = one;
    dp[v][0] = zero;
    ++child;
  }
  if (child > 1)
    kosong[v] = 0;
  dp[v][1] = max(dp[v][1], 1);
  dp[v][0] = max(dp[v][0], 1);
}

