    G[b].push_back(a);

  }

  if (n == 2) {
    cout << 1 << endl;
    return 0;
  }

  for (int a = 0; a < n; ++a) {
    add_key(a, -1);
    for (auto b : G[a]) {
      add_key(a, b);
    }
  }

  dp.resize(300005);
  for (auto &v : dp) {
    v.resize(2);
    for (auto &x : v) {
      x = -1;
    }
  }

  int ans = INT_MAX;
  for (int i = 0; i < n; ++i) {
    if (G[i].size() == 1) {
      int tmp = count(i, -1, 0, G) + 1;
      ans = min(ans, tmp);
      // D(i); D(tmp);
    }
  }

  cout << ans << endl;

  return 0;
}

