void DFS(int a, int pp) {
	int i;
	for (i = 0; i < E[a].size(); i++) {
		int x = E[a][i];
		if (x == pp)continue;
		DFS(x, a);
	}
	vector<int>T;
	int s = 0;
	for (i = 0; i < E[a].size(); i++) {
		int x = E[a][i];
		if (x == pp)continue;
		T.push_back(D[x]);
		s += D[x];
	}
	if (!pp) {
		int c = 0;
		for (i = 0; i < T.size(); i++)if (T[i])c++;
		if (T.size() == 3) {
			if (c < 2) {
				D[a] = s + 2 - c;
			}
			else D[a] = s;
		}
		else {
			if (c < 3) {
				D[a] = s + 3 - c;
			}
			else D[a] = s;
		}
		return;
	}
	if (T.size()<=1) {
		D[a] = s;
		return;
	}
	if (T.size() == 2) {
		if (T[0] == 0 && T[1] == 0)D[a] = 1;
		else D[a] = s;
		return;
	}
	else {
		int c = 0;
		for (i = 0; i < T.size(); i++)if (T[i])c++;
		if (c < 2) {
			D[a] = s + 2 - c;
		}
		else D[a] = s;
	}
}
