int memo[ten(5)];
int zeroPenalty[ten(5)];

int dfs(int v, int par) {
	int zeroCnt = 0;
	int ret = 0;
	for (auto to : e[v]) {
		if (to == par) continue;
		int val = dfs(to, v);
		if (val == 0) zeroCnt++;
		else ret += val;
	}
	ret += max(zeroCnt - 1, 0);
	if (zeroCnt && par >= 0) {
		zeroPenalty[v] = 1;
	}
	return memo[v] = ret;
}

