	PII ret = {0, 0};
	REP(i, G[v].size()){
		if(G[v][i] == p) continue;
		PII r = dfs(G[v][i], v);
		if(r.sc == 0){
			cnt++;
			ret.fs += r.fs;
		}else{
			ret.sc = 1;
			ret.fs += r.fs;
		}
	}
	if(cnt) ret.fs--;
	if(ret.fs == 0 && ret.sc == 0)
		ret.fs = 1;
	if(G[v].size()-(p!=-1) > 1)
		ret.sc = 1;
	return ret;
}

