		G[v].push_back(u);
	}
	REP(i, N){
		if(G[i].size() > 2){
			root = i;
			break;
		}
	}
	if(root == -1){
		cout << 1 << endl;
		return 0;
	}
	cout << dfs(root, -1).fs << endl;
	return 0;
}

