using namespace std;

const int N = 100 * 1000 + 10;

int n, ans;
int par[N];
bool Simple[N];
vector <int> adj[N];

void input() {
    cin >> n;

    int u, v;
    for (int i = 0; i < n - 1; i++) {
        cin >> u >> v;
        adj[v].push_back(u);
        adj[u].push_back(v);
    }
    return;
}

void PrePros(int &v) {
    bool res = true;
    for (int i = 0; i < adj[v].size(); i++)
        if (adj[v][i] != par[v]) {
            par[adj[v][i]] = v;
            PrePros(adj[v][i]);
            res &= Simple[adj[v][i]];
        }

    if (res && adj[v].size() <= 2)
        Simple[v] = true;
    return;
}

void DFS(int &v) {
    if (adj[v].size() == 1) {
        ans++;
        return;
    }

    bool ignore = true;
    for (int i = 0; i < adj[v].size(); i++)
        if (adj[v][i] != par[v])
            if (ignore && Simple[adj[v][i]] && adj[v].size() > 2)
                ignore = false;
            else
                DFS(adj[v][i]);
    return;
}

void solve() {
    for (int i = 0; i < n; i++)
        if (adj[i].size() > 2) {
            par[i] = -1;

            PrePros(i);
            Simple[i] = false;

            DFS(i);
            return;
        }

    ans = 1;
    return;
}

int main() {
    input();
    solve();
    cout << ans << endl;
    return 0;
}

