void dfs(int now, int lst)
{
	dp[now] = 0;
	if (SZ(nei[now]) == 1)
		return;
	int bb = 0;
	for (int i = 0; i < SZ(nei[now]); i++)
	{
		int j = nei[now][i];
		if (j != lst)
		{
			dfs(j, now);
			dp[now] += dp[j];
			if (dp[j] != 0)bb++;
		}
	}
	dp[now] += max(SZ(nei[now]) - bb - 2, 0);
	if (lst == -1)dp[now]++;
	if (dp[now] == 0)dp[now] = 1;
}

