struct Graph{
    struct Node{
        vector<int> dests;
    };
    vector<Node> nodes;
    Graph(int num): nodes(num){ }
    int id(Node* n){ return n - &nodes[0]; }
    int id(Node& n){ return &n - &nodes[0]; }
    void print(){ for(auto& node : nodes){ prints(id(node), node.dests); } }
    void addEdge(int from, int dest){
        nodes[from].dests.push_back(dest);
    }
    void addEdge2(int from, int dest){
        addEdge(from, dest);
        addEdge(dest, from);
    }
    int dfs(int idx, int from = -1){
        vector<int> rets;
        for(int didx : nodes[idx].dests){
            if(didx == from){ continue; }
            rets.push_back(dfs(didx, idx));
        }
        if(rets.empty()){
            return 0;
        }else{
            sort(rets.begin(), rets.end());
            int ret = 0;
            for(size_t i = 0; i < rets.size(); i++){
                ret += max(int(bool(i)), rets[i]);
            }
            return ret;
        }
    }
};

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n; cin >> n;
    Graph g(n);
    for(int i = 0; i < n - 1; i++){
        int a, b;
        cin >> a >> b;
        g.addEdge2(a, b);
    }
    int idx, maxi = 0;
    for(int i = 0; i < n; i++){
        if(maxi < (int)g.nodes[i].dests.size()){
            maxi = g.nodes[i].dests.size();
            idx = i;
        }
    }
    cout << max(1, g.dfs(idx)) << '\n';
}

