int n,m,d[1000010],f[1000010],ans;
vector<int>g[1000010];

void dfs(int x,int fa)
{
	d[x]=0;
	for(int i=0; i<g[x].size(); i++)
	{
		int y=g[x][i];
		if(y==fa)continue;
		dfs(y,x);
		d[x]+=!f[y];
		f[x]+=f[y];
	}
	if(d[x])f[x]+=d[x]-1;
}

void sol(int x,int fa)
{
	if(g[x].size()==1)ans=min(ans,f[x]+1);
	for(int i=0; i<g[x].size(); i++)
	{
		int y=g[x][i];
		if(y==fa)continue;
		f[x]-=f[y];
		if(!f[y]&&--d[x])f[x]--;
		f[y]+=f[x];
		if(!f[x]&&d[y]++)f[y]++;
		sol(y,x);
		if(!f[x]&&--d[y])f[y]--;
		f[y]-=f[x];
		if(!f[y]&&d[x]++)f[x]++;
		f[x]+=f[y];
	}
}

