int f(int v, int parent, bool has_antennas)
{
    if (edges[v].size() == 1) {
        if (has_antennas) {
            return 1;
        } else {
            return 0;
        }
    } else if (edges[v].size() == 2) {
        for (int child: edges[v]) {
            if (child != parent) {
                return f(child, v, has_antennas);
            }
        }
    } else {
        if (!has_antennas) {
            return IMPOSSIBLE;
        }
        int s = 0;
        int m = INT_MAX;
        for (int child: edges[v]) {
            if (child == parent) {
                continue;
            }
            s += f(child, v, true);
            amin(m, f(child, v, false) - f(child, v, true));
        }
        return min(s, s + m);
    }
}

