void DFS(int u , int par){
    for(int c : adj[u]){
        if(c != par){
            h[c] = h[u] + 1;
            P[c][0] = u;
            for(int i = 1 ; P[P[c][i - 1]][i - 1] != 0 ; ++i){
                P[c][i] = P[P[c][i - 1]][i -  1];
            }
            DFS(c , u);
        }
    }
}

int lca(int u , int v){
    if(h[u] < h[v])swap(u,v);
    for(int i = 0 ; (1 << i) <= (h[u] - h[v]) ; ++i){
        if(((h[u] - h[v]) >> i) & 1){
            u = P[u][i];
        }
    }
    if(u == v)return u;
    for(int i = logn - 1 ; i >= 0 ; --i){
        if(P[u][i] != P[v][i])u = P[u][i] , v = P[v][i];
    }
    return P[u][0];
}

