ll dfs1(ll now, ll par, Graph &G, vector<ll> &cnt){
	ll res = 0;
	if((int)G[now].size()>2) res++;
	for(auto next: G[now]){
		if(next == par) continue;
		res += dfs1(next, now, G, cnt);
	}
	cnt[now] = res;
	return res;
}

ll tot = 0;

void dfs2(ll now, ll par, Graph &G, vector<ll> &cnt){
	ll res = 0;
	for(auto next: G[now]){
		ll val;
		if(next == par){
			val = cnt[0] - cnt[now];
		}else{
			val = cnt[next];
			dfs2(next, now, G, cnt);
		}
		if(val>0) res++;
	}
	tot += max((int)G[now].size() - 1 - res, 0ll);
	return;
}

