void dfs(int now, int lst)
{
	int bb = 0, cc = 0;
	for (int i = 0; i < SZ(nei[now]); i++)
	{
		int j = nei[now][i];
		if (j != lst)
		{
			cc++;
			dfs(j, now);
			dp[now] += dp[j];
			if (dp[j] != 0)bb++;
		}
	}
	dp[now] += max(cc - bb - 1, 0);
	if (cc == 1 && dp[now] == 0)dp[now] = 1;
}

