int N;
vector<int> edge[MAXN];
int parent[MAXN];
bool line[MAXN];
int ans;

void dfs_par(int u)
{
	if (edge[u].size() > 2)
	{
		line[u] = false;
	}
	for (int v : edge[u])
	{
		if (v == parent[u])
		{
			continue;
		}
		parent[v] = u;
		dfs_par(v);
		if (!line[v])
		{
			line[u] = false;
		}
	}
}
void solve(int u)
{
	int lines = 0;
	for (int v : edge[u])
	{
		if (v == parent[u])
		{
			continue;
		}
		if (line[v])
		{
			lines++;
		}
		else
		{
			solve(v);
		}
	}
//	cerr << u << ' ' << lines << endl;
	ans += max(0, lines - 1);
}

