void dfs(int c, int p){
    par[c] = p;
    sz[c] = 1;
    for(int nxt : tr[c]){
        if(nxt == p) continue;
        dfs(nxt, c);
        sz[c] += sz[nxt];
    }
}
int dx[maxn], dy[maxn], dz[maxn], ans[maxn];
int solve(int c, int p){
    int num_leafs = 0;
    int num_trees = 0;
    int sum_trees = 0;
    int non_leaf = -1;
    for(int nxt : tr[c]){
        if(nxt == p) continue;
        if(tr[nxt].size() == 1) num_leafs++;
        else{
            num_trees++;
            sum_trees += solve(nxt, c);
            non_leaf = nxt;
        }
    }
    dx[c] = num_leafs;
    dy[c] = num_trees;
    dz[c] = sum_trees;
    if(num_trees == 0){
        return ans[c] = max(num_leafs - 1, 1);
    } else if(num_trees == 1){
        if(dx[non_leaf] >= 1){
            return ans[c] = sum_trees + max(num_leafs - 1, 0) + 1;
        } else {
            return ans[c] = sum_trees + max(num_leafs - 1, 0);
        }
    } else {
        return ans[c] = sum_trees + max(num_leafs - 1, 0);
    }
}
