class LCA{

  int root;
  //depth of node[i]
  vector<int> d;

  //parent of node[i]
  vector<vector<int> > p;


  int size;

  //initialization of depths and parents
  void init(vector<vector<int> > &g, int pos, int last, int v){
    d[pos] = v;
    p[0][pos] = last;
    for(int i=0; i<g[pos].size(); i++){
      if(g[pos][i] == last) continue;
      init(g, g[pos][i], pos, v+1);
    }
  }

 public:

  //vector<vector<int> >
  //g[i][j] := node[i]'s edge gose to node[ g[i][j] ]

  void initialize(vector<vector<int> > &g, int r){
    int n = g.size();
    root = r;
    d = vector<int>(n);

    size = 1;
    while((1<<size) <= n){
      size++;
    }

    p = vector<vector<int> >(size, vector<int>(n));

    init(g, root,-1,0);

    for(int k=0; k+1 < size; k++){
      for(int v=0; v<n; v++){
        if(p[k][v] < 0) p[k+1][v] = -1;
        else p[k+1][v] = p[k][p[k][v]];
      }
    }
  }

  //return the node number of lowest common ancestor between u and v
  int get_lca(int u, int v){
    if(d[u] > d[v]) swap(u,v);
    for(int k=0; k<size; k++){
      if( (d[v] - d[u]) >> k & 1){
        v = p[k][v];
      }
    }
    if(u==v) return u;

    for(int k=size-1; k>=0; k--){
      if(p[k][u] != p[k][v]) {
        u = p[k][u];
        v = p[k][v];
      }
    }
    return p[0][u];
  }

  //return depth of node[u]
  int depth(int u){
    return d[u];
  }

  int dist(int u, int v){
    int p = get_lca(u,v);
    int res = d[u] + d[v] - 2*d[p];
    return res;
  }
};

vector<int> r;
vector<int> sz;
vector<bool> path;

vector<int> leaf;

int get_size(vector<vector<int>>& G, int pos, int par, bool& is_path){
  int& res = sz[pos];
  res = 1;
  int d = 0;
  for(auto nx : G[pos]) if(nx != par && r[nx] == -1){
    res += get_size(G, nx, pos, is_path);
    d++;
  }

  if( par == -1 ){
    if( d > 2 ) is_path = false;
  }else{
    if( d > 1 ) is_path = false;
  }
  if( d==0 || (par==-1&&d<=1) ){
    leaf.push_back(pos);
  }

  return res;
}

int get_centroid(vector<vector<int>>& G, int pos, int par, int total){
  for(auto nx : G[pos]) if(nx != par && r[nx] == -1){
    if( sz[nx]*2 >= total ){
      return get_centroid(G, nx, pos, total);
    }
  }
  return pos;
}

LCA lca;

vector<int> ll;
vector<int> lr;
vector<int> dp;
int centroid_decomposition(vector<vector<int>>& G, int pos, int par){
  bool is_path = true;
  leaf.resize(0);
  int total = get_size(G, pos, -1, is_path);
  int c = get_centroid(G, pos, -1, total);

  pos = c;

  if( par == -1 ){
    lca.initialize(G, c);
  }


  path[c] = is_path;
  if(is_path){
    ll[pos] = leaf[0];
    lr[pos] = leaf.size()>1 ? leaf[1] : leaf[0];
  }

  r[c] = 1;

  vector<pair<int,int>> ch;
  for(auto nx : G[c]) if( r[nx] == -1 ){
    ch.push_back( {centroid_decomposition(G, nx, c), nx} );
  }
  r[c] = -1;

  if(total == 1){
    dp[c] = 1;
  }else if(is_path){
    dp[c] = 1;
  }else{
    int tmp = 0;
    for(auto nx : ch) if( r[nx.first] == -1 ){
      tmp += dp[nx.first];
    }

    dp[c] = tmp;
    for(auto nx : ch) if( r[nx.first] == -1 ){
      if( path[nx.first] && (ll[nx.first] == nx.second || lr[nx.first] == nx.second)){
        if( par!=-1 && lca.dist(c, par) > lca.dist(nx.second, par) ){
          if( nx.second != ll[nx.first] && nx.second != lr[nx.first] ){
            continue;
          }
          if( ll[nx.first] != lr[nx.first] ){
            if( lca.dist(ll[nx.first] ^ lr[nx.first] ^ nx.second, par) > 1 ) continue;
          }
        }
        dp[c] = min(dp[c], tmp-dp[nx.first]);
      }
    }
  }

  return c;
}

int dfs(vector<vector<int>>& G, int pos, int par){
  bool is_path = true;
  int d = 0;
  for(auto nx : G[pos]) if(nx!=par){
    d++;
    is_path = dfs(G, nx, pos) && is_path;
  }

  if(d >= 2){
    is_path = false;
  }
  path[pos] = is_path;

  if( d==0 ){
    dp[pos] = 1;
    return true;
  }

  int tmp = 0;
  for(auto nx : G[pos]) if(nx!=par){
    tmp += dp[nx];
  }

  dp[pos] = tmp;
  if(!is_path) for(auto nx : G[pos]) if(nx!=par){
    if( path[nx] ){
      dp[pos] = min(dp[pos], tmp - dp[nx]);
    }
  }

  return is_path;
}

