template <typename T>
struct Edge {
    int from, to;
    T cost;
    Edge(int s, T d) : to(s), cost(d) {}
    Edge(int f, int s, T d) : from(f), to(s), cost(d) {}

    bool operator<(const Edge &e) const {
        return cost < e.cost;
    }
    bool operator>(const Edge &e) const {
        return cost > e.cost;
    }
};

template <typename T>
using Graph = vector< vector< Edge<T> > >;

template <typename T>
void getDeepest(pair<int, T> &n, vector< vector< Edge<T> > > &G, int p, int prev, T cost) {
    int ok = true;
    for(auto x : G[p]) {
        if(x.to != prev) {
            ok = false;
            getDeepest(n, G, x.to, p, cost+x.cost);
        }
    }
    if(ok && n.second < cost) {
        n.first = p;
        n.second = cost;
    }
}

