#include<bits/stdc++.h>
using namespace std;

using Graph=vector<vector<int>>;
Graph g0;
Graph t;
vector<int> used;
int root=-1;

void buildTree(int v){
    used[v]=true;
    for(int i=0;i<g0[v].size();i++){
        int to=g0[v][i];
        if(!used[to]){
            t[v].push_back(to);
            buildTree(to);
        }
    }
    return;
}

int dfs(int v){
    if(t[v].size()==0) return 0;
    int res=0;
    int cnt0=0;
