int solve(int mask)
{
    if(mask==0) return 0;
    if(dp[mask]!=-1) return dp[mask];
    int ans=INF;
    for(int i=0;i<15;i++)
    {
        if(!(mask&(1<<i))) continue;
        for(int j=i+1;j<15;j++)
        {
            if(!(mask&(1<<j))) continue;
            int newmask=mask^(1<<i)^(1<<j);
            int to=((i+1)^(j+1))-1;
            if(mask&(1<<to)) ans=min(ans,solve(newmask^(1<<to))+2);
            else ans=min(ans,solve(newmask^(1<<to))+1);
        }
    }
    return dp[mask]=ans;
}
