	dist[0]=0;
	DFS1(0);
	int max_val=0;
	int max_posi=-1;
	for(int i=0; i<N; i++){
		if(dist[i]>max_val){
			max_val=dist[i];
			max_posi=i;
		}
	}
	memset(dist, -1, sizeof(dist));
	dist[max_posi]=0;
	DFS1(max_posi);
	max_val=0;
	vector<int> far;
	for(int i=0; i<N; i++){
