void dfs(int v, int p=-1) {
  if (sz(to[v]) == 1) {
    dp[v][0] = 0;
    dp[v][1] = dp[v][2] = 1;
    return;
  }
  int s0 = 0;
  int s1 = 0;
  int s2 = 0;
  int cnt = 0;
  int mx = 0;
  rep(i,sz(to[v])) {
    int u = to[v][i];
    if (u == p) continue;
    dfs(u,v);
    s0 += dp[u][0];
    s1 += dp[u][1];
    s2 += dp[u][2];
    maxs(mx, dp[u][1]-dp[u][0]);
    cnt++;
  }
  // cout<<v<<" "<<s0<<" "<<s1<<" "<<s2<<endl;
  if (cnt == 1) {
    dp[v][0] = s0;
    dp[v][1] = min(s0+1, s1);
    dp[v][2] = min(s0+1, s2);
  } else {
    dp[v][2] = min(s1+1, s2);
    dp[v][1] = min(dp[v][2], s1-mx);
    dp[v][0] = dp[v][1];
  }
  // cout<<v<<" "<<dp[v]<<endl;
}

