vector<vector<int>> g;

pair<int, int> dfs(int v, int p) {
  pair<int, int> res = {1, 1};
  bool first = true;
  bool rem = false;
  for (int u : g[v]) {
    if (u == p) continue;
    eprintf("%d -> %d\n", v, u);
    if (first) {
      res = dfs(u, v);
      first = false;
    } else {
      if (res.second == 1) {
        assert(res.first == 1);
        res.first = 0;
        rem = true;
      }
      auto in = dfs(u, v);
      res.first += in.first;
      res.second = false;
      if (!rem && in.second) {
        assert(in.first == 1);
        res.first -= in.first;
        rem = true;
      }
    }
  }
  eprintf("dfs(%d) = %d,%d\n", v, res.first, res.second);
  return res;
}

