using namespace std;
int n;
vector<int>p[100100];
vector<int>ch[100100];
ll dp[100100][2][2];

void dfs(int x,int pp = -1){

    for(int i=0 ;i <p[x].size() ;i ++){
        if(p[x][i] == pp)continue;
        dfs(p[x][i],x);
        ch[x].push_back(p[x][i]);
    }
    if(ch[x].empty()){
        dp[x][1][0] = 0;
        dp[x][0][0] = 0;
        dp[x][0][1] = 1;
        dp[x][1][1] = 1;
        return;
    }
    if(ch[x].size() == 1){
        dp[x][0][0] = dp[ch[x][0]][0][0];
    }
    ll r =0,y,r1=0;
    for(int i=0 ;i <p[x].size() ;i ++){
        if(p[x][i] == pp)continue;
        y = p[x][i];
        r += min(dp[y][0][1],dp[y][1][1]);
        r1 += dp[y][1][1];
    }
    dp[x][0][1] = r;
    if(ch[x].size() > 1)
        dp[x][1][1] = r;
    else
        dp[x][1][1] = r+1;
    dp[x][1][1] = min(dp[x][1][1],r1);
    for(int i=0 ;i <p[x].size() ;i ++){
        if(p[x][i] == pp)continue;
        y = p[x][i];
        r1 = min(dp[y][0][1],dp[y][1][1]) - min(min(dp[y][0][0],dp[y][1][0]),min(dp[y][0][1],dp[y][1][1]));
        dp[x][0][1] = min(dp[x][0][1],r - r1);
    }

    if(pp == -1){
        r1 =0 ;
        for(int i=0 ;i <p[x].size() ;i ++){
            if(p[x][i] == pp)continue;
            y = p[x][i];
            r1 += dp[y][1][1];
        }
        for(int i=0 ;i <p[x].size() ;i ++){
            if(p[x][i] == pp)continue;
            y = p[x][i];
            dp[x][1][1] = min(dp[x][1][1],r1-dp[y][1][1]+dp[y][1][0]);
        }
    }

    dp[x][0][1] = max(dp[x][0][1],1LL);
    dp[x][1][1] = max(dp[x][1][1],1LL);
}

