        int to = list[node][i];

        if (to == root) {
            list[node][i] = list[node].back();
            list[node].pop_back();
            i--;
            continue;
        }

        dfs(to, node);
    }

    if (list[node].empty()) {
        dp[node] = 1;
        up[node] = 0;
        return;
    }

    if (list[node].size() == 1) {
        int to = list[node][0];
