using Graph=vector<vector<int>>;

pii dfs(int idx,int par,Graph &g){
    vector<pii> v;
    for(int next:g[idx]){
        if(next==par) continue;
        pii x=dfs(next,idx,g);
        v.push_back(x);
    }
    if(v.size()==1){
        return v[0];
    }
    if(v.size()==0){
        return {0,0};
    }
    int cnt=0;
    int ret=0;
    for(int i=0;i<v.size();i++){
        if(v[i].first==0) cnt++;
        else{
            ret+=v[i].first;
        }
    }
    if(par==-1){
        if(cnt) return {ret+cnt-1,1};
        else return {ret,1};
    }
    if(cnt) return {ret+cnt-1,0};
    else return {ret,1};
}

