P2 dfs(int p , int q){
	int r = 0 , s = 0 , t = 0 , c = 0;
	for(auto u : V[q]){
		if(u == p) continue;
		P2 z = dfs(q,u);
		r += z.first;
		if(z.first==0) ++s;
		else if(z.second>0) ++t;
		else ++c;
	}
	if(s>0) r += s-1;
	return MP(r,s>0||(t+c==1&&t>0)?1:0);
}

