void dfs(int k)
{
	v[k]=1;
	int t[8];for (int i=0;i<8;i++) t[i]=inf;t[6]=0;
	for (vi::iterator r=e[k].begin();r!=e[k].end();r++)
		if (!v[*r])
		{
			dfs(*r);int g[8];
			for (int i=0;i<8;i++) g[i]=inf;
			for (int i=0;i<8;i++)
			{
				int x=i&1,y=(i&2)>>1,z=(i&4)>>2;
				for (int j=0;j<4;j++)
				{
					int p=j&1,q=(j&2)>>1;
					if ((!z)&&(!p)) continue;
					g[(x|p)+((y|p)&(x|q))*2+(z&p)*4]=min(g[(x|p)+((y|p)&(x|q))*2+(z&p)*4],t[i]+dp[*r][j]);
				}
			}
			for (int i=0;i<8;i++) t[i]=g[i];
		}
	for (int i=0;i<4;i++) dp[k][i]=inf;
	for (int i=0;i<8;i++)
	{
		int x=i&1,y=(i&2)>>1,z=(i&4)>>2;
		dp[k][x+(y&z)*2]=min(dp[k][x+(y&z)*2],t[i]);
		dp[k][1+z*2]=min(dp[k][1+z*2],t[i]+1);
		if (k==0) ans=min(ans,t[i]+((!x)|(!y)));
	}
}

