const int MAX = 1e5;

int cnt[MAX];
int dp[MAX];
int ex[MAX];

int dfs(int v, int prev, const vector<vector<int>>& G) {
	int res = 0;
	for (auto to : G[v]) if (to != prev) {
		int tmp = dfs(to, v, G);
		ex[v] += tmp != 0;
		res += tmp;
	}
	int chil = prev == -1 ? (int)G[v].size() - 1 : (int)G[v].size() - 2;
	if (ex[v] < chil) {
		cnt[v] = chil - ex[v];
		res += cnt[v];
	}
	return dp[v] = res;
}

