void dfs(int v, int p = -1){
    int x = 0;
    int y = 0;
    int z = 0;
    for (auto u: g[v]){
        if (u == p) continue;
        dfs(u, v);
        if (dp[u] == 0) x++;
        if (dp[u] == 1) y++;
        if (dp[u] == 2) z++;
    }
    if (x <= 1 && y == 0 && z == 0){
        dp[v] = 0;
        return;
    }
    if (y > 1 || z > 0){
        z += y;
        y = 0;
    }
    if (y == 0){
        if (x == 0){
            dp[v] = 2;
        } else{
            ans += x - 1;
            dp[v] = 1;
        }
        return;
    }
    if (y == 1){
        if (x > 0) ans += x - 1;
        dp[v] = 1;
        if (v == v0) ans++;
    }
}
