int fr[MN],nex[MN],vi[MN],tot=0;
int sn[MN];
int n;
int vd[MN];
int tt[MN];
int res;
void add(int x,int y){
	vi[++tot]=y;nex[tot]=fr[x];fr[x]=tot;++sn[x];
}
void dfs(int x,int fa){
	for(int i=fr[x];i;i=nex[i])if(vi[i]!=fa){
		dfs(vi[i],x);
		if(vd[vi[i]])++vd[x];
		tt[x]+=tt[vi[i]];
	}
	if(vd[x]<sn[x]-1){
		res+=sn[x]-1-vd[x];
		tt[x]+=sn[x]-1-vd[x];
		vd[x]=sn[x]-1;
	}
	//cerr<<x<<' '<<sn[x]<<' '<<vd[x]<<' '<<tt[x]<<' '<<res<<endl;
}
int main(){
	read(n);
	if(n==1)return puts("0"),0;
	if(n==2)return puts("1"),0;
	for(int i=2;i<=n;++i)sn[i]=-1;
	for(int i=1,x,y;i<n;++i){
		read(x);read(y);++x;++y;
		add(x,y);add(y,x);
	}
	dfs(1,1);
	for(int i=2;i<=n;++i){
		if(vd[i]==sn[i]-1&&res==tt[i]){++res;break;}
	}
	printf("%d",res);
	return 0;
}

