int dp[100005][2];

int count(int cur, int parent, int force, vector<vector<int>> &G) {
  if (dp[cur][force] == -1) {
    vector<int> v_next;
    for (auto next : G[cur]) {
      if (next != parent) {
        v_next.push_back(next);
      }
    }

    int cnt = 0;
    if (v_next.size() == 0) {
      cnt = force;
    } else if (v_next.size() == 1) {
      cnt = count(v_next[0], cur, force, G);
    } else if (v_next.size() > 1) {
      vector<int> with_force(v_next.size()), without_force(v_next.size());
      int sum_with = 0, sum_without = 0;

      for (int i = 0; i < v_next.size(); ++i) {
        int next = v_next[i];

        with_force[i] = count(next, cur, 1, G);
        without_force[i] = count(next, cur, 0, G);

        sum_with += with_force[i];
        sum_without += without_force[i];
      }

      // D(sum_with); D(sum_without);
      cnt = INT_MAX;
      for (int i = 0; i < v_next.size(); ++i) {
        int tmp = sum_with - with_force[i] + without_force[i];
        cnt = min(cnt, tmp);
        // D(i); D(tmp);
      }
    }

    dp[cur][force] = cnt;
    // cout << cur << " : " << cnt << " + " << force << " = " << cnt + force << endl;
  }


  return dp[cur][force];
}

int main() { IO;
  int n;
  cin >> n;

  vector<vector<int>> G(n);
  for (int i = 0; i < n - 1; ++i) {
    int a, b;
    cin >> a >> b;

    G[a].push_back(b);
    G[b].push_back(a);
  }

  for (int i = 0; i < 100005; ++i) {
    dp[i][0] = dp[i][1] = -1;
  }

  int ans = INT_MAX;
  for (int i = 0; i < n; ++i) {
    if (G[i].size() >= 3) {
      ans = count(i, -1, 0, G);
      break;
    }
  }

  if (ans == INT_MAX) {
    ans = 1;
  }

  cout << ans << endl;

  return 0;
}

