signed main() {
    int n;
    cin >> n;

    vector2<int> g(n);
    rep(i, n - 1) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    rep(i, n) {
        if (g[i].size() != 2) {
            continue;
        }
        int a = g[i][0];
        int b = g[i][1];

        g[i].resize(0);
        for (size_t j = 0; j < g[a].size(); j++) {
            if (g[a][j] == i) {
                g[a][j] = b;
                break;
            }
        }
        for (size_t j = 0; j < g[b].size(); j++) {
            if (g[b][j] == i) {
                g[b][j] = a;
                break;
            }
        }
    }

    int ans = 0;
    rep(i, n) {
        if (g[i].size() <= 1) {
            continue;
        }
        int cnt = g[i].size() - 1;
        for (size_t j = 0; j < g[i].size(); j++) {
            if (g[g[i][j]].size() >= 3) {
                cnt--;
            }
        }
        ans += cnt;
    }

    cout << max(ans, 1LL) << endl;

    return 0;
