const int N = 1e5 + 7;

int sz[N];
int used[N];
vector<int> g[N];

void dfs_find(int cur, int p, int need, int &ans, int &all) {
	int mx = 0;
	sz[cur] = 1;
	int c = 0;
	for (auto t : g[cur]) {
		if (!used[t] && t != p) {
			dfs_find(t, cur, need, ans, all);
			sz[cur] += sz[t];
			mx = max(mx, sz[t]);
			c++;
		}
	}
	all &= (c < 3);
	mx = max(mx, need - sz[cur]);
	if (2 * mx <= need) {
		ans = cur;
	}
}

void dfs_sz(int cur, int p) {
	sz[cur] = 1;
	for (auto t : g[cur]) {
		if (!used[t] && t != p) {
			dfs_sz(t, cur);
			sz[cur] += sz[t];
		}
	}
}

void dfs(int some, int need, int &ans, int &is_bamb) {
	int centr = -1;
	is_bamb = 1;
	dfs_find(some, -1, need, centr, is_bamb);
	assert(centr != -1);
	dfs_sz(centr, -1);
	used[centr] = 1;
	// cerr << some << ' ' << need << ' ' << centr << endl;
	if (sz[centr] == 1) {
		is_bamb = 1;
		ans = 1;
		return;
	}
	ans = 0;
	int any = 0;
	for (auto t : g[centr]) {
		if (!used[t]) {
			int cans = 0;
			int cbamb = 0;
			dfs(t, sz[t], cans, cbamb);
			// if (centr == 0) {
			// 	cerr << t << ' ' << cans << ' ' << cbamb << endl;
			// }
			ans += cans;
			any |= cbamb;
		}
	}
	ans -= any;
	ans = max(ans, 1);
	return;
}

