    }
    return summ;
}

int GetMinSumAtmostOneZero(const vector<int>& V) {
    int has_ret = 0;
    int num_zeros = 0;
    for(int x : V) {
        num_zeros += (x == 0);
        has_ret += x;
    }

    has_ret += max(0, num_zeros - 1);
    return has_ret;
}

