int root=-1;

void buildTree(int v){
    used[v]=true;
    for(int i=0;i<g0[v].size();i++){
        int to=g0[v][i];
        if(!used[to]){
            t[v].push_back(to);
            buildTree(to);
        }
    }
    return;
}

pair<int,bool> dfs(int v){
    if(t[v].size()==0) return {0,true};
    int res=0;
    int cnt0=0;
    bool aimaiChil=false;
    for(int i=0;i<t[v].size();i++){
        auto ret=dfs(t[v][i]);
        aimaiChil|=ret.second;
        cnt0+=(ret.first==0);
        res+=ret.second;
    }
    bool aimai=false;
    if(cnt0>=1){
        res+=cnt0-1;
        aimai=true;
    }
    if(res==0) aimai=true;
    if(v==root && aimaiChil && cnt0>=1) res++;
    return {res,aimai};
}

