int DFS(int node, int prev) {
	bool isZeroCheck = false;
	int res = 0;
	for (auto &to : G[node]) if(to != prev){
		const int score = DFS(to, node);
		if (score == 0) {
			if (not isZeroCheck) isZeroCheck = true;
			else res++;
		}
		else res += score;
	}
	return res;
}

