bool used[100010];
bool root[100010];
int depth[100010];

void dfs(int v, int dep) {
    if (used[v]) return;
    used[v] = true;
    depth[v] = dep;
    if (G[v].size() == 1) root[v] = true;
    REP(i,G[v].size()) {
        dfs(G[v][i], dep + 1);
    }
}

