    int degree = -1;
    REP(i,N) {
        if ((int) G[i].size() > degree) {
            degree = (int) G[i].size();
            start = i;
        }
    }

    dfs(start, 2);

    set < int > used_v;
    int ans =  1;
    REP(i,N) {
        if (root[i]) {
            if (used_v.find(depth[i]) == used_v.end()) {
                used_v.insert(depth[i]);
            } else {
                ans++;
            }
        }
    }

    REP(i,N) {
        if (G[i].size() > 2) {
            cout << ans << endl;
            return 0;
        }
    }

    cout << ans - 1 << endl;

    return 0;
}

