	CVECTOR(const std::vector<T>& a) : cumsum(a.size() + 1, 0) {
		for (size_t i = 0; i < a.size(); ++i) cumsum[i + 1] = cumsum[i] + a[i];
	}
	T operator[](int idx) { return cumsum[idx + 1]; }
};
template<class T> CVECTOR<T> make_cvector(const std::vector<T>& a) {
	return CVECTOR<T>(a);
}
