int helper(int node, int prev = -1){

    int tot = 0, equipped = 0, deg = adj[node].size();

    for(int nx : adj[node]){
        if(nx == prev) continue;
        int v = helper(nx, node);
        if(v) --deg;
        tot += v;
    }

    return tot + max(0, deg - 2);

}


