  }
  for(auto e: child[i])calc(e);
  if(sz(child[i]) == 1){
    rep(k, 2){
      rep(l, 2){
        dp[i][k][l] = dp[child[i][0]][k][l];
      }
    }
    return;
  }
  if(sz(child[i]) == 2){
    // j = 0
    dp[i][1][0] = 0;
    for(auto e: child[i]){
      dp[i][1][0] += min(dp[e][1][0], dp[e][1][1]);
    }
    // j = 1
    if(i > 0){
      dp[i][1][1] = inf;
      for(auto e: child[i]){
        chmin(dp[i][1][1], dp[i][1][0] - min(dp[e][1][0], dp[e][1][1]) + min(dp[e][0][0], dp[e][0][1]));
      }
    }else{
      int e1 = child[i][0], e2 = child[i][1];
      chmin(dp[i][1][0], dp[e1][1][0] + dp[e2][0][1]);
      chmin(dp[i][1][0], dp[e1][1][1] + dp[e2][0][1] + 1);
      chmin(dp[i][1][0], dp[e2][1][0] + dp[e1][0][1]);
      chmin(dp[i][1][0], dp[e2][1][1] + dp[e1][0][1] + 1);
    }
    return;
  }
  // j = 0
  dp[i][1][0] = 0;
  for(auto e: child[i]){
    dp[i][1][0] += min(dp[e][1][0], dp[e][1][1]);
  }
  // j = 1
  if(i > 0){
    dp[i][1][1] = inf;
    for(auto e: child[i]){
      chmin(dp[i][1][1], dp[i][1][0] - min(dp[e][1][0], dp[e][1][1]) + min(dp[e][0][0], dp[e][0][1]));
    }
  }else{
    int tmp = inf;
    for(auto e: child[i]){
      chmin(tmp, dp[i][1][0] - min(dp[e][1][0], dp[e][1][1]) + min(dp[e][0][0], dp[e][0][1]));
    }
    chmin(dp[i][1][0], tmp);
  }
}

