	typedef struct _b{
		int dest;int nxt;
	}bian;bian memchi[1000001];int gn=1,heads[100001],deg[100001],mxdeg[100001];
	inline void add(int s,int t){
		memchi[gn].dest=t;memchi[gn].nxt=heads[s];heads[s]=gn;gn++;
	}
	void dfs(int pt,int baba){
		mxdeg[pt]=deg[pt];for(register int i=heads[pt];i;i=memchi[i].nxt){
			if(memchi[i].dest==baba)continue;dfs(memchi[i].dest,pt);mxdeg[pt]=max(mxdeg[pt],mxdeg[memchi[i].dest]);
		}
	}int ans;
	void solve(int pt,int baba){
		if(deg[pt]==1){
			ans++;return;
		}if(deg[pt]==2&&baba){
			for(register int i=heads[pt];i;i=memchi[i].nxt){
				if(memchi[i].dest==baba)continue;solve(memchi[i].dest,pt);
			}return;
		}int son=0;for(register int i=heads[pt];i;i=memchi[i].nxt){
			if(memchi[i].dest==baba)continue;if(mxdeg[memchi[i].dest]<=2){
				son=memchi[i].dest;break;
			}
		}for(register int i=heads[pt];i;i=memchi[i].nxt){
			if(memchi[i].dest==baba||memchi[i].dest==son)continue;solve(memchi[i].dest,pt);
		}
	}
	void ywymain(){
		int n=get();for(register int i=1;i<n;i++){
			int s=get()+1,t=get()+1;deg[s]++;deg[t]++;add(s,t);add(t,s);
