		}for(register int rt=1;rt<=n;rt++){
			if(deg[rt]>1){
				dfs(rt,0);if(mxdeg[rt]<=2){
					cout<<1<<endl;return;
				}solve(rt,0);cout<<ans<<endl;return;
			}
		}
	}
