        Dfs2(kx,x,vis);
    }
    if (vis&&d[x]==1) rt1=x;
}
int Solve(int x,int fat) {
    int sum=0;
    int zero=0;
    for (int i=0;i<(int)edge[x].size();i++) {
        int kx=edge[x][i];
        if (kx==fat) continue;
        int nowx=Solve(kx,x);
        sum+=nowx;
        if (nowx==0) zero++;
    }
    if (zero>1) sum+=zero-1;
    return sum;
}
