class E {
public:
    int N;
    vector<vector<int>> E;

    int dfs(int u, int p) {
        vector<int> Q;
        for (int v:E[u]) {
            if (v != p) {
                Q.push_back(dfs(v,u));
            }
        }
        sort(Q.begin(),Q.end());

        int q = 0;
        for (int i = 0; i < Q.size(); ++i) q += Q[i] + (i > 0 && Q[i] == 0);
        return q;
    }

    void solve(istream& cin, ostream& cout) {
        cin >> N;
        if (N == 2) {
            cout << 1 << endl;
            return;
        }

        E.resize(N);
        for (int i = 0; i < N - 1; ++i) {
            int a,b; cin >> a >> b;
            E[a].push_back(b);
            E[b].push_back(a);
        }

        for (int i = 0; i < N; ++i) {
            if (E[i].size() > 1) {
                cout << dfs(i, -1) << endl;
                return;
            }
        }

    }
};


