using namespace std;

int solve(vector< vector<int> > &T, int v, int from){
  int ret = 0, k = 0;
  for(int i = 0; i < T[v].size(); ++i){
    if(T[v][i] != from){
      int t = solve(T,T[v][i],v);
      if(t == 0) ++k;
      ret += t;
    }
  }
  ret += max(0,k-1);
  return ret;
}

