  for(int i = 0; i < N-1; ++i){
    cin >> x >> y;
    T[x].push_back(y);
    T[y].push_back(x);
  }
  int m = 0, v = -1;
  for(int i = 0; i < N; ++i){
    if(T[i].size() > m){
      m = T[i].size();
      v = i;
    }
  }
  int ans = solve(T,v,v);

  cout << ans << endl;
  return 0;
}

