int dfs(int v,int p){
  // cout<<v<<' '<<p<<endl;
  int ch=g[v].size()-(p>=0);
  int res=0;
  pth[v]=2;
  int paths=0;
  for(int w:g[v]){
    if(w==p) continue;
    int k=dfs(w,v);
    if(!pth[w]) pth[v]=0;
    if(pth[w]) paths++;
    pth[v]--;
    res+=k;
  }
  pth[v]=(pth[v]>=1);
  if(res==0) res=1;
  if(paths>=2) res--;
  return res;
}

