	cin >> N;
	vector<vector<int>>edge(N);
	for (int i = 1; i < N; i++) {
		cin >> L >> R;
		edge[L].push_back(R);
		edge[R].push_back(L);
	}
	vector<int>depth(N, MOD);
	vector<int>dp(N);
	Calculate_Depth(edge, depth, 0);
	Search(edge, depth, 0, dp);
	for (int i = 1; i < N; i++) {
		if (edge[i].size() > 2) {
			dp[0]++;
			break;
		}
	}
	dp[0] = max(dp[0], 1);
	cout << dp[0] << endl;
	return 0;
}

