int DFS(int x, int p) {
  int res = 0, f = 0;
  for (int nxt : G[x]) {
    if (nxt == p)
      continue;
    int res_nxt = DFS(nxt, x);
    if (res_nxt == 0 && f)
      ++res;
    if (res_nxt == 0 && !f) 
      f = 1;
    res += res_nxt;
  }
  return res;
}

