#define l_ength size

void mul_mod(ll& a, ll b){
	a *= b;
	a %= MOD;
}

void add_mod(ll& a, ll b){
	a = (a<MOD)?a:(a-MOD);
	b = (b<MOD)?b:(b-MOD);
	a += b;
	a = (a<MOD)?a:(a-MOD);
}

int dv[100100];
bool pu[100100];
std::vector<int> g[100100];

int solve(int v, int p = -1){
	int i,u,cnt=0,ret=0,tmp;
	if(pu[v]){
		++cnt;
	}
	for(i=(g[v].l_ength()-1); i>=0; --i){
		u = g[v][i];
		if(u == p){
			continue;
		}
		pu[u] = (pu[v]|(dv[v]>1));
		tmp = solve(u,v);
		ret += tmp;
		if(tmp){
			++cnt;
		}
	}
	if(dv[v]==1){
		return ret;
	}
	if(cnt<dv[v]){
		ret += (dv[v]-cnt);
	}
	return ret;
}

