		--dv[i];
		dvm = std::max(dvm,P(dv[i],i));
	}
	if(dvm.first<2){
		std::cout << 1 << std::endl;
		return 0;
	}
	std::cout << solve(dvm.second) << std::endl;

	return 0;
}

