typedef long long LL;typedef long double LD;
int DEBUG=0,MULTI=0,GCJ=0;

struct solver_t;solver_t *solver;
struct solver_t {
  VV <VV<int>> EDG;

  int res = 0;
  int dfs(int u, int prev) {

    VV <int> next;
    for (int v:EDG[u]) if (v != prev) {
      next.push_back(dfs(v, u));
    }
    if (next.size() == 0) {
      return 0;
    }
    if (next.size() == 1) {
      return next[0];
    }
    sort(ALL(next), greater<int>());

    REP (i, (int) next.size() - 1) {
      res += next[i] == 0 ? 1 : 0;
    }
    return 1;
  }

  template<typename F>
  void dfs2(int u, int prev, int dst, F fun) {
    for (int v:EDG[u]) if (v != prev) {
      dfs2(v, u, dst + 1, fun);
    }
    fun(u, dst);
  }

  void solve() {
    int N; cin >> N;
    EDG.resize(N);

    REP (i, N - 1) {int a, b; cin >> a >> b;
      EDG[a].push_back(b);
      EDG[b].push_back(a);
    }

    if (N <= 1) {
      cout << 0 << "\n";
      return;
    }
    res = 1;

    int best_dst = -1;
    int best_u = -1;

    dfs2(0, -1, 0, [&](int u, int dst) {
        if (best_dst < dst) {
          best_dst = dst;
          best_u = u;
        }
    });
    DB(best_dst<<" "<<best_u);

    dfs(best_u, -1);                                   ;

    cout << res << "\n";

  }
  void gen() {}
  void brute() {}
};

