int n;
vector<int> nei[100007];
int dp[100007];

void dfs(int now, int lst)
{
	dp[now] = 0;
	if (SZ(nei[now]) == 1)
		return;
	int bb = 0, cc = 0;
	for (int i = 0; i < SZ(nei[now]); i++)
	{
		int j = nei[now][i];
		if (j != lst)
		{
			cc++;
			dfs(j, now);
			dp[now] += dp[j];
			if (dp[j] != 0)bb++;
		}
	}
	dp[now] += max(cc - bb - 1, 0);
	if (dp[now] == 0)dp[now] = 1;
}

