using namespace std;

const int N=100010;

int n,cnt,G[N],f[N],du[N];
struct edge{
	int t,nx;
}E[N<<1];

inline void addedge(int x,int y){
	E[++cnt].t=y; E[cnt].nx=G[x]; G[x]=cnt;
	E[++cnt].t=x; E[cnt].nx=G[y]; G[y]=cnt;
}

void dfs(int x,int p){
	int son=0,ct=0;
	for(int i=G[x];i;i=E[i].nx)
		if(E[i].t!=p){
			dfs(E[i].t,x);
			son++; ct+=!!f[E[i].t];
			f[x]+=f[E[i].t];
		}
	f[x]+=max(son-1-ct,0);
}

int main(){
	scanf("%d",&n);
	for(int i=1,x,y;i<n;i++)
		scanf("%d%d",&x,&y),addedge(x,y),du[x]++,du[y]++;
	int rt;
	for(int i=0;i<n;i++) if(du[i]) rt=i;
	dfs(rt,-1);
	printf("%d\n",f[rt]+1);
	return 0;
}

