int dfs(int son, int fa)
{
    int ans = 0, flag = 0;
    for(int i = 0; i < v[son].size(); i++)
    {
        if(v[son][i]==fa)
            continue;
        int res = dfs(v[son][i], son);
        if(!res && !flag)
        {
            flag++;
        }
        if(!res && flag)
        {
            ans++;
        }
        ans += res;
    }
    return ans;
}

