struct Triangle {
    int parent;
    vector<int> children;
};

class Tree {
public:
    vector<vector<int>> edges;

    Tree(int n) : edges(n) {}

    void edge(int i, int j) {
        edges[i].push_back(j);
        edges[j].push_back(i);
    }

    void root(int r, vector<Triangle> &leafs) {
        queue<int> vs;
        vs.push(r);
        vector<bool> check(edges.size(), false);
        check[r] = true;
        while (!vs.empty()) {
            int k = vs.front();
            Triangle triangle;
            triangle.parent = k;

            for (int i : edges[k]) {
                if (check[i]) continue;
                check[i] = true;
                triangle.children.push_back(i);
                vs.push(i);
            }
            vs.pop();
            leafs.push_back(triangle);
        }
        reverse(leafs.begin(), leafs.end());
    }

    int max_v() {
        int v = 0;
        for (auto &e: edges) {
            cmax(v, (int) e.size());
        }
        return v;
    }

    int get_v(int v) {
        rep(i, edges.size()) {
            auto &e = edges[i];
            if (e.size() == v) return i;
        }
        return -1;
    }

};

