    rep(i, n - 1) {
        int a, b;
        cin >> a >> b;
//        is >> a >> b;
        tree.edge(a, b);
    }


    if (tree.max_v() <= 2) {
        cout << 1 << endl;
        ret();
    }

    int root = tree.get_v(tree.max_v());

    vector<Triangle> leafs;
    tree.root(root, leafs);

    vector<int> dp(n, 0);

    for (auto &e : leafs) {

        int child_sum = 0;
        int empty = 0;
        for (int i : e.children) {
            child_sum += dp[i];
            if (dp[i] == 0) empty++;
        }

        int next = child_sum + max(empty - 1, 0);


        dp[e.parent] = next;
    }


    cout << dp[root] << endl;
}

