            if (!visit[child]) continue;
            cs++;
            onechild = child;
            if (cexist[child]) {
                cexist[now] = true;
                ca++;
            }
            if (pneed[child]) pn++;
        }
        bool nw = false;
        if (cs - ca >= 2) {
            ans += cs-ca-1;
