    re;
  }
  if (chainCnt >= 1 && pr == -1) {
    dp[v] = max(1, sum - 1);
    used = 1;
  } else {
    dp[v] = max(1, sum);
  }
  if (pr == -1 && !used && chainCnt >= 1) {
    dp[v]--;
  }
  // cerr << v << ' ' << dp[v] << ' ' << chainCnt << ' ' << ok << endl;
}

