bool dp(int b, int to) {
	if (memo.count(make_pair(b, to))) {
		return memo[{b, to}];
	}
	if (graph[to].size() == 1) {
		return memo[{b, to}] = true;
	}
	if (graph[to].size() == 2) {
		int other = graph[to][0];
		if (other == b)other = graph[to][1];
		return memo[{b, to}] = dp(to, other);
	}
	return memo[{b, to}] = false;
}

