void findroot(int x,int lst){
    dub[x] = dub[lst] + 1;
    if(dub[x] > dub[bst])
        bst = x;
    for(int i = 0;i<v[x].size();i++)
        if(v[x][i] != lst)
            findroot(v[x][i], x);
}

void findlan(int x,int lst){
    int lncnt = 0;
    for(int i = 0;i<v[x].size();i++){
        if(v[x][i] == lst) continue;
        findlan(v[x][i], x);
        lncnt += lan[x];
    }
    if((v[x].size() == 2 && x != lst && lncnt) || (v[x].size() == 1 && (x != lst || lncnt))) lan[x] = 1;
}

int solve(int x,int lst){
    int lncnt = 0,ret = 0;
    for(int i = 0;i<v[x].size();i++){
        if(v[x][i] == lst) continue;
        if(lan[v[x][i]]) lncnt++;
        else ret += solve(v[x][i], x);
    }
    if(lncnt) lncnt--;
    return ret + lncnt;
}

