const int MAXN=100000+10;

vector<int> G[MAXN];
int n,m, f[MAXN];
bool tkn[MAXN];
int DP(int u,int fa){
	int vac=0,chil=0;
	f[u] = tkn[u]=0;
	for (int i=0; i< G[u].size(); i++){
		int v= G[u][i];
		if( v==fa) continue;
		f[u]+= DP(v, u);
		++chil;
		if ( !tkn[v]) ++vac;
	}
	if ( vac>1){
		tkn[u] =true;
		f[u] += vac-1;
	}
	if( fa==-1 && vac) ++f[u];
//	if ( fa==-1) ++f[u];
	#ifdef che
	debug("fa=%d\tf[%d] = %d\n",fa, u, f[u]);
	#endif
	return f[u];
}
