	for (int i=1, u,v; i<n; i++){
		scanf("%d%d", &u, &v);
		G[u].PB(v); G[v].PB(u);
	}
	int rt=0;
	for (int i=0; i<n; i++) if ( G[i].size()==1) rt= i;
	int ans=DP(rt,-1);
	printf("%d\n", ans);
	return 0;
}

