template<typename T>
std::vector<std::vector<T>> mk2d(size_t s1, size_t s2, T const& val) {
  std::vector<T> tmp(s2, val);
  return std::vector<std::vector<T>>(s1, tmp);
}

int main() {
  std::cin.tie(0); std::ios::sync_with_stdio(false);
  int N; std::cin >> N;
  std::vector<std::vector<int>> G(N);
  for(int i = 0; i < N-1; ++i) {
    int a, b; std::cin >> a >> b;
    G[a].push_back(b);
    G[b].push_back(a);
  }
  int r = -1;
  for(int i = 0; i < N; ++i) if(G[i].size() > 2) {
    r = i; break;
  }
  if(r < 0) fin(1); // line graph
  auto dp = mk2d(2, N, N+1);
  auto dfs = [&](auto&& f, int v, int p)->void {
    int sum1 = N+1, sum = 0, r0 = -1;
    for(int c: G[v]) if(c != p) {
      f(f, c, v);
      r0 = std::max(r0+1, dp[0][c]);
      if(dp[0][c] == 0) sum1 = std::min(sum, sum1+dp[1][c]);
      sum += dp[1][c];
      if(dp[0][c] > 0) sum1 = std::min(sum, sum1+dp[1][c]);
    }
    dp[0][v] = (r0>0? N+1: 0);
    dp[1][v] = (sum==0||sum1==0)? 1: sum1;
  };
  dfs(dfs, r, -1);
  fin(dp[1][r]);
  return 0;
}

