inline void add(int x, int y) {
  e[++ e_cnt] = (E) {head[x], y}; head[x] = e_cnt; ++ du[y];
}

inline void U(int x, int y) {
  dif[x] += res[y] != 0;
  tot[x] += res[y];
  son[x] ++;
  res[x] = tot[x] + max(0, son[x] - 1 - dif[x]);
}

inline void D(int x, int y) {
  dif[x] -= res[y] != 0;
  tot[x] -= res[y];
  son[x] --;
  res[x] = tot[x] + max(0, son[x] - 1 - dif[x]);
}

inline void dfs(int u, int fat) {
  travel (i, u) {
    int v = e[i].to; if (v != fat) {
      dfs(v, u);
      U(u, v);
    }
  }
}

inline void DP(int u, int fat) {
  ans = min(ans, res[u] + 1);
  travel (i, u) {
    int v = e[i].to; if (v != fat) {
      D(u, v); U(v, u);
      DP(v, u);
      D(v, u); U(u, v);
    }
  }
}

