using namespace std;
const int maxn = 100100;
vector<int> tr[maxn];
int sz[maxn], par[maxn];
void dfs(int c, int p){
    par[c] = p;
    sz[c] = 1;
    for(int nxt : tr[c]){
        if(nxt == p) continue;
        dfs(nxt, c);
        sz[c] += sz[nxt];
    }
}
int solve(int c, int p){
    int leaves = 0, trr = 0;
    for(int nxt : tr[c]){
        if(nxt == p) continue;
        if(tr[nxt].size() == 1) leaves += 1;
        else trr += solve(nxt, c);
    }
    if(leaves > 1 || trr > 0) leaves--;
    return leaves + trr;
}
int main(){
    int n;
    scanf("%d", &n);
    for(int e = 0; e < n - 1; e++){
        int u, v;
        cin >> u >> v;
        tr[u].push_back(v);
        tr[v].push_back(u);
    }
    dfs(0, -1);
    vector<int> centroid;
    for(int e = 0; e < n; e++){
        bool ok = true;
        for(int nxt : tr[e]){
            int tmp;
            if(nxt == par[e]){
                tmp = n - sz[e];
            } else {
                tmp = sz[nxt];
            }
            ok &= tmp <= n / 2;
        }
        if(ok) centroid.push_back(e);
    }
    vector<int> rr;
    for(int v : centroid){
        rr.push_back(solve(v, -1));
    }
    sort(rr.begin(), rr.end());
    cout << rr[0] << endl;
    return 0;
}

