template <class Cost = int>
struct Edge {
    int src, dst;
    Cost cost;
    Edge(int src = -1, int dst = -1, Cost cost = 1)
        : src(src), dst(dst), cost(cost){};

    bool operator<(const Edge<Cost>& e) const { return this->cost < e.cost; }
    bool operator>(const Edge<Cost>& e) const { return this->cost > e.cost; }
};

template <class Cost = int>
using Graph = std::vector<std::vector<Edge<Cost>>>;

Graph<> graph;
int ans = 0;

int dfs(int v, int p = -1) {
    int ch = 0, cnt = 0;
    for (auto e : graph[v]) {
        if (e.dst == p) continue;
        ++ch;
        cnt += dfs(e.dst, v);
    }

    if (ch == 0) {
        return 0;
    } else if (ch == 1) {
        return cnt;
    } else {
        ans += std::max(ch - cnt - 1, 0);
        return 1;
    }
}

void solve() {
    int n;
    std::cin >> n;

    graph.resize(n);
    for (int i = 0; i < n - 1; ++i) {
        int u, v;
        std::cin >> u >> v;
        graph[u].emplace_back(u, v);
        graph[v].emplace_back(v, u);
    }

    int r = -1;
    for (int v = 0; v < n; ++v) {
        if (graph[v].size() >= 3) {
            r = v;
            break;
        }
    }

    if (r == -1) {
        std::cout << 1 << std::endl;
        return;
    }

    dfs(r);
    std::cout << ans << std::endl;
}

int main() {
    std::cin.tie(nullptr);
    std::cout.tie(nullptr);
    std::ios::sync_with_stdio(false);

