void DFS(int v, int par = -1)
{
	int _child_num = 0, non_path = -1, _child_id = -1, mx = 0, sum1 = 0, sum2 = 0, sum3 = 0, cnt = 0;
	for(auto u : adj[v]){
		if(u == par)continue;
		DFS(u, v);
		_child_num ++;
		_child_id = u;
		sum1 += dp[u];
		sum2 += mw[u];
		sum3 += pd[u];
		if(path[u])mx = max(mx, dp[u]), cnt ++;
		else non_path = u;
	}
	child[v] = _child_num;
	if(_child_num == 0){
		path[v] = true;
		dp[v] = mw[v] = pd[v] = 1;
		return ;
	}
	else if(_child_num == 1){
		path[v] = path[_child_id];
		if(child[_child_id] == 1)dp[v] = dp[_child_id];
		else dp[v] = pd[_child_id];
		mw[v] = mw[_child_id];
		pd[v] = 1 + mw[_child_id];
		return ;
	}

	if(_child_num >= 3)
	{
		if(cnt == 0)
		{
			dp[v] = sum2;
			mw[v] = sum2;
			pd[v] = sum2;
			return ;
		}
		if(cnt >= 1)
		{
			dp[v] = sum2 - 1;
			mw[v] = sum2 - 1;
			pd[v] = sum2;
			return ;
		}
	}
	else if(_child_num == 2)
	{
		if(cnt == 0)
		{
			dp[v] = sum2;
			mw[v] = sum2;
			pd[v] = sum2;
			return ;
		}else if(cnt == 2)
		{
			dp[v] = 1;
			mw[v] = 1;
			pd[v] = 2;
			return ;
		}else
		{
			if(child[non_path] >= 1)dp[v] = pd[non_path];
			else dp[v] = dp[non_path];
			mw[v] = mw[non_path];
			pd[v] = 1 + mw[non_path];
			return ;
		}
	}

	return ;

}

