#include <bits/stdc++.h>

using namespace std;

#define N 100000

vector<int> g[N + 1];
int non_leaf[N + 1];
bool seen[N + 1];
bool leaf[N + 1];
int ans, n;

// Sort by increasing number of NON-LEAF nodes

bool comp(int a, int b){
	return non_leaf[a] < non_leaf[b];
}

void init(int u){
	int children, v, i;

	seen[u] = true;
	non_leaf[u] = 0;
	children = 0;

	for (i = 0; i < (int)g[u].size(); i++){
		v = g[u][i];

		if (!seen[v]){
			init(v);
			children++;
			non_leaf[u] += non_leaf[v];
		}
	}

	if (children > 0){
		non_leaf[u]++;
	}
	else{
		// printf("%d is leaf\n", u - 1);
		leaf[u] = true;
	}

	sort(g[u].begin(), g[u].end(), comp);
}

bool dfs(int u, bool p){
	int marks, ret, v, i;

	// printf("At %d\n", u - 1);

	seen[u] = true;
	marks = 0;

	// Marking leaves
	if (!p){
		for (i = 0; i < (int)g[u].size() and marks + (int)p < (int)g[u].size() - 1; i++){
			v = g[u][i];

			if (leaf[v]){
				// printf("force painting %d\n", v - 1);
				marks++;
				ans++;
			}
		}
	}

	for (i = 0; i < (int)g[u].size(); i++){
		v = g[u][i];

		if (!seen[v] and !leaf[v]){
			// Edge downwards
			ret = dfs(v, ((marks + (int)p) > 0));
			marks += ret;
		}
	}

	if (marks + (int)p < (int)g[u].size() - 1){
		// printf("At %d marking %d vertices p = %d and marks = %d\n", u - 1, (int)g[u].size() - 1 - marks, p, marks);
		ans += ((int)g[u].size() - 1) - (marks + (int)p);
		marks = (int)g[u].size() - 1;
	}

	return (marks > 0);
}

int main(){
	int root, u, v, i;

	scanf("%d", &n);

	for (i = 1; i <= n - 1; i++){
		scanf("%d%d", &u, &v);
		g[u + 1].push_back(v + 1);
		g[v + 1].push_back(u + 1);
	}

	if (n == 2){
		printf("1\n");
		return 0;
	}

	// Find root
	for (u = 1; u <= n; u++){
		if ((int)g[u].size() >= 2){
			root = u;
			break;
		}
	}

	// Init graph.
	memset(seen, false, sizeof(seen));
	init(root);

	// Without painting first node.
	ans = 0;
	memset(seen, false, sizeof(seen));
	dfs(root, false);

	printf("%d\n", max(1, ans));

	return 0;
}

pub trait Graph<'a> {
    type Edge: 'a;
    type DIter: Iterator<Item = &'a (usize, Self::Edge)>;
    fn vertices(&self) -> usize;
    fn delta(&'a self, v: &usize) -> Self::DIter;
}

pub struct DirectedGraph<E> {
    g: Vec<Vec<(usize, E)>>
}

impl<'a, E: 'a> Graph<'a> for DirectedGraph<E> {
    type Edge = E;
    type DIter = std::slice::Iter<'a, (usize, E)>;
    fn vertices(&self) -> usize {
        self.g.len()
    }
    fn delta(&'a self, v: &usize) -> Self::DIter {
        self.g[*v].iter()
    }
}

impl<E> DirectedGraph<E> {
    pub fn new(n: usize) -> Self {
        DirectedGraph { g: (0..n).map(|_| Vec::new()).collect() }
    }
    pub fn from_iter(n: usize, iter: impl IntoIterator<Item = (usize, usize, E)>) -> Self {
        let mut g = Self::new(n);
        for (f, t, e) in iter {
            g.add_edge(f, t, e);
        }
        g
    }
    pub fn add_edge(&mut self, from: usize, to: usize, e: E) {
        self.g[from].push((to, e));
    }

    pub fn dfs(&self, v: &usize, p: &usize) -> u64 {
        let mut ans = 0u64;
        let mut zeros = 0u64;
        for (t, _) in self.delta(&v) {
            if t == p { continue }
            let res = self.dfs(t, v);
            ans += res;
            if res == 0 { zeros += 1 }
        }
        if zeros > 1 { ans += zeros - 1 }
        ans
    }
}

