pair<int,int> dfs(int x,int p)
{
	pair<int,int> t;
	int a=0,b=0;
	int s=0;
	rep(i,sz(v[x]))
	{
		if (v[x][i]==p) continue;
		s++;
		t=dfs(v[x][i],x);
		a=max(t.first,a);
		b=max(t.second,b);
	}
	if (s==0) return dp[x]={1,0};
	if (s==1) return dp[x]={a,b};
	if (s==2)
	{
		if (b==1) a++,b=0;
		else b=1;
		return dp[x]={a,b};
	}
	a++;
	return dp[x]={a,b};
}
