pair<ll,ll> dfs(ll u, ll p, ll d){
	if(memo[u].first != -1) return memo[u];
	ll zero = 0;
	ll res = 0;
	ll t = inf;
	ll cnt = 0;
	for(auto v : G[u]){
		if(v == p) continue;
		P df = dfs(v,u,d+1);
		if(df.first == 0) zero++;
		else cnt++;
		res += df.first;
		chmin(t, df.second);
	}
	if(zero) zero--;
	if(cnt + zero > 1) t = d;
	return memo[u] = {res + zero, t};
}

