int DP(int u,int fa){
	int vac=0,chil=0;
	f[u] = tkn[u]=0;
	for (int i=0; i< G[u].size(); i++){
		int v= G[u][i];
		if( v==fa) continue;
		f[u]+= DP(v, u);
		++chil;
		if ( !tkn[v]) ++vac;
	}
	if ( vac>1){
		tkn[u] =true;
		f[u] += vac-1;
	}	else
	if ( chil!=vac) tkn[u]=true;
	if ( fa==-1) ++f[u];
	#ifdef che
	debug("fa=%d\tf[%d] = %d\n",fa, u, f[u]);
	#endif
	return f[u];
}
int FindRt(){
	fro=rea=0;
	for (int i=0; i<n; i++){
		lef[i] = -1;
		if ( G[i].size()==1) que[rea++] = i, lef[i] = i;

	}
	while (fro < rea)
		for (int u=que[fro++], i=0,v; i< G[u].size()?v=G[u][i],1:0; i++){
			if( lef[v]==lef[u]) continue;
			if ( lef[v] !=-1) return lef[v];
			lef[v] = lef[u];
