		for(auto &e : tr.edges[now]) {
			int k = dfs(e.to);
			if(k) {
				res = 1;
			} else {
				zerocnt++;
			}
		}
		if(zerocnt >= 2) {
			res = 1;
			ans++;
		}
		return res;
	};

	dfs(0);
	drop(ans + 1);

	return 0;
}

