vector<int> g[N];
int s1[N];
int s2[N];
int b[N];
void dfs(int x,int fa)
{
	s1[x]=0;
	int num=0;
	for(auto v:g[x])
		if(v!=fa)
		{
			dfs(v,x);
			s1[x]+=s1[v];
			if(!s1[v])
				num++;
		}
	if(num)
		s1[x]+=num-1;
}
void dfs2(int x,int fa)
{
	int temp1=s2[x];
	int temp2=(fa?(s2[x]?0:1):0);
	for(auto v:g[x])
		if(v!=fa)
		{
			temp1+=s1[v];
			temp2+=(s1[v]?0:1);
		}
	for(auto v:g[x])
		if(v!=fa)
		{
			s2[v]=temp1-s1[v]+(temp2-!s1[v]?temp2-!s1[v]-1:0);
			dfs2(v,x);
		}
}
void dfs3(int x,int fa)
{
	s1[x]=0;
	int num=0;
	for(auto v:g[x])
		if(v!=fa)
		{
			dfs3(v,x);
			s1[x]+=s1[v];
			if(!s1[v])
				num++;
		}
	if(num)
	{
		s1[x]+=num-1;
		for(auto v:g[x])
			if(v!=fa)
			{
				if(!s1[v]&&num>1)
				{
					b[v]=1;
					num--;
				}
			}
	}
}
void solve()
{
	int n;
	scanf("%d",&n);
	for(int i=1;i<=n;i++)
	{
		g[i].clear();
		b[i]=s1[i]=s2[i]=0;
	}
	int x,y;
	for(int i=1;i<n;i++)
	{
		scanf("%d%d",&x,&y);
      x++;
      y++;
		g[x].push_back(y);
		g[y].push_back(x);
	}
	dfs(1,0);
	dfs2(1,0);
	pii ans(0x7fffffff,0);
	for(int i=1;i<=n;i++)
		ans=min(ans,pii(s1[i]+s2[i]+1,i));
	for(int i=1;i<=n;i++)
	{
		b[i]=0;
		s1[i]=0;
	}
	dfs3(ans.second,0);
	b[ans.second]=1;
	printf("%d\n",ans.first);
}
