using ll = long long;

int N;
vector<vector<int>> graph;

pair<int, bool> solve(int v, int p) {
    int ans = 0, nonzero = 0;
    int n_children = graph[v].size() - (p == -1 ? 0 : 1);
    bool im = false;
    for (int w : graph[v]) {
        if (w == p) continue;
        int sa; bool sim;
        tie(sa, sim) = solve(w, v);
        ans += sa;
        im = im || sim;
        if (sa != 0) nonzero += 1;
    }
    ans += max(0, n_children-1 - nonzero);
    if (nonzero == n_children) im = false;
    if (p == -1 && im) ans += 1;
    // cout << v << " " << p << " " << n_children << " " << nonzero << " " << im << " " << ans << endl;
    return make_pair(ans, im);
}

int main() {
    cin.tie(0); ios::sync_with_stdio(false);
    cin >> N;
    graph.resize(N);
    for (int j = 0; j < N-1; ++j) {
        int x, y;
        cin >> x >> y;
        graph[x].push_back(y);
        graph[y].push_back(x);
    }

    int start = -1;
    for (int j = 0; j < N; ++j) {
        if (graph[j].size() >= 2) {
            start = j;
            break;
        }
    }
    cout << (start == -1 ? 1 : solve(start, -1).first) << endl;

    return 0;
}

