void solve(Graph &G, int cur, int par=-1) {
    if(~dp[cur]) return;

    vector<int> vals;
    dp[cur] = 0;
    for(auto to : G[cur]) {
        if(to == par) continue;
        solve(G, to, cur);
        vals.push_back(dp[to]);
