const int MAXN = 1e5+5;

ll n;
vector<int> g[MAXN];
int dp1[MAXN], dp2[MAXN];

void dfs(int v, int f = -1) {
	int ct0 = 0;
	int ct = 0;

	for (int u : g[v]) {
		if (u == f)
			continue;
		dfs(u, v);
		ct++;
		ct0 += (dp1[u] == 0);
	}

	if (ct == 1) {
		for (int u : g[v]) {
			if (u == f)
				continue;
			dp1[v] = dp2[u];
		}
		dp2[v] = dp1[v];
	} else {
		for (int u : g[v]) {
			if (u == f)
				continue;
			dp1[v] += dp1[u];
		}

		if (ct0 == 0)
			dp2[v] = dp1[v];
		else {
			dp1[v] += (ct0 - 1);
			dp2[v] = dp1[v] + 1;
		}
	}

	// cout << dp1[v] << ' ' << dp2[v] << endl;
}

int main() {
	cin >> n;
	if (n == 2) {
		cout << "1\n";
		return 0;
	}

	for (int i = 0; i < n-1; ++i) {
		int a, b;
		cin >> a >> b;
		g[a].push_back(b);
		g[b].push_back(a);
	}

	dfs(0, -1);
	cout << dp1[0] << endl;
}

