int N;
vector<int> E[101010];
int dp[101010][3]; // non=0,part=1,fill=2;

void dfs(int cur,int pre) {
	int c=0;
	FORR(e,E[cur]) if(e!=pre) c++;

	if(c==0) {
		dp[cur][0]=0;
		dp[cur][2]=1;
		dp[cur][1]=1<<20;
	}
	else {
		int first=1;
		FORR(e,E[cur]) if(e!=pre) {
			dfs(e,cur);
			if(first) {
				dp[cur][0]=dp[e][0];
				dp[cur][1]=dp[e][1];
				dp[cur][2]=dp[e][2];
				first=0;
			}
			else {
				int d[3]={dp[cur][0],dp[cur][1],dp[cur][2]};
				dp[cur][0]=dp[cur][1]=dp[cur][2]=1<<20;
				dp[cur][1]=min({dp[cur][1],d[2]+dp[e][0],d[0]+dp[e][2]});
				dp[cur][2]=min(dp[cur][2],min(d[1],d[2])+min(dp[e][1],dp[e][2]));
			}
		}

		dp[cur][2]=min(dp[cur][2],min(dp[cur][1],dp[cur][0])+1);
	}
	//cout<<cur<<" "<<dp[cur][0]<<"  "<<dp[cur][1]<<"  "<<dp[cur][2]<<endl;
}


