bool dfs(int index)
{
	visited[index] = true;
	int count{};
	for (auto& e: edges[index])
	{
		if (visited[e]) continue;
		if (dfs(e)) count++;
	}
	if (edges[index].size() > 2)
	{
		int diff{std::max(0, (int)edges[index].size() - 2 - count)};
		ans += diff;
		count += diff;
	}
	return count > 0;
}

