int rec(int cur, int pre)
{
    if(g[cur].size()==1)
    {
        // leaf
        return 0;
    }
    int cnt = 0, sum = 0;
    for(auto v:g[cur])
    {
        if(v==pre) continue;
        int tmp = rec(v, cur);
        if(tmp)
        {
            cnt++;
            sum += tmp;
