    int k = 0;
    for (int i = 0 ; i < n ; i ++) {
        int tmp = Find(i);
        if (!vis[tmp]) {
            vis[tmp] = ++k;
            q[k].push(a[i]);
        }
        else q[vis[tmp]].push(a[i]);
    }
    if (k == 1) {
        printf("0\n");
        return ;
    }
    ll ans = 0;
    for (int i = 1 ; i <= k ; i ++) {
        if (q[i].empty()) continue;
        ans += q[i].top();
        q[i].pop();
        while(!q[i].empty()) {
            pp.push(q[i].top());
            q[i].pop();
        }
    }
    int sum = k - 2;
    int flag = 1;
    while(sum--) {
        if (pp.empty()) {
            flag = 0;
            break;
        }
        ans += pp.top();
        pp.pop();
    }
    if (!flag) printf("Impossible\n");
    else printf("%lld\n", ans);
}

