void addpath(int i,int j){
	++szp;
	pth[szp].ne=mp[i];
	pth[szp].tow=j;
	mp[i]=szp;
	deg[i]++;
}

void dfs1(int i,int j){
	if (vis[i]!=0) return;
	vis[i]=j;
	int po=mp[i];
	while (po!=-1){
		if (vis[pth[po].tow]==0){
			bro[pth[po].tow]=son[i];
			son[i]=pth[po].tow;
		}
		dfs1(pth[po].tow,j+1);
		po=pth[po].ne;
	}	
}
void dfs2(int i){
	int j=son[i];
	if (j==-1){
		left[i]=1;
		dp[i]=1;
		return;
	}
	while (j!=-1){
		dfs2(j);
		left[i]+=left[j];
		dp[i]+=dp[j];
		j=bro[j];
	}
	j=son[i];
	if (j!=-1&&bro[j]!=-1)
	while (j!=-1){
		if (dp[j]==1&&left[j]==1){
			dp[i]--;
			return;
		}
		j=bro[j];
	}

}


