vector <vector <int> > g;

int dfs (int v, int p, int val) {
    int z = 0, sum = 0;
    for (int j = 0; j < g[v].size(); j++) {
        int u = g[v][j];
        if (u == p)
            continue;
        int val = dfs(u, v, sum);
        sum += val;
        z += !val;
    }
    return sum + z - (z != 0);
}

