bool dfs_path(int v, int par) {
	if ((int)adj[v].size() - (par > 0) == 0)
		return ispath[v] = true;
	else if ((int)adj[v].size() - (par > 0) == 1) {
		for (auto i : adj[v])
			if (i != par)
				return dfs_path(i, v);
	}
	else {
		for (auto i : adj[v])
			if (i != par)
				dfs_path(i, v);
		return ispath[v] = false;
	}
}

void dfs_dp(int v, int par) {
	if (ispath[v]) {
		dp[v] = 1;
		return;
	}
	int res = 0;
	bool flag = false;
	for (auto i : adj[v])
		if (i != par) {
			dfs_dp(i, v);
			res += dp[i];
			if (ispath[i])
				flag = true;
		}
	if (!flag)
		dp[v] = res;
	else
		dp[v] = res - 1;
}

