int solve(int root, int parent){
    int nonsolved = 0;
    int solved = 0;
    int ans = 0;
    for(auto xt : adj[root]){
        if(xt == parent) continue;
        int st = solve(xt, root);
        ans += st;
        if(!st) nonsolved++;
        else solved++;
    }
    int dis = max(0, nonsolved - 1);
    if(parent == -1 && solved >= 1) {
        dis = max(1, dis);
    }
    //if(dis) printf("%d\n", root);
