const int N = 1e5 + 5;
int n;
struct Edge {
	int to;
	int next;
}edge[N * 2];
int head[N];
int cnt;
void AddEdge(int fr, int to) {
	edge[++cnt].to = to;
	edge[cnt].next = head[fr];
	head[fr] = cnt;
}
int d[N];
int DFS(int x, int fa) {
	int t = d[x] - 2;
	if (fa == 0) t++;
	t = max(t, 0);
	int re = 0;
	for (int i = head[x]; i; i = edge[i].next) {
		if (edge[i].to != fa) {
			int tmp = DFS(edge[i].to, x);
			re += tmp;
			if (tmp) t--;
		}
	}
	re += max(t, 0);
	//cerr << x << " " << re << endl;
	return re;
}
