pii cnt[100005];
bool mark[100005];
void dfs(int u,int p){
  dist[u]=dist[p]+1;
  par[u]=p;
  for(auto x:adj[u])
    if(x!=p)
      dfs(x,u);
}
void solve(){
  int n,i,u,v,c1,c2,res=0;
  cin>>n;
  for(i=0;i<n-1;i++){
    cin>>u>>v;
    u++,v++;
    adj[u].pb(v);
    adj[v].pb(u);
  }
  dfs(1,0);
  u=0;
  for(i=1;i<=n;i++)
    if(dist[i]>dist[u])
      u=i;
  dfs(u,0);
  v=0;
  for(i=1;i<=n;i++)
    if(dist[i]>dist[v])
      v=i;
  if(dist[v]&1){
    c1=v;
    for(i=0;i<dist[v]/2;i++)
      c1=par[c1];
    c2=c1;
  }
  else{
    c1=v;
    for(i=0;i<dist[v]/2-1;i++)
      c1=par[c1];
    c2=par[c1];
  }
  dist[c1]=dist[c2]=0;
  dfs(c1,c2);
  dfs(c2,c1);
  for(i=1;i<=n;i++)
    D[dist[i]].pb(i);
  for(i=n;i>0;i--){
    set<int> p;
    for(auto x:D[i]){
      p.insert(par[x]);
      if(mark[x])
        cnt[par[x]].F++;
      else
        cnt[par[x]].S++;
