        res+=cnt[x].S-1;
        mark[x]=1;
      }
      cnt[x].F=cnt[x].S=0;
    }
  }
  if(c1!=c2 and !mark[c1] and !mark[c2]){
    res++;
  }
  cout<<res;
}

