#include "bits/stdc++.h"
using namespace std;
typedef long long li;

li n;
vector<vector<li>> g;
li rec(li pos, li parent, bool parent_antenna) {
    if (g[pos].size() == 1 && parent != -1) {
        if (parent_antenna) {
            return 0;
        } else {
            return 1;
        }
    }

    bool next_parent_antenna = parent_antenna || (g[pos].size() >= 3);
    li sum = 0;
    li zeros = 0;
    for (auto next : g[pos]) {
        if (next == parent) {
            continue;
        }
        li sub = rec(next, pos, next_parent_antenna);
        sum += sub;
        if (sub == 0) {
            zeros++;
        }
    }
    li zero_cost = max(zeros - (parent_antenna ? 1 : 0), 0LL);
    return sum + zero_cost;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

