        g[b].push_back(a);
    }

    for (int i = 0; i < n; ++i) {
        if (g[i].size() == 1) {
            li ans = min(rec(i, -1, false), rec(i, -1, true) + 1);
            cout << ans << endl;
            break;
        }
    }

    return 0;
}

