#include <bits/stdc++.h>
using namespace std;
const int N = 1e5 + 5;
int n;
struct Edge {
	int to;
	int next;
}edge[N * 2];
int head[N];
int cnt;
void AddEdge(int fr, int to) {
	edge[++cnt].to = to;
	edge[cnt].next = head[fr];
	head[fr] = cnt;
}
int d[N];
bool v[N];
int Find(int x, int fa) {
	if (d[x] > 2) return x;
	for (int i = head[x]; i; i = edge[i].next) {
		if (edge[i].to != fa) {
			return Find(edge[i].to, x);
		}
	}
	return x;
}
int main() {
	scanf("%d", &n);
	for (int a, b, i = 1; i < n; i++) {
		scanf("%d%d", &a, &b);
		d[++a]++;
		d[++b]++;
		AddEdge(a, b);
		AddEdge(b, a);
	}
	bool flag = 0;
	for (int i = 1; i <= n; i++) {
		if (d[i] > 2) {
			flag = 1;
			break;
		}
	}
	if (!flag) {
		printf("1\n");
		return 0;
	}
	int ans = 0;
	for (int i = 1; i <= n; i++) {
		if (d[i] == 1) {
			v[Find(i, 0)] = 1;
			ans++;
		}
	}
	for (int i = 1; i <= n; i++) {
		if (v[i]) {
			ans--;
		}
	}
	printf("%d\n", ans);
	return 0;
}

