    auto [x, y] = dfs(v, u);
    if (y) ok = true;
    res += x;
    ++cnt;
  }
  bool res_ok;
  if (cnt == 0 || (cnt == 1 && ok)) res = 1, res_ok = true;
  else if (ok) --res, res_ok = false;
  if (p == -1 && cnt == 1) ++res;
  if (p == -1 && cnt == 1 && ok) --res;
  return {res, res_ok};
}

