	int ans1, ans2, root, u, v, i;

	scanf("%d", &n);

	for (i = 1; i <= n - 1; i++){
		scanf("%d%d", &u, &v);
		g[u + 1].push_back(v + 1);
		g[v + 1].push_back(u + 1);
	}

	if (n == 2){
		printf("1\n");
		return 0;
	}

	// Find root
	for (u = 1; u <= n; u++){
		if ((int)g[u].size() >= 2){
			root = u;
			break;
		}
	}

	// Init graph.
	memset(seen, false, sizeof(seen));
	init(root);

	// Without painting first node.
	ans = 0;
	memset(seen, false, sizeof(seen));
	dfs(root, false);
	ans1 = ans;

	// Painting first node???
	ans = 1;
	memset(seen, false, sizeof(seen));
	dfs(root, true);
	ans2 = ans;

	printf("%d\n", max(1, min(ans1, ans2)));

	return 0;
}

