#include <algorithm>

using namespace std;

const int N = 1e6 + 10, M = 2e6 + 10;

inline void Read(int &x) {
	x = 0; register char cc = '\0'; int fff = 1;
	for (; cc < '0' || cc > '9'; cc = getchar())
		if (cc == '-') fff = -1;
	for (; cc >= '0' && cc <= '9'; cc = getchar())
		x = (x << 1) + (x << 3) + (cc & 15);
	x *= fff;
}

bool ischain;
int n, rt, tot, fans, deg[N], f[N], Head[N], Next[M], Adj[M];

void DFS(int x, int fat) {
	if (deg[x] > 1) {
		int t = 0;
		for (int e = Head[x]; e; e = Next[e])
			if (Adj[e] != fat) {
				DFS(Adj[e], x);
				f[x] |= f[Adj[e]];
				if (f[Adj[e]]) ++t;
			}
		if (fat) {
			if (deg[x] > 2) f[x] = 1;
			if (t < deg[x] - 2)
				fans += deg[x] - 2 - t;
		}
		else {
			if (deg[x] > 1) f[x] = 1;
			if (t < deg[x] - 1)
				fans += deg[x] - 1 - t;
		}
	}
}

int main()
{
	Read(n);
	if (n == 1) {
		printf("0\n");
		return 0;
	}
	for (int i = 1, x, y; i < n; ++i) {
		Read(x), Read(y);
		++deg[x], ++deg[y];
		Next[++tot] = Head[x]; Head[x] = tot; Adj[tot] = y;
		Next[++tot] = Head[y]; Head[y] = tot; Adj[tot] = x;
	}
	for (int i = 1; i <= n; ++i)
		if (deg[i] > 2) {
			rt = i;
			ischain = true;
			break;
		}
	DFS(rt, 0);
	fans = max(fans, 1);
	printf("%d\n", fans);

	return 0;
}

