using Graph = vector< vector<int> >;
int deg[100010];

int solve(Graph &G, int cur, int par=-1) {
    int ret = 0;

    bool appear_zero = false;
    for(auto to : G[cur]) {
        if(to == par) continue;
        int val = solve(G, to, cur);

        if(val != 0) ret += val;
        else {
            if(!appear_zero) {
                appear_zero = true;
            }
            else {
                ret++;
            }
        }
    }

    return ret;
}

