void dfs1(int v, int par = -1) {
  int chi = 0;
  bool allLeaf = true;
  for (int b : es[v])
    if (b != par) {
      chi++;
      dfs1(b, v);
      allLeaf &= isleaf[b];
    }
  if (chi <= 1 && allLeaf)
    isleaf[v] = true;
}

int dfs2(int v, int par = -1) {
  if (isleaf[v]) return 1;

  int ans = 0;
  bool hasleaf = false;
  for (int b : es[v])
    if (b != par) {
      ans += dfs2(b, v);
      if (isleaf[b]) hasleaf = true;
    }
  assert(ans >= 2);
  if (hasleaf) ans--;
  return ans;
}

