const int N=1000010;
int n;
int head[N],nxt[N<<1],to[N<<1],lst=0;
inline void adde(int x,int y) {nxt[++lst]=head[x]; to[lst]=y; head[x]=lst;}
int in[N];
int col[N];
int ans=0;
int lef[N];
int f[N];
void DP(int u,int fr) {
  bool fl=0;
  for(int i=head[u];i;i=nxt[i])
    if(to[i]!=fr) {
      int v=to[i]; DP(v,u);
      lef[u]+=lef[v];
      f[u]+=f[v];
      fl|=lef[v]==1;
    }
  if(lef[u]<=1) f[u]=1,lef[u]=1;
  else f[u]-=fl;
}
