#include<bits/stdc++.h>
using namespace std;

const int N = 1e5 + 10;
int dp[2][N], sz[N];
bool f[N], g[N];
vector<int> adj[N];

void dfs(int root, int par) {
    bool flag1 = false, flag2 = false, tmp = false, tmp2 = false;
    sz[root] = 1;
    dp[1][root] = dp[0][root] = 1;
    int cnt = 0, cnt2 = 0;
    f[root] = true;
    for (int i = 0; i < adj[root].size(); i++) {
        int u = adj[root][i];
        if (u ^ par) {
            if (cnt == 0)
                dp[0][root] = 0;
            cnt++;
            dfs(u, root);
            sz[root] += sz[u];
            if (sz[u] == 1)
                g[root] = true;
            tmp2 |= g[u];
            f[root] &= f[u];
            if (f[u] && !flag1)
                flag1 = true;
            else {
                if (dp[1][u] - 1 > 0)
                    dp[1][root] += min(dp[1][u] - 1, dp[0][u]);
                else
                    dp[1][root] += min(dp[1][u], dp[0][u]);
            }
            cnt2 += f[u];
            if (!f[u] && min(dp[1][u], dp[0][u]) > 1)
                tmp = true;
            dp[0][root] += min(dp[1][u], dp[0][u]);
        }
    }
    if (cnt2 > 1 || (cnt2 == 1 && tmp))
        dp[0][root]--;
    if (tmp2 && cnt - cnt2 == 1)
        dp[0][root]++;
    if (cnt > 1)
        f[root] = false;
    return;
}

