void dfs(int v)
{
	mark[v] = true;
	for (int i = 0; i < graph[v].size(); i++)
	{
		int u = graph[v][i];
		if (!mark[u])
		{
			dfs(u);
			if (dp[u] == 0)
			{
				child[v]++;
			}
		}
	}
	for (int i = 0; i < graph[v].size(); i++)
	{
		int u = graph[v][i];
		dp[v] += dp[u];
	}
	dp[v] += max(child[v] - 1, 0);
}

bool isPath()
{
	int cnt = 0;
	for (int i = 0; i < n; i++)
	{
		if (deg[i] == 1)
		{
			cnt++;
		}
		if (deg[i] > 2)
		{
			return false;
		}
	}
	if (cnt != 2)
	{
		return false;
	}
	return true;
}

