template <typename T>
void gi(T &ret) {
	ret = 0; char inp=gc(); int kl=1;
	while (inp<'0' || inp>'9') {if (inp=='-') kl=-1; inp=gc();}
	while ('0'<=inp && inp<='9') ret=(ret<<3)+(ret<<1)+(inp-'0'), inp=gc();
	if (kl<1) ret=-ret;
}

const int MAXN = 1e5+5;
int n, ans = 0, root = 0;
vi adj[MAXN];

int dfs (int now, int par) {
	int ch = 0, dpt = 0;
	for (auto nex : adj[now]) {
		if (nex==par) continue;
		dpt += dfs (nex,now);
		ch++;
	}
	ch--;
	if (ch) {
		if (dpt<ch) {
			ans += ch-dpt;
			dpt = ch;
		}
	} else if (now==root) ans++;
	if (dpt) return 1;
	else return 0;
}

