	gi(n);
	for (int i=1; i<n; i++) {
		int a,b; gi(a); gi(b);
		adj[a].psb(b);
		adj[b].psb(a);
	}
	for (int i=0; i<n; i++) if (sz(adj[i])==2) root = i;
	dfs (root,-1);
	printf ("%d\n", ans);
	return 0;
