const ll INF = 1e9+7;


vector<int>  edge[1000005];
map<int,int> memo[1000005];
int dfs(int n, int b){
	if( memo[n].count(b) ) return memo[n][b];
	if( b >= 0 && edge[n].size() == 1 ) return -1;
	int ret = 0, cnt = 0;
	for(auto t: edge[n]) if( t != b ){
		auto r = dfs(t, n);
		if( r < 0 ) cnt++;
		else ret += r;
	}
	//cout << "dfs: " << n << " " << ret << " " << cnt << endl;
	if( ret == 0 && cnt == 1 ) return memo[n][b] = -1;
	if( cnt > 0 ) ret += cnt-1;
	return memo[n][b] = ret;
}

