		edge[a].push_back(b);
		edge[b].push_back(a);
	}

	int ans = INF;
	rep(i,N) if( edge[i].size() == 1 ){
		int ret = 0, cnt = 0;
		for(auto t: edge[i]){
			auto r = dfs(t, i);
			if( r < 0 ) cnt++;
			else ret += r;
		}
		if( edge[i].size() <= 1 && ret > 0 && cnt == 0 ) ret++;
		if( ret == 0 && cnt == 1 ) ret = 1;
		else if( cnt > 1 ) ret += cnt-1;
		else if( ret > 0 && cnt == 1 ) ret += cnt;
		else if( cnt > 0 ) ret += cnt-1;
		//cout << i << "=" << ret << endl;
		chmin(ans, ret);
	}

	cout << ans << endl;

	return 0;
}

