signed main() {
	INIT;

	VAR(int, n);
	VEC_ROW(int, n - 1, a, b);
	std::vector<std::vector<int>> g(n);
	REP(i, n - 1) {
		g[a[i]].emplace_back(b[i]);
		g[b[i]].emplace_back(a[i]);
	}

	std::vector<bool> deleted(n, false);
	std::vector<int> depthp(n, 0);
	std::vector<int> depthq(n, 0);
	int ans = 0;
	int p = -1;
	[&] {
		int max = 0;
		std::vector<int> depth(n, 0);
		std::function<void(int, int)> dfs = [&](int v, int par) {
			for (auto& to : g[v]) {
				if (to == par) continue;
				if (deleted[to]) continue;
				depth[to] = depth[v] + 1;
				CHMAX(max, depth[to]);
				dfs(to, v);
			}
		};
		dfs(n - 1, -1);
		REP(i, n) {
			if (depth[i] == max) {
				p = i;
				return;
			}
		}
	}();
	int q = -1, D = -1;
	{
		std::function<void(int, int, std::vector<int>&)> dfs = [&](int v, int par, std::vector<int>& d) {
			for (auto& to : g[v]) {
				if (to == par) continue;
				if (deleted[to]) continue;
				d[to] = d[v] + 1;
				dfs(to, v, d);
			}
		};
		dfs(p, -1, depthp);
		REP(i, n) {
			CHMAX(D, depthp[i]);
		}
		REP(i, n) {
			if (depthp[i] == D) {
				q = i;
				break;
			}
		}
		dfs(q, -1, depthq);
	}

	int cnt = 1;
	std::vector<int> path;
	for (int v = p; v != q;) {
		++cnt;
		deleted[v] = true;
		path.emplace_back(v);
		for (auto& to : g[v]) {
			if (deleted[to]) continue;
			if (depthp[to] + depthq[to] != D) continue;
			v = to;
			break;
		}
	}
	deleted[q] = true;
	path.emplace_back(q);

	if (cnt == n) {
		OUT(1)BR;
		return 0;
	}
	ans += 2;
	std::function<int(int, int)> dfs = [&](int v, int par) {
		deleted[v] = true;
		int res = 0;
		std::vector<int> chi;
		for (auto& to : g[v]) {
			if (to == par) continue;
			if (deleted[to]) continue;
			chi.emplace_back(to);
		}
		if (chi.size() == 0) return 0LL;
		if (chi.size() == 1) return dfs(chi[0], v);
		int zero = 0;
		for (auto& c : chi) {
			int t = dfs(c, v);
			if (t == 0) ++zero;
			else res += t;
		}
		if (zero >= 2) res += zero - 1;
		return res;
	};
	for (auto& v : path) {
		ans += dfs(v, -1);
	}
	OUT(ans)BR;
	return 0;
}

