const int MAXN=100000;

int n;
vector<int> adj[MAXN];

int dp[MAXN][2]; // dp[i][j] is the minimum cost of the subtree at i (at least one) (when j==1 there is an antenna in the parent subtree)
bool canempty[MAXN];

void dfs(int at,int par) {
	int nchild=0;
	canempty[at]=true;
	REPSZ(i,adj[at]) {
		int to=adj[at][i]; if(to==par) continue;
		++nchild;
		dfs(to,at);
		if(!canempty[to]) canempty[at]=false;
	}
	if(nchild==0) {
		dp[at][0]=dp[at][1]=1;
	} else if(nchild==1) {
		REPSZ(i,adj[at]) {
			int to=adj[at][i]; if(to==par) continue;
			dp[at][0]=dp[to][0];
			dp[at][1]=canempty[to]?1:dp[to][1];
		}
	} else {
		canempty[at]=false;
		dp[at][0]; int mxspare=0;
		REPSZ(i,adj[at]) {
			int to=adj[at][i]; if(to==par) continue;
			dp[at][0]+=dp[to][1];
			if(canempty[to]) mxspare=max(mxspare,dp[to][1]);
		}
		dp[at][1]=dp[at][0]-mxspare;
	}
	//printf("%d: %d/%d canempty=%d (%d)\n",at,dp[at][0],dp[at][1],canempty[at]?1:0,nchild);
}

