using namespace std;

const int kMaxN = 1e5+10;
const int kInf = (1<<30);

vector<vector<int>> dp;
vector<vector<int>> T;

void DFS(int x, int f) {
	vector<int> sons;	

	for (auto y : T[x]) {
		if (y != f) {
			DFS(y, x);
			sons.push_back(y);
		}
	}

	if (sons.size() == 0) {
		dp[x][0] = 0;
		dp[x][1] = 0;
	} else if (sons.size() == 1) {
		dp[x][0] = dp[sons[0]][0];
		dp[x][1] = dp[sons[0]][1];
	} else {
		for (auto y : sons) {
			dp[x][0] += max(1, dp[y][1]);
		}

		dp[x][1] = kInf;

		if (sons.size() == 2 && (dp[sons[0]][1] == 0 || dp[sons[1]][1] == 0)) {
			if (dp[sons[0]][1] == 0) {
				dp[x][1] = min(dp[x][1], max(1, dp[sons[1]][0]));
			}
			if (dp[sons[1]][1] == 0) {
				dp[x][1] = min(dp[x][1], max(1, dp[sons[0]][0]));
			}
		} else {
			int alt = 0;
			bool zero = true;
			for (auto y : sons) {
				if (dp[y][1] == 0 && zero) {
					zero = false;
				} else if (dp[y][1]	 == 0 && !zero) {
					alt += 1;
				} else {
					alt += dp[y][1];
				}
			}

			dp[x][1] = min(dp[x][1], alt);
		}
	}

	// cerr << x << " " << dp[x][0] << " " << dp[x][1] << "\n";
}

