		T[x].push_back(y);
		T[y].push_back(x);
	}


	if (n == 2) {
		cout << 1 << "\n";
		return;
	}

	int root = 1;

	for (int i = 1; i <= n; ++i) {
		if (T[i].size() > 1) {
			root = i;
			break;
		}
	}

	DFS(root, 0);

	cout << dp[root][1] << "\n";
}


