{
    int sum = 0;
    for(int i = 0; i < G[node].size(); i++)
    {
        int neighb = G[node][i];
        if(neighb == father)
            continue;
        DFS(neighb, node);
        sum += DP[1][neighb];
    }
    DP[1][node] = sum;
    for(int i = 0; i < G[node].size(); i++)
    {
        int neighb = G[node][i];
        if(neighb == father)
            continue;
        if(DP[0][neighb] == 0)
            DP[1][node] = min(DP[1][node], sum - DP[1][neighb]);
    }
    DP[1][node] = max(DP[1][node], 1);
    /*if(DP[1][node] > 0)
