int main() {
    int n;
    cin >> n;

    rep(i,n-1){
        int a, b;
        scanf("%d%d", &a, &b);
        a--; b--; // 0-indexにするため.
        pre_G[a].push_back(b);
        pre_G[b].push_back(a);
    }
    int start = -1;
    rep(i,n){
        if(pre_G[i].size()==1){
            start = i;
            break;
        }
    }

    make_netsukigi(start);
    int ans = 1;

    queue<int> que;
    int ari[n] = {};
    int son[n] = {};
    int nashi[n] = {};
    rep(i,n){
        son[i] = G[i].size();
        if(i == start) continue;
        if(son[i] == 0){
            que.push(i);
        }
    }

    while(que.size()){
        int x = que.front();
        que.pop();
        if(G[x].size()>=2){
            ans += max(0, nashi[x]-1);
            ari[x] = 1;
        }
        if(x == start)break;
        son[par_[x]]--;
        if(son[par_[x]] == 0) que.push(par_[x]);
        if(ari[x] == 0) nashi[par_[x]]++;
    }

    cout << ans << endl;
    return 0;
}

