vector <int> t[100000];
int n, ans;

int solve(int cur, int par) {
	int cnt = 0;
	bool need = false;
	bool same = false;
	for (int i = 0; i < t[cur].size(); i++) {
		if (t[cur][i] == par) continue;
		int xx = solve(t[cur][i], cur);
		if (xx == 1 || xx == 3) need = true;
		if (xx == 2 || xx == 3) cnt++;
		if (xx == 3) same = true;
	}
	bool root = (par == -1);
	//cout << cur << " " << cnt << " " << need << " " << same << endl;
	if (!root) {
		if (cnt == t[cur].size() - 1) {
			if (cnt > 0) return 2;
			else return 1;
		}	
		if (cnt < t[cur].size() - 1) {
			ans += t[cur].size() - 2 - cnt;
			if (cnt > 0 || t[cur].size() - 2 - cnt > 0) return 3;
			else return 1;
		}
	} else {
		int added = 0;
		if (t[cur].size() > cnt + 1) added = t[cur].size() - cnt - 1;
		ans += added;
		if (cnt >= 2) return 0;
		if (added) {
			return 0;
		} else {
			if (same || (need && cnt == 0)) ans++;
		}
		return 0;
	}
	assert(false);
	return 0;
}

