int count(int cur, int parent, int force, vector<vector<int>> &G) {
  vector<pair<int,int>> v;

  for (auto next : G[cur]) {
    if (next != parent) {
      v.push_back({G[next].size(), next});
    }
  }
  sort(v.begin(), v.end(), greater<pair<int,int>>());

  int cnt = 0;
  for (int i = 0; i < v.size(); ++i) {
    int next = v[i].second;
    if (i == v.size() - 1) {
      cnt += count(next, cur, force, G);
      force = 0;
    } else {
      if (force) {
        force = 0;
      }
      cnt += count(next, cur, 1, G);
    }
  }

  // cout << cur << " : " << cnt << " + " << force << " = " << cnt + force << endl;

  return cnt + force;
}

int main() { IO;
  int n;
  cin >> n;

  vector<vector<int>> G(n);
  for (int i = 0; i < n - 1; ++i) {
    int a, b;
    cin >> a >> b;

    G[a].push_back(b);
    G[b].push_back(a);
  }

  int ans = n;
  vector<int> index(n);
  for (int i = 0; i < n; ++i) {
    index[i] = i;
  }
  random_shuffle(index.begin(), index.end());

  int runs = 10000;
  for (int i = 0; i < n; ++i) {
    if (G[i].size() == 1) {
      int cnt = count(index[i], -1, 0, G) + 1;
      ans = min(ans, cnt);
      runs--;
      if (runs == 0) break;
    }
  }

  cout << ans << endl;

  return 0;
}

