int d2[MAXN];

void dfs(const int p, int d, int &lnode, int &maxd) {
  if (visited[p]) return;
  visited[p] = 1;

  for (auto nxt : edges[p]) {
    dfs(nxt, d + 1, lnode, maxd);
  }
  if (d > maxd) {
    maxd = d;
    lnode = p;
  }
}

void dfs2(const int p, int d, int *dd, vector<int> *lvls) {
  // cerr << "dfs2: " << p << "  dep:  " << d << endl;
  if (visited[p]) return;
  visited[p] = 1;
  lvls[d].push_back(p);
  dd[p] = d;
  for (auto nxt : edges[p]) {
    dfs2(nxt, d + 1, dd, lvls);
  }
}

