vector<int> used;

void buildTree(int v){
    used[v]=true;
    for(int i=0;i<g0[v].size();i++){
        int to=g0[v][i];
        if(!used[to]){
            t[v].push_back(to);
            buildTree(to);
        }
    }
    return;
}

int dfs(int v){
    if(t[v].size()==0) return 0;
    int res=0;
    int cnt0=0;
    for(int i=0;i<t[v].size();i++){
        int ret=dfs(t[v][i]);
        cnt0+=(ret==0);
        res+=ret;
    }
    if(cnt0>=1) res+=cnt0-1;
    return res;
}

