void dfs(int x,int fa)
{
	d[x]=0;
	for(int i=0; i<g[x].size(); i++)
	{
		int y=g[x][i];
		if(y==fa)continue;
		dfs(y,x);
		d[x]+=!f[y];
		f[x]+=f[y];
	}
