		f[x]-=f[y];
		if(!f[y]&&--d[x])f[x]--;
		f[y]+=f[x];
		if(!f[x]&&d[y]++)f[y]++;
		sol(y,x);
		if(!f[x]&&--d[y])f[y]--;
		f[y]-=f[x];
		if(!f[y]&&d[x]++)f[x]++;
		f[x]+=f[y];
	}
}

