	scanf("%d",&n); REP(i,n-1) { int a,b; scanf("%d%d",&a,&b); adj[a].PB(b); adj[b].PB(a); }
	if(n==2) { printf("1\n"); return; }
	int root=0; while(SZ(adj[root])<2) ++root;
	dfs(root,-1);
	printf("%d\n",dp[root][1]);
}

