	bool f;
	Data(int ud, int ld, int cnt, bool f):ud(ud), ld(ld), cnt(cnt), f(f){}

	Data operator+(const Data& d){
		ud = min(ud, d.ud);
		ld = max(ld, d.ld);
		cnt += d.cnt;
		f = f | d.f;
		if(ld-ud >= 1 && cnt >= 2)
