    //葉でないところに設置しても方向の特定に役立たないから、葉に設置するのが最善だと思う。
    //アンテナを葉に設置していったとき、どっち向きに移動したかがわかるといい。
    //アンテナを結んだとき、そのパス上の頂点と
    //もし頂点にパス以外の辺がただ一つならその辺と繋がってる頂点を特定できる
    //直径をなす頂点を1つ見つけてそこからdfsする
    //端に到達したとき、行きがけに分岐が3つ以上あったらそこにアンテナを置いて、分岐のカウントを1減らして戻る
    int leaf=0,d=0;
    std::function<void(int,int,int)> treeDFS=[&](int now,int pre,int dist){
        if(dist>=d){
            leaf=now;
            d=dist;
        }
        for(auto v:graph[now]){
            if(v==pre) continue;
            treeDFS(v,now,dist+1);
        }
    };
    treeDFS(0,-1,0);
    int s=leaf;
    treeDFS(leaf,-1,0);
    int e=leaf;
    int ans=2;
