#include <bits/stdc++.h>

using namespace std;

#define N 100000

vector<int> g[N + 1];
int max_degree[N + 1];
bool seen[N + 1];
bool leaf[N + 1];
int ans, n;

// Sort by increasing number of NON-LEAF nodes

bool comp(int a, int b){
	return max_degree[a] > max_degree[b];
}

void init(int u){
	int children, v, i;

	seen[u] = true;
	max_degree[u] = (int)g[u].size();
	children = 0;

	for (i = 0; i < (int)g[u].size(); i++){
		v = g[u][i];

		if (!seen[v]){
			init(v);
			children++;
			max_degree[u] = max(max_degree[u], max_degree[v]);
		}
	}

	if (children == 0){
		// printf("%d is leaf\n", u - 1);
		leaf[u] = true;
	}

	sort(g[u].begin(), g[u].end(), comp);
}

bool dfs(int u, bool p){
	int marks, ret, v, i;

	// printf("At %d\n", u - 1);

	seen[u] = true;
	marks = 0;

	// Marking leaves
	if (!p){
		for (i = 0; i < (int)g[u].size() and marks + (int)p < (int)g[u].size() - 1; i++){
			v = g[u][i];

			if (leaf[v]){
				// printf("force painting %d\n", v - 1);
				marks++;
				ans++;
			}
		}
	}

	for (i = 0; i < (int)g[u].size(); i++){
		v = g[u][i];

		if (!seen[v] and !leaf[v]){
			// Edge downwards
			ret = dfs(v, ((marks + (int)p) > 0));
			marks += ret;
		}
	}

	if (marks + (int)p < (int)g[u].size() - 1){
		// printf("At %d marking %d vertices p = %d and marks = %d\n", u - 1, (int)g[u].size() - 1 - marks, p, marks);
		ans += ((int)g[u].size() - 1) - (marks + (int)p);
		marks = (int)g[u].size() - 1;
	}

	return (marks > 0);
}

int main(){
	int root, u, v, i;

	scanf("%d", &n);

	for (i = 1; i <= n - 1; i++){
		scanf("%d%d", &u, &v);
		g[u + 1].push_back(v + 1);
		g[v + 1].push_back(u + 1);
	}

	if (n == 2){
		printf("1\n");
		return 0;
	}

	// Find root
	for (u = 1; u <= n; u++){
		if ((int)g[u].size() >= 2){
			root = u;
			break;
		}
	}

	// Init graph.
	memset(seen, false, sizeof(seen));
	init(root);

	// Without painting first node.
	ans = 0;
	memset(seen, false, sizeof(seen));
	dfs(root, false);

	printf("%d\n", max(1, ans));

	return 0;
}

