int findD(int x, int y) {
	queue<int> q;
	vector<int> d(n, 0);
	q.push(x);
	d[x] = 1;
	while (!d[y]) {
		int v = q.front();
		q.pop();
		for (int i = 0; i < g[v].size(); i++) {
			if (!d[g[v][i]]) {
				d[g[v][i]] = d[v] + 1;
				q.push(g[v][i]);
			}
		}
	}
	return d[y] - 1;
}

int algo() {

	int sum = 0;

	for (int i = 0; i < n; i++) {
		if (g[i].size() < 3)
			continue;
		int leaves = 0;
		for (int j = 0; j < g[i].size(); j++) {
			int p = i;
			int v = g[i][j];
			while (g[v].size() == 2) {
				if (g[v][0] != p) {
					p = v;
					v = g[v][0];
				}
				else {
					p = v;
					v = g[v][1];
				}
			}
			if (g[v].size() == 1)
				leaves++;
		}
		if (leaves) {
			sum += leaves - 1;
		}
	}

	return sum;
}

