#include <bits/stdc++.h>

using namespace std;

#define N 100000

vector<int> g[N + 1];
int non_leaf[N + 1];
bool seen[N + 1];
int ans, n;

// Sort by increasing number of NON-LEAF nodes

bool comp(int a, int b){
	return non_leaf[a] < non_leaf[b];
}

void init(int u){
	int children, v, i;

	seen[u] = true;
	non_leaf[u] = 0;
	children = 0;

	for (i = 0; i < (int)g[u].size(); i++){
		v = g[u][i];

		if (!seen[v]){
			init(v);
			children++;
			non_leaf[u] += non_leaf[v];
		}
	}

	if (children > 0){
		non_leaf[u]++;
	}

	sort(g[u].begin(), g[u].end(), comp);
}

bool dfs(int u, bool p){
	int marks, ret, v, i;

	// printf("At %d\n", u - 1);

	seen[u] = true;
	marks = 0;

	for (i = 0; i < (int)g[u].size(); i++){
		v = g[u][i];

		if (!seen[v]){
			// Edge downwards
			ret = dfs(v, ((marks + (int)p) > 0));

			if (marks + (int)p == 0 and ret == 0){
				marks++;
				ans++;
			}
			else{
				marks += ret;
			}
		}
	}

	if (marks + (int)p < (int)g[u].size() - 1){
		// printf("At %d marking %d vertices p = %d and marks = %d\n", u - 1, (int)g[u].size() - 1 - marks, p, marks);
		ans += ((int)g[u].size() - 1) - (marks + (int)p);
		marks = (int)g[u].size() - 1;
	}

	return (marks > 0);
}

int main(){
	int ans1, ans2, u, v, i;

	scanf("%d", &n);

	for (i = 1; i <= n - 1; i++){
		scanf("%d%d", &u, &v);
		g[u + 1].push_back(v + 1);
		g[v + 1].push_back(u + 1);
	}

	// Init graph.
	memset(seen, false, sizeof(seen));
	init(1);

	// Without painting first node.
	ans = 0;
	memset(seen, false, sizeof(seen));
	dfs(1, false);
	ans1 = ans;

	// Painting first node???
	ans = 1;
	memset(seen, false, sizeof(seen));
	dfs(1, true);
	ans2 = ans;

	printf("%d\n", max(1, min(ans1, ans2)));

	return 0;
}

