bool is_path(int v, int p) {
    bool ret = true;
    if((int)t[v].size() >= 3) return false;
    for(auto c: t[v]) {
        if(c == p) continue;
        ret = ret & is_path(c, v);
    }
    return ret;
}

int dfs(int v, int p) {
    int ret = 0;
    bool b = false;
    for(auto c: t[v]) {
        if(c == p) continue;
        if(is_path(c, v)) {
            if(!b) b = true;
            else ret++;
        } else {
            ret += dfs(c, v);
        }
    }
    return ret;
}

