vector<vector<int>> dp;
vector<vector<int>> T;

void DFS(int x, int f) {
	vector<int> sons;	

	for (auto y : T[x]) {
		if (y != f) {
			DFS(y, x);
			sons.push_back(y);
		}
	}

	if (sons.size() == 0) {
		dp[x][0] = 0;
		dp[x][1] = 0;
	} else if (sons.size() == 1) {
		dp[x][0] = dp[sons[0]][0];
		dp[x][1] = dp[sons[0]][1];
	} else {
		for (auto y : sons) {
			dp[x][0] += max(1, dp[y][1]);
		}

		int alt = 0;
		bool zero = true;
		for (auto y : sons) {
			if (dp[y][1] == 0 && zero) {
				zero = false;
			} else if (dp[y][1]	 == 0 && !zero) {
				alt += 1;
			} else {
				alt += dp[y][1];
			}
		}

		dp[x][1] = alt;
	}

	// cerr << x << " " << dp[x][0] << " " << dp[x][1] << "\n";
}

int ComputeRoot(int x) {
	if (T[x].size() == 2 && (dp[T[x][0]][1] == 0 || dp[T[x][1]][1] == 0)) {
		if (dp[T[x][0]][1] == 0) {
			return max(1, dp[T[x][1]][0]);
		} else	{
			return max(1, dp[T[x][0]][0]);
		}
	}

	int alt = 0;
	bool zero = true;
	for (auto y : T[x]) {
		if (dp[y][1] == 0 && zero) {
			zero = false;
		} else if (dp[y][1]	 == 0 && !zero) {
			alt += 1;
		} else {
			alt += dp[y][1];
		}
	}

	return alt;
}

void Solve() {
	int n;
	cin >> n;


	T = vector<vector<int>>(n + 1);
	dp = vector<vector<int>>(n + 1, vector<int>(2));

	for (int i = 1; i < n; ++i) {
		int x, y;
		cin >> x >> y;
		++x;
		++y;
		T[x].push_back(y);
		T[y].push_back(x);
	}


	if (n == 2) {
		cout << 1 << "\n";
		return;
	}

	int root = 1;

	for (int i = 1; i <= n; ++i) {
		if (T[i].size() > 1) {
			root = i;
			break;
		}
	}

	DFS(root, 0);

	cout << ComputeRoot(root) << "\n";
}


int main() {
	int tests = 1;

	for (;tests; --tests) {
		Solve();
	}
}

