	int to,next;
}es[maxn*2];
int first[maxn],st=0;
void addE(int a,int b){
	st++;
	es[st].to=b;
	es[st].next=first[a];
	first[a]=st;
}
int f[maxn][2],n,x,y,ans;
bool now_ok[maxn];
void dfs(int v,int fa){
	int son=0,cnt=0,sum=0;
	for(int e=first[v];e;e=es[e].next){
		int to=es[e].to;
		if(to==fa)continue;
		dfs(to,v);
		son++;
		if(f[to][0]==0)cnt++;
	}
	if(son==0){
		f[v][0]=0;
		f[v][1]=1;
		return ;
	}
	int now=0;
	for(int e=first[v];e;e=es[e].next){
		int to=es[e].to;
		if(to==fa)continue;
		if(f[to][0]!=0)now++;
		f[v][0]+=f[to][0];
	}
	if(cnt>1)f[v][0]+=cnt-1;
	if(now==1&&cnt<=1)now_ok[v]=true;
	if(son>1){
		for(int e=first[v];e;e=es[e].next){
			int to=es[e].to;
			if(to==fa)continue;
			f[v][1]+=f[to][0];
			if(f[to][0]==0)f[v][1]++;
		}
	}
	else{
		for(int e=first[v];e;e=es[e].next){
			int to=es[e].to;
			if(to==fa)continue;
			f[v][1]=f[to][1];
		}
	}
}
