using namespace std;

const int N = 1e5 + 5;
vector<int> graph[N];
int deg[N];
int dp[N];
int child[N];
int root;
bool mark[N];
int n;

void dfs(int v)
{
	mark[v] = true;
	for (int i = 0; i < graph[v].size(); i++)
	{
		int u = graph[v][i];
		if (!mark[u])
		{
			dfs(u);
			if (dp[u] == 0)
			{
				child[v]++;
			}
		}
	}
	for (int i = 0; i < graph[v].size(); i++)
	{
		int u = graph[v][i];
		dp[v] += dp[u];
	}
	dp[v] += max(child[v] - 1, 0);
}

bool isPath()
{
	int cnt = 0;
	for (int i = 0; i < n; i++)
	{
		if (deg[i] == 1)
		{
			cnt++;
		}
		if (deg[i] > 2)
		{
			return false;
		}
	}
	if (cnt != 2)
	{
		return false;
	}
	return true;
}

int main() 
{
	cin >> n;
	for (int i = 0; i < n - 1; i++)
	{
		int u, v;
		cin >> u >> v;
		deg[u]++;
		deg[v]++;
		graph[u].push_back(v);
		graph[v].push_back(u);
	}
	if (isPath())
	{
		cout << 1;
		exit(0);
	}
	assert(1 == 1);
	for (int i = 0; i < n; i++)
	{
		if (deg[i] > 1)
		{
			root = i;
			break;
		}
	}
	dfs(root);
	cout << dp[root];


}

