ll INF = 10000000000;
vvl G = vv(100001, 0, 0, ll), dp = vv(100001, 2, INF, ll);
void dfs(ll now, ll from){
  ll c = 0, t;
  for(int i=0;i<G[now].size();i++) if(G[now][i]!=from) c++, t = G[now][i];
  if(c==0){
    dp[now] = vll{0, 1};
    return;
  }
  for(int i=0;i<G[now].size();i++) if(G[now][i]!=from) dfs(G[now][i], now);
  ll s = 0, sa = 0;
  for(int i=0;i<G[now].size();i++){
    if(G[now][i]==from) continue;
    s += dp[G[now][i]][1];
    sa = max(sa, dp[G[now][i]][1]);
  }
  if(c==1) dp[now] = dp[t];
  else dp[now] = vll{s-sa, s};
}
