#include<bits/stdc++.h>
using namespace std;

using Graph=vector<vector<int>>;
Graph g0;
Graph t;
vector<int> used;
int root=-1;

void buildTree(int v){
    used[v]=true;
    for(int i=0;i<g0[v].size();i++){
        int to=g0[v][i];
        if(!used[to]){
            t[v].push_back(to);
            buildTree(to);
        }
    }
    return;
}

int dfs(int v){
    if(t[v].size()==0) return 0;
    int res=0;
    int cnt0=0;
    for(int i=0;i<t[v].size();i++){
        auto ret=dfs(t[v][i]);
        cnt0+=(ret==0);
        res+=ret;
    }
    if(cnt0>=1){
        res+=cnt0-1;
        if(cnt0==t[v].size()-1) res++;
    }
    return res;
}

int main(){
    int n;
    cin>>n;
    g0.assign(n,vector<int>());    
    t.assign(n,vector<int>());
    used.assign(n,0);

    for(int i=0;i<n-1;i++){
        int a,b;
        cin>>a>>b;
        g0[a].push_back(b);
        g0[b].push_back(a);
    }
    if(n==2){
        cout<<1<<endl;
        return 0;
    }

    for(int i=0;i<n;i++){
        if(g0[i].size()>=2){
            root=i;
        }
    }
    buildTree(root);
    auto ret=dfs(root);

    cout<<ret<<endl;
    return 0;
}

