void dfs(int x,int fa)
{
	s1[x]=0;
	int num=0;
	for(auto v:g[x])
		if(v!=fa)
		{
			dfs(v,x);
			s1[x]+=s1[v];
			if(!s1[v])
				num++;
		}
	if(num)
		s1[x]+=num-1;
}
void dfs2(int x,int fa)
{
	int temp1=s2[x];
	int temp2=(fa?(s2[x]?0:1):0);
	for(auto v:g[x])
		if(v!=fa)
		{
			temp1+=s1[v];
			temp2+=(s1[v]?0:1);
		}
	for(auto v:g[x])
		if(v!=fa)
		{
			s2[v]=temp1-s1[v]+(temp2-!s1[v]?temp2-!s1[v]-1:0);
			dfs2(v,x);
		}
}
