			ret.first += ret.second;
			ret.second = 1;
		}
		if(b.first==0){
			ret.first += ret.second;
			ret.second = 1;
		}

		return ret;
	};

	auto f1 = [](pair<int,int> a,int ind,int p){
		if(a==make_pair(-1,-1))return make_pair(0,0);
		return make_pair(a.first,0);
	};

	rerooting<pair<int,int>,decltype(f0),decltype(f1)> rr(E,f0,f1,{-1,-1});

