vector <int> g[MAXN], used[MAXN], DP[MAXN];
int F[MAXN], FS[MAXN], FE[MAXN];
int ans = INF;

void dfs(int u, int pos = -1)
{
	int v, sum = 0, emp = 0;
	if (pos > -1)
		v = g[u][pos];
	else
		v = u;
	if (pos > -1 && F[v] > -1)
	{
		sum = FS[v];
		emp = FE[v];
		vector <int>::iterator it = lower_bound(g[v].begin(), g[v].end(), u);
		sum -= DP[v][it - g[v].begin()];
		emp -= !DP[v][it - g[v].begin()];
		it = lower_bound(g[v].begin(), g[v].end(), F[v]);
		if (!used[v][it - g[v].begin()])
			dfs(v, it - g[v].begin());
		sum += DP[v][it - g[v].begin()];
		emp += !DP[v][it - g[v].begin()];
	}
	else
		REP(i, SZ(g[v]))
	{
		int to = g[v][i];
		if (to == u)
			continue;
		if (!used[v][i])
		{
			used[v][i] = true;
			dfs(v, i);
		}
		sum += DP[v][i];
		emp += !DP[v][i];
	}
	if (pos > -1)
	{
		DP[u][pos] = sum + max(0, emp - 1);
		if (F[v] == -1)
		{
			F[v] = u;
			FS[v] = sum;
			FE[v] = emp;
		}
	}
	else
		ans = min(ans, sum + max(1, emp));
}

