vi adj[SIZE];
int rem[SIZE] = {0};

void reduce(int v, int idx, int p) {
	if (v != p && adj[v].size() == 2) {
		rem[v] = 1;
		int t = ((adj[v][0] == p || rem[adj[v][0]]) ? adj[v][1] : adj[v][0]);
		reduce(t, idx, p);
		return;
	}
	if (p != v) adj[p][idx] = v;
	for (int i = 0 ; i < adj[v].size() ; ++i) {
		int t = adj[v][i];
		if (t == p || rem[t]) continue;
		reduce(t, i, v);
	}
}

int dfs(int v, int p) {
	int s, leaf = 0, sum = 0;
	if (v != p && adj[v].size() == 1) return 1;
	for (auto t: adj[v]) {
		if (t == p || rem[t]) continue;
		sum += dfs(t ,v);
		leaf |= (adj[t].size() == 1);
	}
	return sum - leaf;
}

