signed main() {
	INIT;
	auto start = std::chrono::system_clock::now();

	VAR(int, n);
	VEC_ROW(int, n - 1, a, b);
	std::vector<std::vector<int>> g(n);
	REP(i, n - 1) {
		g[a[i]].emplace_back(b[i]);
		g[b[i]].emplace_back(a[i]);
	}

	std::vector<int> leaf;
	REP(i, n) {
		if (g[i].size() == 1) {
			leaf.emplace_back(i);
		}
	}
	int ans = INFINT;
	std::function<int(int, int)> dfs = [&](int v, int par) {
		int res = 0;
		std::vector<int> chi;
		for (auto& to : g[v]) {
			if (to == par) continue;
			chi.emplace_back(to);
		}
		if (chi.size() == 0) return 0LL;
		if (chi.size() == 1) return dfs(chi[0], v);
		int zero = 0;
		for (auto& c : chi) {
			int t = dfs(c, v);
			if (t == 0) ++zero;
			else res += t;
		}
		if (zero >= 2) res += zero - 1;
		return res;
	};
	REP(i, leaf.size()) {
		CHMIN(ans, dfs(i, -1) + 1);

		auto end = std::chrono::system_clock::now();
		auto res = std::chrono::duration_cast<std::chrono::milliseconds>((end - start)).count();
		if (res > 1900) break;
	}
	OUT(ans)BR;
	return 0;
}

