const int maxn=1e5+5;
using namespace std;

vector<int>G[maxn];
int n,Dp[maxn],Dp2[maxn],pre[maxn],suf[maxn];

void Dfs(int x,int p)
{
	if(G[x].size()==1&&G[x][0]==p)
	{
		Dp[x]=1;
		Dp2[x]=0;
		return;
	}

	int ans=0;

	if(G[x][0]==p)pre[0]=0;

	for(int i=0;i<G[x].size();i++)if(G[x][i]!=p)
	{
		ans++;
		int y=G[x][i];
		Dfs(y,x);
		Dp2[x]+=Dp2[y];
		if(i)pre[i]=pre[i-1]+min(Dp2[y],Dp[y]);
		else pre[i]=min(Dp2[y],Dp[y]);
	}
	else if(i)pre[i]=pre[i-1];


	if(ans>=2)Dp2[x]++;
	bool ok=(ans>=3);

	suf[G[x].size()]=0;
	for(int i=G[x].size()-1;i>=0;i--)
	{
		suf[i]=suf[i+1];
		int y=G[x][i];
		if(y!=p)suf[i]+=min(Dp2[y],Dp[y]);
	}

	int yy=G[x][0],res=INF;
	if(yy!=p)res=Dp[yy]+suf[1];

	for(int i=1;i<G[x].size();i++)if(G[x][i]!=p)
		res=min(res,Dp[G[x][i]]+pre[i-1]+suf[i+1]);

	if(ok)res++;
	Dp[x]=res;

	//cerr<<x<<" "<<Dp[x]<<" "<<Dp2[x]<<endl;
}



