void dfs(int u, int par) {
	long long mx = 0, sz = 0;
	for (int nxt : adj[u]) {
		if (nxt == par)
			continue;
		sz++;
		dfs(nxt, u);
		dp[u][1] += dp[nxt][1];
		mx = max(mx, dp[nxt][1] - dp[nxt][0]);
	}

	dp[u][0] = dp[u][1] - mx;
	if (sz == 0) {
		dp[u][1] = 1;
	} else if (sz >= 2) {
		dp[u][1] -= mx;
	}

}

