int main()
{
	int N; cin >> N;

	vector<vector<int>>E(N);
	for (int i = 0; i < N - 1; i++) {
		int a, b; cin >> a >> b;
		E[a].push_back(b);
		E[b].push_back(a);
	}
	vector<int>id;
	for (int i = 0; i < N; i++)if (E[i].size() == 1)id.push_back(i);

	vector<int>cnt(N);
	for (int i = 0; i < id.size(); i++) {
		queue<int>que;
		que.push(id[i]);
		int pre_q = id[i];
		while (que.size()) {
			int q = que.front(); que.pop();
			if (E[q].size() > 2) {
				cnt[q]++;
				continue;
			}
			for (int j = 0; j < E[q].size(); j++) {
				if (E[q][j] == pre_q)continue;
				pre_q = q;
				que.push(E[q][j]);
				break;
			}
		}
	}

	int ans = 0;
	for (int i = 0; i < N; i++)if (cnt[i])ans += cnt[i] - 1;

	cout << max(1, ans) << endl;

    return 0;
}

