inline void read(int &x) {
  x = 0; char ch;
  while (!isdigit(ch = getchar()));
  do { x = (x << 1) + (x << 3) + ch - '0'; }
  while (isdigit(ch = getchar()));
}

struct edge {
  int nxt, to;
} e[N << 1];
int fir[N], cnt = 1;

inline void addedge(int x, int y) {
  e[++ cnt] = (edge) { fir[x], y }; fir[x] = cnt;
}

int n, dp[N], ans = N;
bool z[N];

inline void Dfs(int x, int f) {
  int son = 0, tot = 0;
  bool tmp = 0;
  for (int i = fir[x]; i; i = e[i].nxt)
    if (e[i].to != f) {
      son ++;
      Dfs(e[i].to, x);
      tot += dp[e[i].to];
      tmp |= z[e[i].to];
    }
  if (son == 0) dp[x] = z[x] = 1;
  else if (son == 1) dp[x] = tot, z[x] = tmp;
  else dp[x] = tot - tmp;
}

inline void solve(int x, int f, int gift, bool zz) {
  int son = 0, tot = gift, Max = zz;
  for (int i = fir[x]; i; i = e[i].nxt)
    if (e[i].to != f) {
      son ++;
      tot += dp[e[i].to];
      Max += z[e[i].to];
    }
  if (son == 0) {
    ans = min(ans, gift + 1 - zz);
    return;
  }
  ans = min(ans, tot - (Max > 0) + 1);
  for (int i = fir[x]; i; i = e[i].nxt)
    if (e[i].to != f) {
      if (son == 1)
	solve(e[i].to, x, gift, zz);
      else
	solve(e[i].to, x, tot - (Max > z[e[i].to]) - dp[e[i].to], 0);
    }
}

