  for (int i = 1, x, y; i < n; i ++) {
    read(x); read(y);
    addedge(x, y); addedge(y, x);
    deg[x] ++; deg[y] ++;
  }
  int rt = 0;
  for (int i = 1; i <= n; i ++)
    if (deg[i] == 1) { rt = i; break; }
  Dfs(rt, 0);
  ans = dp[rt] + 1;
  solve(e[fir[rt]].to, rt, 1, 1);
  printf("%d\n", ans);
  return 0;
}
