    Graph g(n);
    for(int i=0;i<n-1;i++){
        int a,b;
        cin>>a>>b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    bool z=false;
    function<int(int,int)> dfs=[&](int v,int pre){
        int sum=0;
        bool zero=false;
        for(auto to:g[v]){
            if(pre!=to){
                int tmp=dfs(to,v);
                if(!tmp){
                    if(!zero) zero=true;
                    else sum++;
                }
                else{
                    sum+=tmp;
                }
            }
        }
        z=z||zero;
        if(pre==-1){
            if(z && g[v].size()==1) return sum+1;
            else return sum;
        }
        else{
            return sum;
        }
    };
    cout<<dfs(0,-1)<<endl;
    return 0;
}

