        vector<bool> is_path(n);
        function<void (int, int)> dfs = [&](int u, int prev) {
                is_path[u] = true;
                int cnt = 0;
                for (auto v : g[u]) if (v != prev) {
                        cnt ++;
                        dfs(v, u);
                        if (!is_path[v]) is_path[u] = false;
                }
                if (cnt > 1) is_path[u] = false;
        };
        dfs(0, -1);
        int ans = 0;
        function<void (int, int, int)> dfs2 = [&](int u, bool par_path, int prev) {
                int path_cnt = 0;
                int children = 0;
                for (auto v : g[u]) {
                        if (v == prev) {
                                path_cnt += par_path;
                        } else {
                                path_cnt += is_path[v];
                        }
                        children ++;
                }
                ans += max(0, path_cnt - 1);
                bool this_path = par_path && children <= 1;
                for (auto v : g[u]) if (v != prev) {
                        dfs2(v, this_path, u);
                }
        };
        dfs2(0, true, -1);
        printf("%d\n", ans);
        return 0;
}

