void BFS(int st){
        q[1]=st;
        pa[st]=-1;
        int top=1,bot=1;
        while (top<=bot){
                int x=q[top++];
                for(auto y:v[x]) if (y!=pa[x]){
                        pa[y]=x;
                        q[++bot]=y;
                }
        }
