int f[N][2];
int solve(){
        for(int i=n;i>=1;i--){
                int x=q[i];
                if (v[x].size()==1){
                        f[x][1]=1;
                        f[x][0]=0;
                        continue;
                }
                int n1=v[x].size();
                int nson=n1-(i!=1);
                if (nson==1){
                        for(auto y:v[x]) if (y!=pa[x])
                                f[x][0]=f[y][0],f[x][1]=f[y][1];
                        continue;
                }
                int sum=0;
                for(int j=0;j<n1;j++) if (v[x][j]!=pa[x])
                        sum+=f[v[x][j]][1];
                f[x][1]=sum;
                f[x][0]=inf;
                for(int j=0;j<n1;j++) if (v[x][j]!=pa[x]){
                        f[x][1]=min(f[x][1],sum-f[v[x][j]][1]+f[v[x][j]][0]);
                }
        }
        return min(f[q[1]][1],f[q[1]][0]);
