void dfs(int node, int root) {
    int i;

    for (i = 0; i < list[node].size(); i++) {
        int to = list[node][i];

        if (to == root) {
            list[node][i] = list[node].back();
            list[node].pop_back();
            i--;
            continue;
        }

        dfs(to, node);
    }

    if (list[node].empty()) {
        dp[node] = 1;
        up[node] = 0;
        return;
    }

    if (list[node].size() == 1) {
        int to = list[node][0];
        up[node] = up[to];
        dp[node] = dp[to];
        return;
    }

    up[node] = n + 1;
    for (auto to : list[node])
        dp[node] += dp[to];

    int base = dp[node];

    for (auto to : list[node])
        dp[node] = min(dp[node], base - dp[to] + up[to]);
}

