#define N 100008

int n, top, ans;
int f[N], son[N], fa[N], vis[N];
struct road
{
    int next, to;
}r[2*N];

void build(int u, int v)
{
    r[++top].to = v;
    r[top].next = f[u];
    f[u] = top;
}

int dfs(int now, int fa)
{
    if (son[now] > 2)   return now;
    for (int i = f[now]; i; i = r[i].next)
    {
        if (r[i].to == fa) continue;
        now = dfs(r[i].to, now);
    }
    return now;
}

void solve()
{
    for (int i = 0; i < n; i++)
    {
        if (son[i] == 1)
        {
            vis[dfs(i, -1)] = 1;
            ans++;
        }
    }
    for (int i = 0; i < n; i++)
        if (vis[i] == 1)
            ans--;
    ans = max(ans, 1);
}

int main()
{
    int x, y;
    while (~scanf("%d", &n))
    {
        top = ans = 0;
        memset(f, 0, sizeof(f));
        memset(vis, 0, sizeof(vis));
        memset(son, 0, sizeof(son));
        for (int i = 1; i < n; i++)
        {
            scanf("%d%d", &x, &y);
            son[x]++;
            son[y]++;
            build(x, y);
            build(y, x);
        }
        solve();
        printf("%d\n", ans);
    }
    return 0;
}

