const int N = 100005;

int n, d[N][2];
vector<int> e[N];

int f(int x, int y, int z){
    if(d[x][y] >= 0) return d[x][y];
    if(y == 0 && e[x].size() > 2) return d[x][y] = N;
    if(e[x].size() == 1) return d[x][y] = y;
    int r = 0, m = 0;
    for(int i : e[x]){
        if(i == z) continue;
        if(y == 0) return d[x][y] = f(i, y, x);
        int a = f(i, 0, x);
        int b = f(i, 1, x);
        r += b;
        if(!a) m = max(m, b);
    }
    return d[x][y] = r - (e[x].size() > 2) * m;
}

