#include <bits/stdc++.h>
using namespace std;

const int N = 1e6 + 5;

vector <int> G[N];

int n, m, x, y, dp[N], ans = 1e9, Can[N], CanS[N], Son[N], Sum[N];

void get(int x) {
  if(Son[x] <= 1 && CanS[x] == Son[x]) {
    dp[x] = 1;
    Can[x] = 1;
    return;
  }
  else {
    Can[x] = 0;
    dp[x] = Sum[x] - (!!CanS[x]);
  } 
}

void dfs(int x, int f) {
  Sum[x] = 0;
  for(int i = 0; i < (int) G[x].size(); ++ i) {
    int V = G[x][i];
    if(V == f) continue;
    dfs(V, x);
    ++ Son[x];
    Sum[x] += dp[V];
    if(Can[V]) ++ CanS[x];
  }
  get(x);
}

int solve(int x) {
  dfs(x, 0);
  return (Can[x]) ? 0 : dp[x];
}

void io() {
  freopen("beacon.in", "r", stdin);
  freopen("beacon.out", "w", stdout);
}

void dfs2(int x, int f) {
  if(Can[x]) ans = 1;
  ans = min(ans, dp[x] + 1);
  for(int i = 0; i < (int) G[x].size(); ++ i) {
    int V = G[x][i];
    if(V == f) continue;
    int sonx = Son[x], sonV = Son[V],
      dpx = dp[x], dpV = dp[V],
      Canx = Can[x], CanV = Can[V],
      CanSx = CanS[x], CanSV = CanS[V],
      Sumx = Sum[x], SumV = Sum[V];
    CanS[x] -= Can[V];
    Sum[x] -= dp[V];
    -- Son[x];
    get(x);

    CanS[V] += Can[x];
    Sum[V] += dp[x];
    ++ Son[V];
    get(V);

    dfs2(V, x);

    Son[x] = sonx, Son[V] = sonV;
    dp[x] = dpx, dp[V] = dpV;
    Can[x] = Canx, Can[V] = CanV;
    CanS[x] = CanSx, CanS[V] = CanSV;
    Sum[x] = Sumx, Sum[V] = SumV;
  }
}

