int pointer = SIZE;
char buffer[SIZE];

char Advance() {
    if (pointer == SIZE) {
        fread(buffer, 1, SIZE, stdin);
        pointer = 0;
    }
    return buffer[pointer++];
}

int Read() {
    int answer = 0, sign = 1;
    char ch = Advance();
    while (!isdigit(ch) && ch != '-')
        ch = Advance();
    if (ch == '-') {
        sign = -1;
        ch = Advance();
    }
    while (isdigit(ch)) {
        answer = answer * 10 + ch - '0';
        ch = Advance();
    }
    return answer * sign;
}

char ReadCh() {
    char ch = Advance();
    while (!isalpha(ch))
        ch = Advance();
    return ch;
}

const int MAXN = 100000;

vector<int> g[1 + MAXN];
bool has[1 + MAXN];
int answer = 0;

void DFS(int node, int father) {
    int good = 0, sons = 0;
    for (auto &son : g[node])
        if (son != father) {
            DFS(son, node);
            sons++;
            if (has[son])
                good++;
        }
    if (sons <= 1)
        return;
    has[node] = true;
    if (good < sons - 1)
        answer += sons - 1 - good;
}

