    int root;
    for (int i = 1; i <= n; i++)
        if (g[i].size() > 2) {
            chain = false;
            root = i;
            break;
        }
    if (chain) {
        printf("1\n");
        return 0;
    }
    DFS(root, 0);
    printf("%d\n", answer);
    return 0;
}

