int N;
vector<vector<int>> graph;

bool calc(vector<int> vc, vector<bool> vi) {
    const int N = vc.size();
    bool b = false;
    int ct = 0;
    for (int j = 0; j < N; ++j) {
        ct += vc[j] ? 1 : 0;
        if (vc[j] && !vi[j]) return true;
        if (vi[j]) b = true;
    }
    return ct < 2 && b;
}

pair<int, bool> solve(int v, int p) {
    int n_ch = graph[v].size() - (p == -1 ? 0 : 1);
    int ans = 0, n_nz = 0;
    bool im = false;
    vector<int> vc; vector<bool> vi;
    for (int w : graph[v]) {
        if (p == w) continue;
        auto pr = solve(w, v);
        int sa = pr.first; im = im || pr.second;
        vc.push_back(sa != 0); vi.push_back(pr.second);
        ans += sa;
        if (sa != 0) n_nz += 1;
    }
    if (n_nz > 1) im = false;
    if (n_nz == 0) im = true;
    ans += max(0, n_ch - 1 - n_nz);
    if (p == -1 && n_ch - 1 - n_nz <= 0) {
        bool b = calc(vc, vi);
        if(b) ans += 1;
    }
    return make_pair(ans, im);
}

