template<class T> struct TreeOperator{
	using TypeDist = T;
	inline static constexpr size_t bit = 20;
	inline static constexpr TypeDist unit_dist = 0;
	inline static constexpr TypeDist unit_lca = 0;
	inline static constexpr TypeDist func_dist(const TypeDist& parent,const TypeDist& w){return parent+w;}
	inline static constexpr pair<size_t,TypeDist> func_lca(const pair<size_t,TypeDist>& l,const pair<size_t,TypeDist>& r){return make_pair(l.first,l.second+r.second);}
	template<class TypeReroot> inline static constexpr TypeReroot func_reroot(const TypeReroot& l,const TypeReroot& r) {
		return {l.first+r.first+r.second,l.second+r.second};
	}
	template<class TypeReroot> inline static constexpr TypeReroot func_reroot_merge(const TypeReroot& l,const TypeReroot& r) {
		return {l.first+r.first,l.second+r.second};
	}
};

int main() {
	int N; cin >> N;
	Tree<TreeOperator<ll>> tree(N);
	vector<ll> dim(N,0);
	for(int i = 0; i < N-1; ++i) {
		int u,v; cin >> u >> v;
		dim[u]++,dim[v]++;
		tree.make_edge(u,v);
		tree.make_edge(v,u);
	}
	corner(N==2,1);
	int root;
	for(int i = 0; i < N; ++i) if(dim[i]>1) root=i;
	tree.make_depth(root);
	tree.make_child();
	vector<pair<int,int>> dp1(N,{0,0}),dp2(N,{0,0});
	for(int pa:tree.order){
		int m=0,x=0,s=0;
		for(auto e:tree.child[pa]) {
			int ch=e.first;
			m += 1;
			s += dp1[ch].first;
			x += dp1[ch].second;
		}
		//xが1以下ならないのと一緒
		if(x<=1) x=0;
		//絶対にm-1個必要
		if(m-1>x){
			s += (m-1)-x;
			x = m-1;
		}
		//子のいずれかが点灯してるなら自分も点灯
		dp1[pa]={s,bool(x)};
	}
	int ans=N;
	for(int pa:tree.reorder) {
		if(tree.child[pa].empty()) continue;
		int m=bool(tree.depth[pa]),x=dp2[pa].second,s=dp2[pa].first;
		for(auto e:tree.child[pa]) {
			int ch=e.first;
			m += 1;
			s += dp1[ch].first;
			x += dp1[ch].second;
		}
		{
			int a=s,b=x;
			if(b<=1)b=0;
			if(m-1>b){
				a+=(m-1)-b;
				b=m-1;
			}
			chmin(ans,a);
		}
		for(auto e:tree.child[pa]) {
			int ch=e.first;
			m -= 1;
			s -= dp1[ch].first;
			x -= dp1[ch].second;
			{
				int a=s,b=x;
				if(b<=1)b=0;
				if(m-1>b){
					a+=(m-1)-b;
					b=m-1;
				}
				dp2[ch]={a,bool(b)};
			}
			m += 1;
			s += dp1[ch].first;
			x += dp1[ch].second;
		}
	}
	cout << ans << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 1e5 + 5;
const int INF = 1e9 + 5;
vector<int> adj[N];
int dp[N][2], vis[N][2];
int memo[N][2];
int n, ans, vis_id;
vector<int> _t, _d;

int solve(int idx, int flag) {
	if (idx == _t.size()) {
		if (_t.size() > 1 || !flag)
			return 0;
		return INF;
	}

	int &ret = dp[idx][flag];
	if (vis[idx][flag] == vis_id)
		return ret;
	vis[idx][flag] = vis_id;
	ret = INF;
	if (!flag) {
		ret = min(solve(idx + 1, 0) + _t[idx], solve(idx + 1, 1) + _d[idx]);
	} else {
		ret = solve(idx + 1, flag) + _t[idx];
	}
	return ret = min(ret , INF);
}

int dfs(int u, int par, int flag) {

	int &ret = memo[u][flag];
	if (~ret)
		return ret;

	vector<int> t, d;
	for (int nxt : adj[u]) {
		if (nxt == par)
			continue;
		t.push_back(dfs(nxt, u, 1));
		d.push_back(dfs(nxt, u, 0));
	}

	if (t.size() == 0)
		return ret = flag;

	if (!flag) {
		if (d.size() > 1)
			return ret = INF;
		return ret = d[0];
	}

	_t = t;
	_d = d;
	vis_id++;
	return ret = solve(0, 0);
}

int main() {

	memset(memo, -1, sizeof memo);
	int a, b;
	scanf("%d", &n);
	for (int i = 1; i < n; i++) {
		scanf("%d%d", &a, &b);
		adj[a].push_back(b);
		adj[b].push_back(a);
	}

	for (int i = 0; i < n; i++) {
		if (adj[i].size() > 1) {
			printf("%d\n", dfs(i, -1, 1));
			return 0;
		}
	}

	puts("1");

	return 0;
}

