int depth[100000];
void dfs(const VVI& G, int u, int p, int d, VVI& dps){
  depth[u] = d;
  dps[d].PB(u);

  for(int to: G[u]){
	if(to == p) continue;
	dfs(G, to, u, d+1, dps);
  }
}

int main(){
  cin.tie(0);
  ios_base::sync_with_stdio(false);

  int N;
  cin >> N;
  VVI G(N);
  REP(i,N-1){
	int a, b;
	cin >> a >> b;
	G[a].PB(b);
	G[b].PB(a);
  }

  int r = 0;
  REP(i,N) if(SZ(G[i]) == 1){ r = i; break;}
  VVI dps(N+1);
  dfs(G, r, -1, 0, dps);

  int ans = 0;
  vector<bool> mkd(N);
  for(int d=N;d>0;--d){
	for(int u: dps[d]){
	  int sz = 0;
	  for(int to: G[u]){
		if(depth[to] == d+1){
		  if(!mkd[to]) ++sz;
		  else mkd[u] = true;
		}
	  }

	  if(sz > 1){
		ans += sz-1;
		mkd[u] = true;
	  }
	}
  }

  cout << 1+ans << endl;

  return 0;
}

