#include <bits/stdc++.h>
using namespace std;
const int D=1000010;
int n,dp[D],ans=INT_MAX;
vector<int> g[D];
void recalc(int x,int fa){
    int mx=-1,ex=0;
    for (auto i:g[x]){
	if (i==fa) continue;
	dp[x]+=dp[i];
	mx=max(mx,dp[i]);
	++ex;
	if (dp[i]>0) --ex;
    }
    --ex;
    dp[x]-=mx;
    dp[x]+=ex;
}
void dark(int x,int fa){
    int tmp=dp[fa],tmp2=dp[x];
    if (fa){
	recalc(fa,x);
	recalc(x,0);
    }
    if (g[x].size()>=3) ans=min(ans,dp[x]);
    for (auto i:g[x]){
	if (i==fa) continue;
	dark(i,x);
    }
    dp[fa]=tmp;
    dp[x]=tmp2;
}
