int dfs(int v, int pv) {
	int sum = 0;
	int zeros = 0;
	for (int to : edges[v]) {
		if (to == pv) continue;
		int got = dfs(to, v);
		if (got == 0) {
			zeros++;
		}
		sum += got;
	}
	if (zeros > 1) {
		sum += zeros - 1;
	}
	// cout << "v = " << v << ", sum = " << sum << '\n';
	return sum;
}

