inline int read()
{
	int x=0,f=1; char ch=getchar();
	while(ch<'0'||ch>'9'){if(ch=='-')f=-1; ch=getchar();}
	while(ch>='0'&&ch<='9'){x=x*10+ch-'0'; ch=getchar();}
	return x*f;
}
struct edge
{
	int v,next;
}vs[N<<1];
int n,ee,st[N],F[N],sign[N],d[N];
inline void addedge(int u,int v)
{
	vs[++ee].v=v;vs[ee].next=st[u];st[u]=ee;
}
inline void dfs(int rt,int pr)
{
	int cnt=0;
	for(int i=st[rt];i;i=vs[i].next)
	{
		if(vs[i].v==pr) continue;
		cnt++; dfs(vs[i].v,rt);
	}
	if(!cnt) sign[rt]=1,F[rt]=1;
	if(cnt==1)
	{
		for(int i=st[rt];i;i=vs[i].next)
		{
			if(vs[i].v==pr) continue;
			F[rt]=F[vs[i].v]; sign[rt]=sign[vs[i].v];
		}
	}
	if(cnt>1)
	{
		for(int i=st[rt];i;i=vs[i].next)
		{
			if(vs[i].v==pr) continue;
			F[rt]+=F[vs[i].v]; sign[rt]|=sign[vs[i].v];
		}
		if(sign[rt]) F[rt]--,sign[rt]=0;
	}
}
int main()
{
	// freopen("read.in","r",stdin);
	n=read();
	for(int i=1;i<n;i++)
	{
		int u=read()+1, v=read()+1;
		addedge(u,v); addedge(v,u);
		d[u]++; d[v]++;
	}
	int Rt=1; for(;Rt<=n;Rt++) if(d[Rt]>=3) break;
	if(Rt>n) {puts("1"); return 0;}
	dfs(Rt,0); cout << F[Rt] << endl; return 0;
}

