void dfs(int x){
	vis[x]=1;
	if (d[x]==1){
		f0[x]=0;
		f1[x]=1;
		return;
	}
	int s=0,y=0;
	for(int p=h[x];p;p=e[p].nxt)
	if (!vis[e[p].x]){
		fa[e[p].x]=x;
		dfs(e[p].x);
		s++;
		y=e[p].x;
	}
	if (s==1){
		f0[x]=f0[y];
		f1[x]=f1[y];
	}
	else{
		f0[x]=f1[x]=1e9;
		int sum=0;
		for(int p=h[x];p;p=e[p].nxt)
		if (fa[e[p].x]==x)sum+=f1[e[p].x];
		for(int p=h[x];p;p=e[p].nxt)
		if (fa[e[p].x]==x)f1[x]=min(f1[x],sum-f1[e[p].x]+f0[e[p].x]);
	}
}

