const int MAX = 100100;

struct Sol {
  int sum;
  int cnt_zero;
};

vector<int> E[MAX];
Sol down[MAX], up[MAX];
Sol children[MAX];
int parent[MAX];

void DfsDown(int x) {
  for (int i = 0; i < (int)E[x].size(); ++i) {
    if (E[x][i] == parent[x]) {
      swap(E[x][i], E[x].back());
      E[x].pop_back();
      break;
    }
  }

  for (int y: E[x]) {
    parent[y] = x;
    DfsDown(y);

    if (down[y].sum > 0) {
      children[x].sum += down[y].sum;
    } else {
      children[x].cnt_zero++;
    }
  }

  down[x] = children[x];
  if (down[x].cnt_zero > 1) {
    down[x].sum += down[x].cnt_zero - 1;
  }
}

void DfsUp(int x) {
  Sol tmp = children[x];
  if (parent[x] != -1) {
    if (up[x].sum > 0) {
      tmp.sum += up[x].sum;
    } else {
      tmp.cnt_zero++;
    }
  }

  for (int y: E[x]) {
    up[y] = tmp;
    if (down[y].sum > 0) {
      up[y].sum -= down[y].sum;
    } else {
      up[y].cnt_zero--;
    }
    if (up[y].cnt_zero > 1) {
      up[y].sum += up[y].cnt_zero - 1;
    }
    DfsUp(y);
  }
}

