const int N=2e6;
int n,rt1,rt2,dx=0,px;
int d[N+10],deep[N+10];
vector <int> edge[N+10];
void Add(int u,int v) {
    edge[u].push_back(v);
    edge[v].push_back(u);
}
void Dfs1(int x,int fat) {
    deep[x]=dx;
    int cnt=0;
    for (int i=0;i<(int)edge[x].size();i++) {
        int kx=edge[x][i];
        if (kx==fat) continue;
        ++cnt;
        ++dx;
        Dfs1(kx,x);
        --dx;
    }
    if (cnt>=2&&deep[x]>=deep[px]) px=x;
}
void Dfs2(int x,int fat,bool vis) {
    if (x==px) vis=1;
    for (int i=0;i<(int)edge[x].size();i++) {
        int kx=edge[x][i];
        if (kx==fat) continue;
        Dfs2(kx,x,vis);
    }
    if (vis&&d[x]==1) {
        if (rt1) rt2=x;
        else rt1=x;
    }
}
int Solve(int x,int fat) {
    int sum=0;
    int zero=0;
    for (int i=0;i<(int)edge[x].size();i++) {
        int kx=edge[x][i];
        if (kx==fat) continue;
        int nowx=Solve(kx,x);
        sum+=nowx;
        if (nowx==0) zero++;
    }
    if (zero>1) sum+=zero-1;
    return sum;
}
int main() {
    scanf("%d",&n);
    if (n==1) {
        printf("0\n");
