        int u,v;
        scanf("%d%d",&u,&v);
        u++;
        v++;
        Add(u,v);
        d[u]++;
        d[v]++;
    }
    int rt=1;
    for (int i=2;i<=n;i++)
        if (d[i]>=2) rt=i;
    Dfs1(rt,-1);
    Dfs2(rt,-1,0);
    int ans=min(Solve(rt1,-1),Solve(rt2,-1))+1;
    printf("%d\n",ans);
    return 0;
}

