  vector<vector<int>> G(n);
  for (int i = 0; i < n - 1; ++i) {
    int a, b;
    cin >> a >> b;

    G[a].push_back(b);
    G[b].push_back(a);
  }

  int ans = n;
  for (int i = 0; i < n; ++i) {
    if (G[i].size() == 1) {
      int cnt = count(i, -1, 0, G) + 1;
      ans = min(ans, cnt);
    }
  }

  cout << ans << endl;

  return 0;
}

