using namespace std;

const int N = 1e5 + 5;
const int INF = 1e9 + 5;
vector<int> adj[N];
int dp[N][2], vis[N][2];
int n, ans, vis_id;
vector<int> _t, _d;

int solve(int idx, int flag) {
	if (idx == _t.size()) {
		if (_t.size() > 1 || !flag)
			return 0;
		return INF;
	}

	int &ret = dp[idx][flag];
	if (vis[idx][flag] == vis_id)
		return ret;
	vis[idx][flag] = vis_id;
	ret = INF;
	if (!flag) {
		ret = min(solve(idx + 1, 0) + _t[idx], solve(idx + 1, 1) + _d[idx]);
	} else {
		ret = solve(idx + 1, flag) + _t[idx];
	}
	return ret;
}

int dfs(int u, int par, int flag) {
	vector<int> t, d;
	for (int nxt : adj[u]) {
		if (nxt == par)
			continue;
		t.push_back(dfs(nxt, u, 1));
		d.push_back(dfs(nxt, u, 0));
	}

	if (t.size() == 0)
		return flag;

	if (!flag) {
		if (d.size() > 1)
			return INF;
		return d[0];
	}

	_t = t;
	_d = d;
	vis_id++;
	return solve(0, 0);
}

