    p = vector<vector<int> >(size, vector<int>(n));

    //initialize as root = 0
    init(g, root,-1,0);

    for(int k=0; k+1 < size; k++){
      for(int v=0; v<n; v++){
        if(p[k][v] < 0) p[k+1][v] = -1;
        else p[k+1][v] = p[k][p[k][v]];
      }
    }
  }

  //return the node number of lowest common ancestor between u and v
  int get_lca(int u, int v){
    if(d[u] > d[v]) swap(u,v);
    for(int k=0; k<size; k++){
      if( (d[v] - d[u]) >> k & 1){
        v = p[k][v];
      }
    }
    if(u==v) return u;

    for(int k=size-1; k>=0; k--){
      if(p[k][u] != p[k][v]) {
        u = p[k][u];
        v = p[k][v];
      }
    }
    return p[0][u];
  }

  //return depth of node[u]
  int depth(int u){
    return d[u];
  }

  int dist(int u, int v){
    int p = get_lca(u,v);
    int res = d[u] + d[v] - 2*d[p];
    return res;
  }
};

vector<int> r;
vector<int> sz;
vector<bool> path;

int get_size(vector<vector<int>>& G, int pos, int par, bool& is_path){
  int& res = sz[pos];
  res = 1;
  int d = 0;
  for(auto nx : G[pos]) if(nx != par && r[nx] == -1){
    res += get_size(G, nx, pos, is_path);
    d++;
  }

  if( par == -1 ){
    if( d > 2 ) is_path = false;
  }else{
    if( d > 1 ) is_path = false;
  }

  return res;
}

int get_centroid(vector<vector<int>>& G, int pos, int par, int total){
  for(auto nx : G[pos]) if(nx != par && r[nx] == -1){
    if( sz[nx]*2 >= total ){
      return get_centroid(G, nx, pos, total);
    }
  }
  return pos;
}

vector<int> dp;
int centroid_decomposition(vector<vector<int>>& G, int pos, int par, LCA& lca){
  bool is_path = true;
  int total = get_size(G, pos, -1, is_path);
  int c = get_centroid(G, pos, -1, total);

  pos = c;

  path[c] = is_path;

  r[c] = 1;
  for(auto nx : G[c]) if( r[nx] == -1 ){
    centroid_decomposition(G, nx, c, lca);
  }
  r[c] = -1;

  if(total == 1){
    dp[c] = 1;
  }else if(is_path){
    dp[c] = 1;
  }else{
    int tmp = 0;
    for(auto nx : G[c]) if( r[nx] == -1 ){
      tmp += dp[nx];
    }

    dp[c] = tmp;
    for(auto nx : G[c]) if( r[nx] == -1 ){
      if( G[nx].size() <= 2 && path[nx] ){
        if( par!=-1 && (lca.dist(c, par) > lca.dist(nx,par)) ) continue;
        dp[c] = min(dp[c], tmp-dp[nx]);
      }
    }
  }

  return c;
}

