    for (int i = 0, a, b; i < N - 1; i++) { std::cin >> a >> b, T.addEdge(a, b, true); }
    std::vector<int> dp0(N, N), dp1(N, N);
    auto dfs = [&](auto&& self, const int s, const int p) -> void {
        int min = 0, sum = 0, son = 0;
        for (const int to : T[s]) {
            if (to == p) { continue; }
            self(self, to, s);
            son++, sum += dp1[to], chmin(min, dp0[to] - dp1[to]);
        }
        if (son <= 1) {
            dp0[s] = sum + min, chmin(dp1[s], sum + min + 1);
        } else {
            chmin(dp1[s], sum + min);
        }
    };
    int r = -1;
    for (int i = 0; i < N; i++) {
        if (T[i].size() > 2) { r = i; }
    }
    if (r == -1) { return std::cout << 1 << std::endl, 0; }
    dfs(dfs, r, -1);
