        G[u].emplace_back(v);
        G[v].emplace_back(u);
    }

    auto dist = bfs(G,0);
    int s = max_element(all(dist)) - dist.begin();
    auto dfs=[&](auto&& self, int v, int pv)->int {
        int ret = 0;
        int cnt0 = 0;
        for (auto nv : G[v]) {
            if (nv==pv) continue;
            int val = self(self,nv,v);
            ret += val;
            if (!val) cnt0++;
        }
        ret += max(0,cnt0-1);
        return ret;
    };
    cout << dfs(dfs,s,-1)+1 << ln;
}

