public class Main {
    FastScanner in;
    PrintWriter out;

    ArrayList<Integer>[] g;

    int go(int v, int p) {
        ArrayList<Integer> ch = new ArrayList<>();
        for (int to : g[v]) {
            if (to == p) {
                continue;
            }
            ch.add(go(to, v));
        }
        Collections.sort(ch);
        int sum = 0;
        for (int i = 0; i < ch.size(); i++) {
            sum += Math.max(i == 0 ? 0 : 1, ch.get(i));
        }
        return sum;
    }

    void solve() {
        int n = in.nextInt();
        g = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            g[i] = new ArrayList<>();
        }
        for (int i = 0; i + 1 < n; i++) {
            int fr = in.nextInt();
            int to = in.nextInt();
            g[fr].add(to);
            g[to].add(fr);
        }
        int root = -1;
        for (int i = 0; i < n; i++) {
            if (g[i].size() > 2) {
                root = i;
            }
        }
        if (root == -1) {
            out.println(1);
            return;
        }
        out.println(go(root, -1));
    }

