    }

    static class TaskEAntennasonTree {
        int[] deg;
        int n;
        List<Integer>[] g;
        int[][] memo;

        public void solve(int testNumber, MyInput in, PrintWriter out) {
            n = in.nextInt();
            g = new List[n];
            memo = new int[2][n];
            Arrays.fill(memo[0], -1);
            Arrays.fill(memo[1], -1);
            for (int i = 0; i < n; i++) {
                g[i] = new ArrayList<>();
            }
            deg = new int[n];
            for (int i = 0; i < n - 1; i++) {
                int u = in.nextInt();
                int v = in.nextInt();
                g[u].add(v);
                g[v].add(u);
                deg[u]++;
                deg[v]++;
            }

            for (int i = 0; i < n; i++) {
                if (deg[i] >= 3) {
                    out.println(dfs(i, -1, 0));
                    return;
                }
            }
            out.println(1);
        }

        int dfs(int v, int p, int carry) {
            if (memo[carry][v] >= 0) return memo[carry][v];
            if (deg[v] == 1) {
                return memo[carry][v] = carry;
            }

            if (deg[v] == 2) {
                for (int t : g[v]) {
                    if (t != p) {
                        return memo[carry][v] = dfs(t, v, carry);
                    }
                }
            }

            int res = 0;
            int max = Integer.MIN_VALUE;
            for (int t : g[v]) {
                if (t != p) {
                    int val = dfs(t, v, 1);
                    max = Math.max(max, val - dfs(t, v, 0));
                    res += val;
                }
            }

            return memo[carry][v] = res - max;
        }

    }

    static class MyInput {
        private final BufferedReader in;
        private static int pos;
        private static int readLen;
        private static final char[] buffer = new char[1024 * 8];
        private static char[] str = new char[500 * 8 * 2];
        private static boolean[] isDigit = new boolean[256];
        private static boolean[] isSpace = new boolean[256];
        private static boolean[] isLineSep = new boolean[256];

        static {
            for (int i = 0; i < 10; i++) {
                isDigit['0' + i] = true;
            }
            isDigit['-'] = true;
            isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
            isLineSep['\r'] = isLineSep['\n'] = true;
        }

        public MyInput(InputStream is) {
            in = new BufferedReader(new InputStreamReader(is));
        }

        public int read() {
            if (pos >= readLen) {
                pos = 0;
                try {
                    readLen = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (readLen <= 0) {
                    throw new MyInput.EndOfFileRuntimeException();
                }
            }
            return buffer[pos++];
        }

        public int nextInt() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            int ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public char nextChar() {
            while (true) {
                final int c = read();
                if (!isSpace[c]) {
                    return (char) c;
                }
            }
        }

        int reads(int len, boolean[] accept) {
            try {
                while (true) {
                    final int c = read();
                    if (accept[c]) {
                        break;
                    }
                    if (str.length == len) {
                        char[] rep = new char[str.length * 3 / 2];
                        System.arraycopy(str, 0, rep, 0, str.length);
                        str = rep;
                    }
                    str[len++] = (char) c;
                }
            } catch (MyInput.EndOfFileRuntimeException e) {
            }
            return len;
        }

        static class EndOfFileRuntimeException extends RuntimeException {
        }

    }
}

