  static class TaskE {

    ArrayList<Integer>[] g;

    public void solve(int testNumber, InputReader in, OutputWriter out) {
      int n = in.nextInt();
      g = new ArrayList[n];
      for (int i = 0; i < n; ++i) {
        g[i] = new ArrayList<>();
      }
      for (int i = 0; i < n - 1; ++i) {
        int x = in.nextInt();
        int y = in.nextInt();
        g[x].add(y);
        g[y].add(x);
      }
      int res = Integer.MAX_VALUE;
      for (int i = 0; i < n; ++i) {
        if (g[i].size() > 1) {
          res = dfs(i, -1);
          break;
        }
      }
      if (res == Integer.MAX_VALUE) {
        res = dfs(0, -1);
      }
      res = dfs(0, -1);
      Assert.assertTrue(res > 0);
      out.printLine(res);
    }

    private int dfs(int x, int p) {
      int sum = 0, nz = 0, deg = 0;
      for (int y : g[x]) {
        if (y == p) {
          continue;
        }
        int val = dfs(y, x);
        sum += val;
        if (val == 0) {
          ++nz;
        }
        ++deg;
      }
      if (p == -1 && deg == 1) {
        ++sum;
      } else {
        if (nz > 0) {
          sum += nz - 1;
        }
      }
      return sum;
    }

