        public int dfs(Node root, Node p) {
            int zero = 0;
            int cnt = 0;
            int child = 0;
            for (Node node : root.adj) {
                if (node == p) {
                    continue;
                }
                int ans = dfs(node, root);
                if (ans == 0) {
                    zero++;
                } else {
                    cnt += ans;
                    child++;
                }
            }

            if (zero > 0) {
                cnt += zero - 1;
                child += zero - 1;
                zero = 1;
            }

            if (p == null) {
                if (child == 1) {
                    cnt++;
                }
            }

            return cnt;
        }

