            for (int i = 0; i < n; i++) {
                nodes[i] = new Node();
            }
            for (int i = 0; i < n - 1; i++) {
                Node a = nodes[in.readInt()];
                Node b = nodes[in.readInt()];
                a.adj.add(b);
                b.adj.add(a);
            }

            List<Node> leaf = new ArrayList<>(n);
            for (Node node : nodes) {
                if (node.adj.size() == 1) {
                    leaf.add(node);
                }
            }

            int ans = n;
            long time = System.currentTimeMillis();
            RandomWrapper rw = new RandomWrapper();
            while (System.currentTimeMillis() - time < 1500) {
                Node node = leaf.get(rw.nextInt(0, leaf.size() - 1));
                ans = Math.min(ans, dfs(node, null) + 1);
            }
            out.println(ans);
        }

        public int dfs(Node root, Node p) {
            int zero = 0;
            int cnt = 0;
            for (Node node : root.adj) {
                if (node == p) {
                    continue;
                }
                int ans = dfs(node, root);
                if (ans == 0) {
                    zero++;
                } else {
                    cnt += ans;
                }
            }

            if (zero > 0) {
                cnt += zero - 1;
                zero = 1;
            }

            return cnt;
        }

    }

    static class FastOutput implements AutoCloseable, Closeable, Appendable {
        private StringBuilder cache = new StringBuilder(10 << 20);
