    static class RandomWrapper {
        private Random random;

        public RandomWrapper() {
            this(new Random());
        }

        public RandomWrapper(Random random) {
            this.random = random;
        }

        public int nextInt(int l, int r) {
            return random.nextInt(r - l + 1) + l;
        }

    }

    static class Node {
        List<Node> adj = new ArrayList<>();

    }

    static class FastInput {
        private final InputStream is;
        private byte[] buf = new byte[1 << 13];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastInput(InputStream is) {
            this.is = is;
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    bufLen = -1;
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public int readInt() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

    }
}

import java.util.Scanner;

public class Main {

	public static int n;
	public static int k[];
	public static boolean isC[][];
	public static boolean isK[];

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		n=sc.nextInt();
		int[] a=new int[n-1];
		int[] b=new int[n-1];
		k=new int[n];
		isK=new boolean[n];
		isC=new boolean[n][n];
		for(int i=0;i<n-1;i++) {
			a[i]=sc.nextInt();
			b[i]=sc.nextInt();
			isC[a[i]][b[i]]=true;
			isC[b[i]][a[i]]=true;
			k[a[i]]++;
			k[b[i]]++;
		}
		for(int i=0;i<n;i++) {
			k[i]=Math.max(0, k[i]-2);
			isK[i]=(k[i]>0);
		}
		int ans=1;
		countk(0,-1);

		for(int i=0;i<n;i++) {
			ans+=Math.max(0, k[i]);
		}
		System.out.println(ans);
	}
	public static void countk(int j,int p) {//p:親
		for(int i=0;i<n;i++) {
			if(isC[j][i]&&i!=p) {
				countk(i,j);
				if(isK[i]) {
					k[j]--;
					isK[j]=true;
				}
			}
		}

	}

	}

