import java.io.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.StringTokenizer;

public class Main {
    ArrayList<Integer>[] g;
    HashSet<Integer> ans = new HashSet<>();
    boolean[] used;
    boolean[] marked;
    int[] someLeaf;
    int[] parent;

    int dfs(int v) {
        used[v] = true;
        int leaf = v;
        for (int i = 0; i < g[v].size(); i++) {
            int to = g[v].get(i);
            if (!used[to]) {
                parent[to] = v;
                leaf = someLeaf[to] = dfs(to);
                marked[v] |= marked[to];
            }
        }
        boolean isFirst = true;
        for (int i = 0; i < g[v].size(); i++) {
            int to = g[v].get(i);
            if (parent[to] != v) {
                continue;
            }
            if (!marked[to]) {
                if (!isFirst) {
                    ans.add(someLeaf[to]);
                    marked[v] = true;
                }
                isFirst = false;
            }
        }
        return leaf;
    }

    public void run() throws IOException {
        MyScanner in = new MyScanner(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        int n = in.nextInt();
        g = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            g[i] = new ArrayList<>();
        }
        for (int i = 0; i < n - 1; i++) {
            int a = in.nextInt();
            int b = in.nextInt();
            g[a].add(b);
            g[b].add(a);
        }
        int root = -1;
        for (int i = 0; i < n; i++) {
            if (g[i].size() > 2) {
                root = i;
                break;
            }
        }
        if (root == -1) {
            for (int i = 0; i < n; i++) {
                if (g[i].size() == 1) {
                    out.println("1");
                    //out.println(i + 1);
                    out.close();
                    return;
                }
            }
        }
        parent = new int[n];
        Arrays.fill(parent, -1);
        someLeaf = new int[n];
        used = new boolean[n];
        marked = new boolean[n];
        dfs(root);
        out.println(ans.size());
        //for (int v : ans) {
        //    out.print(v + 1 + " ");
        //}
        out.close();
    }

    public static void main(String[] args) throws IOException {
        new Main().run();
    }

    static class MyScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public MyScanner(Reader r) {
            br = new BufferedReader(r);
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    FastScanner in;
    PrintWriter out;

    ArrayList<Integer>[] g;

    int go(int v, int p) {
        ArrayList<Integer> ch = new ArrayList<>();
        for (int to : g[v]) {
            if (to == p) {
                continue;
            }
            ch.add(go(to, v));
        }
        Collections.sort(ch);
        int sum = 0;
        for (int i = 1; i < ch.size(); i++) {
            sum += Math.max(1, ch.get(i));
        }
        return sum;
    }

    void solve() {
        int n = in.nextInt();
        g = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            g[i] = new ArrayList<>();
        }
        for (int i = 0; i + 1 < n; i++) {
            int fr = in.nextInt();
            int to = in.nextInt();
            g[fr].add(to);
            g[to].add(fr);
        }
        int root = -1;
        for (int i = 0; i < n; i++) {
            if (g[i].size() > 2) {
                root = i;
            }
        }
        if (root == -1) {
            out.println(1);
            return;
        }
        out.println(go(root, -1));
    }

    void run() {
        try {
            in = new FastScanner(new File("Main.in"));
            out = new PrintWriter(new File("Main.out"));

            solve();

            out.close();
        } catch (FileNotFoundException e) {
            e.printStackTrace();
        }
    }

    void runIO() {

        in = new FastScanner(System.in);
        out = new PrintWriter(System.out);

        solve();

        out.close();
    }

    class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(File f) {
            try {
                br = new BufferedReader(new FileReader(f));
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
        }

        public FastScanner(InputStream f) {
            br = new BufferedReader(new InputStreamReader(f));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                String s = null;
                try {
                    s = br.readLine();
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (s == null)
                    return null;
                st = new StringTokenizer(s);
            }
            return st.nextToken();
        }

        boolean hasMoreTokens() {
            while (st == null || !st.hasMoreTokens()) {
                String s = null;
                try {
                    s = br.readLine();
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (s == null)
                    return false;
                st = new StringTokenizer(s);
            }
            return true;
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }

    public static void main(String[] args) {
        new Main().runIO();
    }
}

