/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        MyInput in = new MyInput(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskEAntennasonTree solver = new TaskEAntennasonTree();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskEAntennasonTree {
        int n;
        List<Integer>[] g;

        public void solve(int testNumber, MyInput in, PrintWriter out) {
            n = in.nextInt();
            g = new List[n];
            for (int i = 0; i < n; i++) {
                g[i] = new ArrayList<>();
            }
            for (int i = 0; i < n - 1; i++) {
                int u = in.nextInt();
                int v = in.nextInt();
                g[u].add(v);
                g[v].add(u);
            }
            out.println(Math.max(1, dfs(0, -1).val));
        }

        S dfs(int v, int p) {
            S s = new S();
            int numLeaf = 0;
            for (int t : g[v]) {
                if (t != p) {
                    S ss = dfs(t, v);
                    s.val += ss.val;
                    s.leaf += ss.leaf;
                    if (ss.leaf == 1) {
                        numLeaf++;
                    }
                }
            }
            if (numLeaf == 1 && s.val > 0) {
                s.val++;
            } else if (numLeaf > 0) {
                s.val += numLeaf - 1;
            }
            if (numLeaf == 0) {
                s.leaf++;
            }
//        dump(v, s.val, s.leaf);
            return s;
        }

        class S {
            int val;
            int leaf;

        }

    }

    static class MyInput {
        private final BufferedReader in;
        private static int pos;
        private static int readLen;
        private static final char[] buffer = new char[1024 * 8];
        private static char[] str = new char[500 * 8 * 2];
        private static boolean[] isDigit = new boolean[256];
        private static boolean[] isSpace = new boolean[256];
        private static boolean[] isLineSep = new boolean[256];

        static {
            for (int i = 0; i < 10; i++) {
                isDigit['0' + i] = true;
            }
            isDigit['-'] = true;
            isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
            isLineSep['\r'] = isLineSep['\n'] = true;
        }

        public MyInput(InputStream is) {
            in = new BufferedReader(new InputStreamReader(is));
        }

        public int read() {
            if (pos >= readLen) {
                pos = 0;
                try {
                    readLen = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (readLen <= 0) {
                    throw new MyInput.EndOfFileRuntimeException();
                }
            }
            return buffer[pos++];
        }

        public int nextInt() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            int ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public char nextChar() {
            while (true) {
                final int c = read();
                if (!isSpace[c]) {
                    return (char) c;
                }
            }
        }

        int reads(int len, boolean[] accept) {
            try {
                while (true) {
                    final int c = read();
                    if (accept[c]) {
                        break;
                    }
                    if (str.length == len) {
                        char[] rep = new char[str.length * 3 / 2];
                        System.arraycopy(str, 0, rep, 0, str.length);
                        str = rep;
                    }
                    str[len++] = (char) c;
                }
            } catch (MyInput.EndOfFileRuntimeException e) {
            }
            return len;
        }

        static class EndOfFileRuntimeException extends RuntimeException {
        }

    }
}

import java.util.ArrayList;
import java.util.Scanner;

public class Main {

	public static int n;
	public static int a[];
	public static int b[];
	public static int k[];
	public static boolean isused[];
	public static ArrayList<Integer> use=new ArrayList<Integer>();
	public static boolean isK[];

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		n=sc.nextInt();
		a=new int[n-1];
		b=new int[n-1];
		k=new int[n];
		isK=new boolean[n];
		for(int i=0;i<n-1;i++) {
			a[i]=sc.nextInt();
			b[i]=sc.nextInt();
			k[a[i]]++;
			k[b[i]]++;
			use.add(i);
		}
		for(int i=0;i<n;i++) {
			k[i]=Math.max(0, k[i]-2);
			isK[i]=(k[i]>0);
		}
		int ans=1;
		countk(0,-1);

		for(int i=0;i<n;i++) {
			ans+=Math.max(0, k[i]);
		}
		System.out.println(ans);
	}
	public static void countk(int j,int p) {//p:親
		for(int i:use) {
			if(a[i]==j&&b[i]!=p) {
				use.remove(use.indexOf(i));
				countk(b[i],j);
				if(isK[b[i]]) {
					k[j]--;
					isK[j]=true;
				}
			}
			if(b[i]==j&&a[i]!=p) {
				use.remove(use.indexOf(i));
				countk(a[i],j);
				if(isK[a[i]]) {
					k[j]--;
					isK[j]=true;
				}
			}
		}

	}

	}

