/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskE solver = new TaskE();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskE {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            TaskE.Vertex[] vs = new TaskE.Vertex[n];
            for (int i = 0; i < n; ++i) vs[i] = new TaskE.Vertex();
            for (int i = 0; i < (n - 1); ++i) {
                TaskE.Vertex a = vs[in.nextInt()];
                TaskE.Vertex b = vs[in.nextInt()];
                a.adj.add(b);
                b.adj.add(a);
            }
            for (TaskE.Vertex v : vs)
                if (v.adj.size() == 1) {
                    out.println(Math.max(1, v.solve(null)[1]));
                    break;
                }
        }

        static class Vertex {
            List<TaskE.Vertex> adj = new ArrayList<>();

            public int[] solve(TaskE.Vertex parent) {
                int[] resIfPut = new int[]{1, 1};
                int[] resIfNot = new int[]{0, 0};
                int[] zerosIfPut = new int[]{0, 0};
                int[] zerosIfNot = new int[]{0, 0};
                for (TaskE.Vertex v : adj) {
                    if (v == parent) continue;
                    int[] cur = v.solve(this);
                    resIfNot[0] += cur[0];
                    if (cur[0] == 0) ++zerosIfNot[0];
                    resIfNot[1] += cur[1];
                    if (cur[1] == 0) ++zerosIfNot[1];
                    resIfPut[0] += cur[0];
                    if (cur[0] == 0) ++zerosIfPut[0];
                    resIfPut[1] += cur[0];
                    if (cur[0] == 0) ++zerosIfPut[1];
                }
                resIfPut[0] += Math.max(zerosIfPut[0] - 1, 0);
                resIfPut[1] += zerosIfPut[1];
                resIfNot[0] += Math.max(zerosIfNot[0] - 1, 0);
                resIfNot[1] += zerosIfNot[1];
                return new int[]{Math.min(resIfPut[0], resIfNot[0]), Math.min(resIfPut[1], resIfNot[1])};
            }

        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Queue;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int root = 0;
        int ans = 0;
        if(n == 2){
            System.out.println(1);
            return;
        }
        Node[] node = new Node[n];
        for(int i=0; i<n; i++){
            node[i] = new Node();
        }

        for(int i=0; i<n-1; i++){
            int ma = sc.nextInt();
            int mb = sc.nextInt();
            node[ma].chi.add(mb);
            node[mb].chi.add(ma);
            if(node[ma].chi.size() >= 2) root = ma;
            if(node[mb].chi.size() >= 2) root = mb;
        }

        ArrayDeque<Integer> queue = new ArrayDeque<Integer>();
        ArrayDeque<Integer> stack = new ArrayDeque<Integer>();
        queue.add(root);
        while(queue.size() != 0){
            int next = queue.poll();
            for(int i=0; i<node[next].chi.size(); i++){
                int mchi = node[next].chi.get(i);
                node[mchi].setpar(next);
                queue.add(mchi);
                stack.push(mchi);
            }
        }

        while(stack.size() != 0){
            int next = stack.poll();
            if(node[next].chi.size() > 0){
                node[next].an = true;
                continue;
            }

            if(count(node[next].par, node) > 1){
                node[next].an = true;
                ans++;
            }
        }

        if(ans >= 2){
            System.out.println(ans);
        }else{
            int num = 0;
            for(int i=0; i<n; i++){
                if(node[n].chi.size() >= 2) num++;
            }
            if(num == 1){
                System.out.println(1);
            }else{
                System.out.println(2);
            }
        }

    }

    public static int count(int p, Node[] node){
        int mnum = 0;
        int msize = node[p].chi.size();
        for(int i=0; i<msize; i++){
            if(node[node[p].chi.get(i)].an){
                mnum++;
            }
        }
        return msize - mnum;
    }


}

class Node {
    public int par;
    public ArrayList<Integer> chi;
    public boolean an;

    public Node(){
        chi = new ArrayList<Integer>();
        an = false;
    }

    public void setpar(int p){
        par = p;
        chi.remove((Integer)p);
    }
}

import sun.util.resources.sr.CalendarData_sr_Latn_BA;

import java.io.*;
import java.util.Arrays;
import java.util.StringJoiner;
import java.util.StringTokenizer;

public class Main {

    static int N;
    static int[] A, B;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        A = new int[N-1];
        B = new int[N-1];
        for (int i = 0; i < N - 1; i++) {
            A[i] = sc.nextInt();
            B[i] = sc.nextInt();
        }

        System.out.println(solve());
    }

    static int solve() {
        if( N == 2 ) return 1;

        int[][] G = adjB(N, A, B);

        // 葉をrootにする
        int root = -1;
        for (int i = 0; i < N; i++) {
            if( G[i].length == 1 ) {
                root = i;
                break;
            }
        }


        int[] dp = new int[N];
        boolean[] req = new boolean[N];
        Node[] nodes = order(N, G, root, false);
        for (Node node : nodes) {
            if( node.a == root ) {
                // root is 葉
                int child = G[root][0];
                dp[root] = dp[child];
                if( req[child] ) {
                    dp[root]++;
                }

            } else {

                if( G[node.a].length == 1 ) {
                    dp[node.a] = 0;
                    req[node.a] = true;
                    continue;
                }

                int dir = 0;
                int hasBase = 0;
                for (int b : G[node.a]) {
                    if( b == node.parent ) continue;

                    dir++;
                    if( dp[b] > 0 ) {
                        dp[node.a] += dp[b];
                        hasBase++;
                    }
                }

                if( dir == hasBase ) {
                    req[node.a] = false;

                } else if( dir-1 == hasBase ) {
                    req[node.a] = true;

                } else {
                    req[node.a] = true;
                    dp[node.a] += dir - hasBase - 1;
                }
            }
        }
        // debug(root, dp);
        return dp[root];
    }

    static Node[] order(int N, int[][] G, int root, boolean fromRoot) {
        Node[] q = new Node[N];
        int u = 0, v = 0;
        Node[] ret = new Node[N];
        int idx = fromRoot ? 0 : N-1;
        int d = fromRoot ? 1 : -1;
        q[v++] = new Node(-1, root);
        while( u != v ) {
            Node n = q[u++];
            ret[idx] = n;
            idx += d;
            for (int b : G[n.a]) {
                if( b == n.parent ) continue;

                q[v++] = new Node(n.a, b);
            }
        }
        return ret;
    }

    static class Node {
        int parent, a;

        public Node(int parent, int a) {
            this.parent = parent;
            this.a = a;
        }
    }

    static int[][] adjB(int n, int[] from, int[] to) {
        int[][] adj = new int[n][];
        int[] cnt = new int[n];
        for (int f : from) {
            cnt[f]++;
        }
        for (int t : to) {
            cnt[t]++;
        }
        for (int i = 0; i < n; i++) {
            adj[i] = new int[cnt[i]];
        }
        for (int i = 0; i < from.length; i++) {
            adj[from[i]][--cnt[from[i]]] = to[i];
            adj[to[i]][--cnt[to[i]]] = from[i];
        }
        return adj;
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = nextInt();
            return a;
        }

        int[] nextIntArray(int n, int delta) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = nextInt() + delta;
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++) a[i] = nextLong();
            return a;
        }
    }

    static void writeLines(int[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int a : as) pw.println(a);
        pw.flush();
    }

    static void writeLines(long[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (long a : as) pw.println(a);
        pw.flush();
    }

    static void writeSingleLine(int[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int i = 0; i < as.length; i++) {
            if (i != 0) pw.print(" ");
            pw.print(as[i]);
        }
        pw.println();
        pw.flush();
    }

    static int max(int... as) {
        int max = Integer.MIN_VALUE;
        for (int a : as) max = Math.max(a, max);
        return max;
    }

    static int min(int... as) {
        int min = Integer.MAX_VALUE;
        for (int a : as) min = Math.min(a, min);
        return min;
    }

    static void debug(Object... args) {
        StringJoiner j = new StringJoiner(" ");
        for (Object arg : args) {
            if (arg == null) j.add("null");
            else if (arg instanceof int[]) j.add(Arrays.toString((int[]) arg));
            else if (arg instanceof long[]) j.add(Arrays.toString((long[]) arg));
            else if (arg instanceof double[]) j.add(Arrays.toString((double[]) arg));
            else if (arg instanceof Object[]) j.add(Arrays.toString((Object[]) arg));
            else j.add(arg.toString());
        }
        System.err.println(j.toString());
    }

    static void printSingleLine(int[] array) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int i = 0; i < array.length; i++) {
            if (i != 0) pw.print(" ");
            pw.print(array[i]);
        }
        pw.println();
        pw.flush();
    }

    static int lowerBound(int[] array, int value) {
        int lo = 0, hi = array.length, mid;
        while (lo < hi) {
            mid = (hi + lo) / 2;
            if (array[mid] < value) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    static int upperBound(int[] array, int value) {
        int lo = 0, hi = array.length, mid;
        while (lo < hi) {
            mid = (hi + lo) / 2;
            if (array[mid] <= value) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * @author Pavel Mavrin
 */
public class Main {

    void init(int n, int m) {
        m *= 2;
        this.n = n;
        this.m = m;
        last = 0;
        head = new int[n];
        nx = new int[m];
        dst = new int[m];
        src = new int[m];
        Arrays.fill(head, -1);
    }

    void addEdge(int x, int y) {
        nx[last] = head[x];
        src[last] = x;
        dst[last] = y;
        head[x] = last;
        last++;
        nx[last] = head[y];
        src[last] = y;
        dst[last] = x;
        head[y] = last;
        last++;
    }

    int res = 0;
    boolean qqq = false;

    private boolean dfs(int x, int p) {
        int j = head[x];
        boolean s = false;
        int k = 0;
        while (j >= 0) {
            int y = dst[j];
            if (y != p) {
                if (!dfs(y, x))
                    k++;
                else
                    s = true;
            }
            j = nx[j];
        }
//        System.out.println(x + " " + k);
        if (k >= 2) {
            res += k - 1;
            s = true;
//            System.out.println(res);
        }
        qqq = k > 0;
        return s;
    }

    int n, m;
    int[] head;
    int[] nx;
    int[] src;
    int[] dst;
    int last;

    private void solve() throws IOException {
        int n = nextInt();
        init(n, n - 1);
        int[] d = new int[n];
        for (int i = 0; i < n - 1; i++) {
            int x = nextInt();
            int y = nextInt();
            d[x]++;
            d[y]++;
            addEdge(x, y);
        }
        res = 1;
        for (int i = 0; i < n; i++) {
            if (d[i] > 2) {
                res = 0;
                dfs(i, -1);
                break;
