    public static void solve(StringBuilder out) {
        int n = In.ni();
        IntArrayList[] t = new IntArrayList[n];
        for (int i = 0; i < n; i++) t[i] = new IntArrayList();
        for (int i = 0; i < n - 1; i++) {
            int a = In.ni(), b = In.ni();
            t[a].add(b);
            t[b].add(a);
        }
        if (n == 2) {
            out.append(1);
            return;
        }
        int root = -1;
        for (int i = 0; i < n; i++) if (t[i].size() == 1) root = i;
        boolean[] line = new boolean[n];
        int[] lines = new int[n];
        int p = root;
        int u = t[root].get(0);
        while (t[u].size() == 2) {
            int x = t[u].get(0), y = t[u].get(1);
            int v = x != p ? x : y;
            p = u;
            u = v;
        }
        if (t[u].size() > 2) {
            lines[u] = 1;
        }
        dfs(t, root, u, p, line, lines);
        int ans = 0;
        for (int l : lines) if (l > 0) ans += l - 1;
        out.append(ans);
    }

    public static boolean dfs(IntArrayList[] t, int root, int u, int p, boolean[] line, int[] lines) {
        if (t[u].size() == 1) return line[u] = true;
        if (t[u].size() == 2) {
            int x = t[u].get(0), y = t[u].get(1);
            int v = x != p ? x : y;
            return line[u] = dfs(t, root, v, u, line, lines);
        }
        t[u].iterator().forEachRemaining((int v) -> {
            if (v != p && dfs(t, root, v, u, line, lines)) {
                lines[u]++;
            }
        });
        return line[u] = false;
    }
