			a[i]=sc.nextInt();
			b[i]=sc.nextInt();
			k[a[i]]++;
			k[b[i]]++;
		}
		for(int i=0;i<n;i++) {
			k[i]=Math.max(0, k[i]-2);
			isK[i]=(k[i]>0);
		}
		int ans=1;
		countk(0,-1);

		for(int i=0;i<n;i++) {
