				countk(b[i],j);
				if(isK[b[i]]) {
					k[j]--;
					isK[j]=true;
				}
			}
			if(b[i]==j&&a[i]!=p) {
				countk(a[i],j);
				if(isK[a[i]]) {
					k[j]--;
					isK[j]=true;
				}
			}
		}

	}

