        if (n == 2) {
            DBG(1);
            return;
        }
        edge = new List<int>[n];
        for (int i = 0; i < n; i++)
        {
            edge[i] = new List<int>();
        }
        for (int i = 0; i < n - 1; i++)
        {
            int a, b;
            sc.Multi(out a, out b);
            edge[a].Add(b);
            edge[b].Add(a);
        }
        for (int i = 0; i < n; i++)
        {
            if (edge[i].Count > 1) {
                bool need;
                int a = dfs(i, -1, out need);
                if (need) ++a;
                Prt(a);
                break;
            }
        }
        sw.Flush();
    }
    static List<int>[] edge;
    static int dfs(int p, int par, out bool need) {
        int sum = 0;
        int c = 0;
        int nc = 0;
        foreach (var item in edge[p])
        {
            if (item == par) continue;
            bool nd;
            int a = dfs(item, p, out nd);
            if (nd || a == 0) ++nc;
            sum += a;
            if (a > 0) ++c;
        }
        if (par == -1)
            need = nc > 1;
        else
            need = nc > 0;

        if (c < edge[p].Count - 2) {
            sum += edge[p].Count - 2 - c;
        }
        return sum;
    }

