                foreach (var edge in graph[current])
                {
                    var next = edge.To.Index;
                    if (next == parent)
                    {
                        continue;
                    }

                    children++;
                    var an = Dfs(next, current);
                    antennas += an;

                    if (an > 0)
                    {
                        antennaBranches++;
                    }
                }

                if (children > antennaBranches + 1)
                {
                    antennas += children - (antennaBranches + 1);
                }

                return antennas;
            }
        }
    }
}

