    static List<int>[] edge;
    static int dfs(int p, int par, out bool need) {
        int sum = 0;
        int c = 0;
        int nc = 0;
        foreach (var item in edge[p])
        {
            if (item == par) continue;
            bool nd;
            int a = dfs(item, p, out nd);
            if (nd) ++nc;
            sum += a;
            if (a > 0) ++c;
        }
        if (par == -1)
            need = c < edge[p].Count | nc > 1;
        else
            need = c < edge[p].Count - 1 | nc > 0;

        if (c < edge[p].Count - 2) {
            sum += edge[p].Count - 2 - c;
        }
        return sum;
    }

