class Myon
{
    public Myon() { }
    public static int Main()
    {
        new Myon().calc();
        return 0;
    }


    Scanner cin;


    int N;
    int[] A;
    int[] B;
    List<int>[] es;

    void calc()
    {
        cin = new Scanner();
        DateTime dt = DateTime.Now;
        N = cin.nextInt();
        A = new int[N];
        B = new int[N];
        es = new List<int>[N];

        for (int i = 0; i < N; i++)
        {
            es[i] = new List<int>();
        }

        int[] sum = new int[N];
        for (int i = 0; i < N - 1; i++)
        {
            A[i] = cin.nextInt();
            B[i] = cin.nextInt();
            sum[A[i]]++;
            sum[B[i]]++;
            es[A[i]].Add(B[i]);
            es[B[i]].Add(A[i]);
        }

        int ans = 99999999;
        for (int i = 0; i < N; i++)
        {
            if(sum[i] == 1)
            {
                ans = Math.Min(ans, dfs(i, -1) + 1);
                if ((DateTime.Now - dt).TotalMilliseconds > 1500) break;
            }
        }

        Console.WriteLine(ans);
    }

    int dfs(int a, int pre)
    {
        int ans = 0;
        int tmp = 0;
        foreach (var next in es[a])
        {
            if (next == pre) continue;
            tmp++;
            ans += dfs(next, a);
        }
        ans = Math.Max(ans, tmp - 1);
        return ans;
    }
}


