class Solver {
    StreamWriter sw;
    Scan sc;
    void Prt(string a) => sw.WriteLine(a);
    void Prt<T>(IEnumerable<T> a) => Prt(string.Join(" ", a));
    void Prt(params object[] a) => Prt(string.Join(" ", a));
    public Solver(StreamWriter sw) {
        this.sw = sw;
        this.sc = new Scan();
    }

    public void solve() {
        int n = sc.Int;
        edge = new List<int>[n];
        for (int i = 0; i < n; i++)
        {
            edge[i] = new List<int>();
        }
        for (int i = 0; i < n - 1; i++)
        {
            int u, v;
            sc.Multi(out u, out v);
            edge[u].Add(v);
            edge[v].Add(u);
        }
        if (edge.Max(x => x.Count) <= 2) {
            Prt(1);
            return;
        }
        lc = new int[n];
        dfs(0, -1);
        Prt(lc[0] - dfs2(0, -1));
    }
    List<int>[] edge;
    int[] lc;
    int dfs(int p, int par) {
        int res = edge[p].Count == 1 ? 1 : 0;
        foreach (var item in edge[p])
        {
            if (item == par) continue;
            res += dfs(item, p);
        }
        return lc[p] = res;
    }
    int dfs2(int p, int par) {
        int res = 0;
        bool f = false;
        foreach (var item in edge[p])
        {
            if (item == par) continue;
            res += dfs2(item, p);
            f |= lc[item] == 1;
        }
        if (edge[p].Count > 2 && f) ++res;
        return res;
    }
}

