namespace Kujikatsu102.Questions
{
    /// <summary>
    /// https://atcoder.jp/contests/apc001/tasks/apc001_e
    /// </summary>
    public class QuestionG : AtCoderQuestionBase
    {
        public override void Solve(IOManager io)
        {
            var n = io.ReadInt();
            var graph = new BasicGraph(n);

            for (int i = 0; i < n - 1; i++)
            {
                var a = io.ReadInt();
                var b = io.ReadInt();
                graph.AddEdge(new BasicEdge(a, b));
                graph.AddEdge(new BasicEdge(b, a));
            }

            var (antennas, unknowns) = Dfs(0, -1);
            antennas += unknowns;

            io.WriteLine(antennas);

            (int antennas, int unknowns) Dfs(int current, int parent)
            {
                var children = graph[current].Count();

                if (children == 1 && parent != -1)
                {
                    return (0, 1);
                }
                else if (children == 2 && parent != -1)
                {
                    foreach (var edge in graph[current])
                    {
                        var next = edge.To.Index;
                        if (next != parent)
                        {
                            return Dfs(next, current);
                        }
                    }
                    return (0, 0);
                }
                else
                {
                    var antennas = 0;
                    var unknowns = 0;

                    foreach (var edge in graph[current])
                    {
                        var next = edge.To.Index;
                        if (next == parent)
                        {
                            continue;
                        }

                        children++;
                        var (an, unk) = Dfs(next, current);
                        antennas += an;
                        unknowns += unk;
                    }

                    if (unknowns >= 2)
                    {
                        return (antennas + (unknowns - 1), 0);
                    }
                    else
                    {
                        return (antennas, unknowns);
                    }
                }
            }
        }
    }
}

