class Myon
{
    public Myon() { }
    public static int Main()
    {
        new Myon().calc();
        return 0;
    }


    Scanner cin;


    int N;
    int[] A;
    int[] B;
    List<int>[] es;

    void calc()
    {
        cin = new Scanner();
        DateTime dt = DateTime.Now;
        N = cin.nextInt();
        A = new int[N];
        B = new int[N];
        es = new List<int>[N];

        for (int i = 0; i < N; i++)
        {
            es[i] = new List<int>();
        }

        int[] sum = new int[N];
        for (int i = 0; i < N - 1; i++)
        {
            A[i] = cin.nextInt();
            B[i] = cin.nextInt();
            sum[A[i]]++;
            sum[B[i]]++;
            es[A[i]].Add(B[i]);
            es[B[i]].Add(A[i]);
        }

        int ans = 99999999;
        for (int i = 0; i < N; i++)
        {
            if(sum[i] == 1)
            {
                ans = (dfs(i, -1) + 1) / 2;
                break;
            }
        }

        Console.WriteLine(ans);
    }

    int dfs(int a, int pre)
    {
        int ans = 0;
        int tmp = 0;
        int min = 999999;
        int flag = 0;
        int ret = 0;
        foreach (var next in es[a])
        {
            if (next == pre) continue;
            tmp++;
            ret = dfs(next, a);
            ans += ret / 2;
            min = Math.Min(ret, min);
        }
        if (tmp == 0) return 1;
        if(tmp == 1)
        {
            return ret;
        }
        if (min <= 1) flag = 1;
        ans = Math.Max(ans, tmp - 1);
        return ans * 2 + flag;
    }
}


class Scanner
{
    string[] s;
    int i;

    char[] cs = new char[] { ' ' };

    public Scanner()
    {
        s = new string[0];
        i = 0;
    }

    public string next()
    {
        if (i < s.Length) return s[i++];
        string st = Console.ReadLine();
        while (st == "") st = Console.ReadLine();
        s = st.Split(cs, StringSplitOptions.RemoveEmptyEntries);
        if (s.Length == 0) return next();
        i = 0;
        return s[i++];
    }

