class Solver
{
    Scanner sc = new Scanner();
    //
    List<int>[] edge;
    public void Solve()
    {
        var N = sc.Int;

        edge = Create(N, () => new List<int>());
        for (var i = 0; i < N - 1; i++)
        {
            int a, b;
            sc.Make(out a, out b);
            //a--; b--;
            edge[a].Add(b);
            edge[b].Add(a);
        }
        for (var i = 0; i < N; i++)
            if (edge[i].Count > 2)
                Fail(dfs(i, -1));
        WriteLine(1);
    }
    int dfs(int idx, int p)
    {
        int c = 0, z = -1;
        foreach (var e in edge[idx])
            if (e != p)
            {
                var t = dfs(e, idx);
                if (t == 0) z++;
                c += t;
            }
        return c + Max(z, 0);
    }
}

