public class Program
{
    private int N;
    private List<int>[] Edge;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        Edge = new List<int>[N];
        for (int i = 0; i < N; i++)
        {
            Edge[i] = new List<int>();
        }

        for (int i = 0; i < N - 1; i++)
        {
            int a = sc.NextInt();
            int b = sc.NextInt();
            Edge[a].Add(b);
            Edge[b].Add(a);
        }

        // node iの子が k個
        // 部分木 k個
        // アンテナが無い木が2つ以上ある
        // 無い部分木を区別できない
        // 無い木は1つ以下

        // 次数が3以上の頂点を根として見る
        // 親側には必ずアンテナがある
        // 

        int root = -1;
        for (int i = 0; i < N; i++)
        {
            if (Edge[i].Count >= 3) root = i;
        }

        if (root == -1)
        {
            Console.WriteLine(1);
            return;
        }
        Console.WriteLine(Search(root, -1));
    }

    // 現在地、親、置く必要があるか?
    int Search(int n, int parent)
    {
        int sum = 0;
        int cnt = 0;
        foreach (int to in Edge[n])
        {
            if (parent == to) continue;
            int t = Search(to, n);
            if (t == 0) cnt++;
            sum += t;
        }

        if (cnt >= 1) sum += cnt - 1;
        return sum;
    }

    public static void Main(string[] args) => new Program().Solve();
}

