class Solve{
    int count;
    List<int>[] G;
    public Solve(){}
    StringBuilder sb;
    ReadData re;
    public static int Main(){
        new Solve().Run();
        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        re = new ReadData();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        int N = re.i();
        G = re.g(N,N-1);
        count = 0;
        for(int i=0;i<N;i++){
            if(G[i].Count > 2){
                dfs(i,-1);
                break;
            }
        }
        if(count == 0){
            count = 1;
        }
        sb.Append(count+"\n");
    }
    bool dfs(int v,int f){
        if(G[v].Count == 1){
            return true;
        }
        if(G[v].Count == 2){
            if(G[v][0] == f){
                return dfs(G[v][1],v);
            }
            else{
                return dfs(G[v][0],v);
            }
        }
        int edge = 0;
        for(int i=0;i<G[v].Count;i++){
            if(G[v][i] != f){
                if(dfs(G[v][i],v)){
                    edge++;
                }
            }
        }
        edge--;
        if(edge >= 0){
            count += edge;
        }
        return false;
    }
}
