var reader = bufio.NewReaderSize(os.Stdin, 1000000)
var writer = bufio.NewWriter(os.Stdout)
func NextLine() string {
  buffer := make([]byte, 0)
  for true {
    line, isPrefix, err := reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer, line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func NextInt() int {
  n, _ := strconv.Atoi(NextLine())
  return n
}
func NextIntVec() []int {
  L := strings.Split(NextLine(), " ")
  N := make([]int, len(L))
  for i := range N {
    N[i], _ = strconv.Atoi(L[i])
  }
  return N
}
func Write(s interface{}) {
  fmt.Fprintln(writer, s)
}
func Output() {
  _ = writer.Flush()
}

func DFS(T *[][]int, D *[]int, p, v int) int {
  if len((*T)[v]) == 1 {
    (*D)[v] = 1
    return 1
  }
  for _, adj := range (*T)[v] {
    if adj == p { continue }
    (*D)[v] += DFS(T, D, v, adj)
  }
  return (*D)[v]
}

func Solve() {
  N := NextInt()
  T := make([][]int, N)
  for i := range T {
    T[i] = make([]int, 0)
  }
  for i := 1; i < N; i++ {
    xy := NextIntVec()
    x, y := xy[0], xy[1]
    T[x] = append(T[x], y)
    T[y] = append(T[y], x)
  }
  max := 0
  for i, t := range T {
    if len(T[max]) < len(t) { max = i }
  }
  D := make([]int, N)
  DFS(&T, &D, max, max)
  Q := make([]int, 0)
  Q = append(Q, max)
  for 0 < len(Q) {
    q := Q[0]
    Q = Q[1:]
    rm := false
    for _, adj := range T[q] {
      if 0 < D[adj] { Q = append(Q, adj) }
      if D[q] == 1 || D[adj] != 1 || rm { continue }
      D[adj] = 0
      rm = true
    }
    if 1 < len(T[q]) { D[q] = 0 }
  }
  cnt := 0
  for _, d := range D {
    if 0 < d { cnt++ }
  }
  Write(cnt)
  return
}

func main() {
  Solve()
  Output()
}

