const MOD: usize = 1e9 as usize + 7;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let mut graph = vec![vec![]; n];
    for _ in 1..n {
        let a: usize = sc.read();
        let b: usize = sc.read();
        graph[a].push(b);
        graph[b].push(a);
    }

    for i in 0..n {
        if graph[i].len() >= 3 {
            let (ans, _) = dfs(i, i, &graph);
            println!("{}", ans);
            return;
        }
    }
    println!("1");
}

fn dfs(v: usize, p: usize, graph: &Vec<Vec<usize>>) -> (usize, bool) {
    if graph[v].len() == 1 {
        // leaf
        return (1, true);
    } else if graph[v].len() == 2 {
        let next = if graph[v][0] == p {
            graph[v][1]
        } else {
            graph[v][0]
        };
        return dfs(next, v, graph);
    }

    let mut lines = 0;
    let mut sum = 0;
    for &next in graph[v].iter() {
        if next == p {
            continue;
        }
        let (child, line) = dfs(next, v, graph);
        sum += child;
        if line {
            lines += 1;
        }
    }

    if lines > 0 {
        (sum - 1, false)
    } else {
        (sum, false)
    }
}

pub struct Combination {
    fact: Vec<usize>,
    inv_fact: Vec<usize>,
    modulo: usize,
}

impl Combination {
    pub fn new(max: usize, modulo: usize) -> Combination {
        let mut inv = vec![0; max + 1];
        let mut fact = vec![0; max + 1];
        let mut inv_fact = vec![0; max + 1];
        inv[1] = 1;
        for i in 2..(max + 1) {
            inv[i] = inv[modulo % i] * (modulo - modulo / i) % modulo;
        }
        fact[0] = 1;
        inv_fact[0] = 1;
        for i in 0..max {
            fact[i + 1] = fact[i] * (i + 1) % modulo;
        }
        for i in 0..max {
            inv_fact[i + 1] = inv_fact[i] * inv[i + 1] % modulo;
        }
        Combination {
            fact: fact,
            inv_fact: inv_fact,
            modulo: modulo,
        }
    }

    pub fn get(&self, x: usize, y: usize) -> ModInt<usize> {
        assert!(x >= y);
        ModInt(self.fact[x] * self.inv_fact[y] % self.modulo * self.inv_fact[x - y] % self.modulo)
    }
}

pub mod mod_int {
