#[derive(Debug)]
pub struct TreeRec {
    pub n: usize,
}
impl TreeRec {
    pub fn new(n: usize) -> TreeRec {
        TreeRec { n: n }
    }
    pub fn dfs(&mut self, u: usize, p: usize, graph: &Graph) -> usize {
        let mut n = 0usize;
        let mut x = 0usize;
        for v in graph.adjacency(u) {
            if v.to != p {
                let t = self.dfs(v.to, u, graph);
                x += t;
                if t == 0 {
                    n += 1;
                }
            }
        }
        x + n.saturating_sub(1)
    }
}
fn main() {
    input! { n, ab: [(usize, usize); n-1] };
    let mut graph = Graph::new(n);
    let mut rec = TreeRec::new(n);
    let mut deg = vec![0; n];
    for &(a, b) in &ab {
        graph.add_undirected_edge(a, b);
        deg[a] += 1;
        deg[b] += 1;
    }
    let u = (0..n).max_by_key(|&u| deg[u]).unwrap();
    if deg[u] <= 2 {
        println!("{}", 1);
    } else {
        println!("{}", rec.dfs(u, n, &graph));
    }
}

