fn dfs(v: usize, p: usize, graph: &Vec<Vec<usize>>) -> (bool, usize) {
    let mut ans = vec![];
    for &next in graph[v].iter() {
        if next == p {
            continue;
        }
        ans.push(dfs(next, v, graph));
    }
    if ans.len() == 0 {
        (true, 1)
    } else if ans.len() == 1 {
        ans[0]
    } else {
        let mut has_line = false;
        let mut sum = 0;
        for (is_line, count) in ans.into_iter() {
            has_line |= is_line;
            sum += count;
        }

        if has_line {
            (false, sum - 1)
        } else {
            (false, sum)
        }
    }
}

