fn dfs(v: usize, p: usize, graph: &Vec<Vec<usize>>) -> (bool, usize) {
    let mut children = 0;
    let mut sum = 0;
    let mut has_line = false;
    for &next in graph[v].iter().filter(|&&next| next != p) {
        children += 1;
        let (only_line, count) = dfs(next, v, graph);
        sum += count;
        assert!(!only_line || count == 1);
        has_line |= only_line;
    }

    if children == 0 {
        (true, 1)
    } else if children == 1 {
        (has_line, sum)
    } else {
        if has_line {
            (false, sum - 1)
        } else {
            (false, sum)
        }
    }
}

pub struct Scanner<R> {
