    for &next in graph[v].iter().filter(|&&next| next != p) {
        result.push(dfs(next, v, graph));
    }

    if result.is_empty() {
        (true, 1)
    } else if result.len() == 1 {
        let (only_line, count) = result[0];
        assert!(!only_line || count == 1);
        (only_line, count)
    } else {
        let sum = result.iter().map(|&(_, count)| count).sum::<usize>();
        let mut ans = sum;
        for (only_line, count) in result.into_iter() {
            if only_line {
                assert_eq!(count, 1);
                ans = cmp::min(ans, sum - 1);
            }
        }
        (false, ans)
    }
}

