type Graph = Vec<Vec<usize>>;

fn dfs(graph: &Graph, now: usize, parent: Option<usize>) -> Vec<usize> {
    let mut cn = 0;
    let mut cres = vec![];
    for &to in &graph[now] {
        if Some(to) == parent {
            continue;
        }
        cn += 1;
        cres.push(dfs(graph, to, Some(now)));
    }
    if cn == 0 {
        return vec![0, 1];
    }
    if cn == 1 {
        return cres[0].clone();
    }

    let mut ret = dvec!(INF; cn+1, 2);
    ret[0][0] = 0;
    for i in 0..cn {
        for f in 0..2 {
            let base = ret[i][f];
            if f == 0 {
                ret[i+1][1] = min(ret[i+1][1], base+cres[i][0]);
            }
            ret[i+1][f] = min(ret[i+1][f], base+cres[i][1]);
        }
    }
    vec![INF, min(ret[cn][0], ret[cn][1])]
}

fn solve(g: &Graph) -> usize {
    let n = g.len();
    let mut has3 = false;
    for i in 0..n {
        has3 |= g[i].len() >= 3;
