const INF: i32 = 1 << 25;

fn dfs(g: &[Vec<usize>], v: usize, par: usize) -> [i32; 2] {
    let mut ch = vec![];
    for &w in &g[v] {
        if par == w { continue; }
        ch.push(w);
    }
    if ch.len() == 0 {
        return [0, 1];
    }
    let mut ret = [1; 2];
    let mut ma = 0;
    for &w in &ch {
        let sub = dfs(g, w, v);
        for j in 0..2 {
            ret[j] += sub[j];
            if sub[j] == -INF {
                ret[j] = -INF;
            }
        }
        ma = max(ma, sub[1] - sub[0]);
    }
    if ch.len() >= 2 {
        ret[1] = -INF;
        ret[0] += ma;
    } else {
    }
    //eprintln!("dfs({}) = {:?}", v, ret);
    ret
}

// 0: parent doesn't need to have antennas
// 1: parent needs to have antennas
fn dfs2(g: &[Vec<usize>], v: usize, par: usize) -> [i32; 2] {
    let mut ch = vec![];
    for &w in &g[v] {
        if par == w { continue; }
        ch.push(w);
    }
    if ch.len() == 0 {
        return [0, 0];
    }
    if ch.len() == 1 {
        let mut sub = dfs2(g, ch[0], v);
        if sub[0] == 0 {
            sub[0] = 1;
        }
        return sub;
    }
    let mut ans = [0; 2];
    let mut vecs = vec![vec![]; 2];
    for &w in &ch {
        let sub = dfs2(g, w, v);
        for i in 0..2 {
            vecs[i].push(sub[1]);
        }
    }
    for i in 0..2 {
        vecs[i].sort();
        for j in i..vecs[i].len() {
            vecs[i][j] = max(vecs[i][j], 1);
        }
        for &a in &vecs[i] {
            ans[i] += a;
        }
    }
    //eprintln!("{} -> {:?}", v, ans);
    ans
}

fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
