        ab: [(usize, usize); n - 1],
    }
    let mut g = vec![vec![]; n];
    for &(a, b) in &ab {
        g[a].push(b);
        g[b].push(a);
    }
    let ans;
    if g.len() == 2 {
        ans = 1;
    } else {
        let mut r = 0;
        for i in 0..n {
            if g[i].len() >= 2 {
                r = i;
                break;
            }
        }
        ans = dfs2(&g, r, n)[1];
    }
    puts!("{}\n", ans);
}

