fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let mut graph = vec![vec![]; n];
    for _ in 1..n {
        let a: usize = sc.read();
        let b: usize = sc.read();
        graph[a].push(b);
        graph[b].push(a);
    }

    if let Some(root) = (0..n).find(|&i| graph[i].len() >= 3) {
        let (ans, _) = calc(root, root, &graph);
        println!("{}", ans);
    } else {
        println!("1");
    }
}

fn calc(v: usize, p: usize, graph: &Vec<Vec<usize>>) -> (usize, bool) {
    let children: Vec<usize> = graph[v].iter().cloned().filter(|&next| next != p).collect();
    match children.len() {
        0 | 1 => (1, true),
        _ => {
            let mut one_line = false;
            let mut sum = 0;
            for next in children.into_iter() {
                let (next_count, is_line) = calc(next, v, graph);
                sum += next_count;
                one_line |= is_line;
            }
            (sum - if one_line { 1 } else { 0 }, false)
        }
    }
}

