impl UndirectedSparseGraph {
    fn dfs(&self, u: usize, p: usize) -> usize {
        let mut acc = 0;
        let mut z = 0;
        for a in self.adjacencies(u).filter(|a| a.to != p) {
            let x = self.dfs(a.to, u);
            acc += x;
            z += (x == 0) as usize;
        }
        acc + z.saturating_sub(1)
    }
}

