const INF: usize = 1e9 as usize;

type Graph = Vec<Vec<usize>>;

fn dfs(graph: &Graph, now: usize, parent: Option<usize>) -> Vec<usize> {
    let mut cn = 0;
    let mut cres = vec![];
    for &to in &graph[now] {
        if Some(to) == parent {
            continue;
        }
        cn += 1;
        cres.push(dfs(graph, to, Some(now)));
    }
    if cn == 0 {
        return vec![0, 1];
    }

    let mut ret = dvec!(INF; cn+1, 2);
    let mut ret0 = 0;
    ret[0][0] = 0;
    for i in 0..cn {
        for f in 0..2 {
            let base = ret[i][f];
            if f == 0 {
                ret[i+1][1] = min(ret[i+1][1], base+cres[i][0]);
            }
            ret[i+1][f] = min(ret[i+1][f], base+cres[i][1]);
        }
        ret0 += cres[i][0];
    }
    if cn >= 2 {
        ret0 = INF;
    }
    let mut ret1 = min(INF, ret[cn][1]);
    if cn == 1 {
        ret1 = ret[cn][0];
    }
    // debug!(ret0, ret1, now, cres);
    vec![min(INF, ret0), min(INF, ret1)]
}

fn solve(g: &Graph) -> usize {
    let n = g.len();
    let mut has3 = false;
    for i in 0..n {
        has3 |= g[i].len() >= 3;
    }
    if !has3 {
        return 1;
    }

    let mut root = 0;
    for i in 0..n {
        if g[i].len() >= 3 {
            root = i;
            break;
        }
    }

    let a = dfs(g, root, None);
    a[1]
}


