fn dfs2(g: &[Vec<usize>], v: usize, par: usize) -> [i32; 2] {
    let mut ch = vec![];
    for &w in &g[v] {
        if par == w { continue; }
        ch.push(w);
    }
    if ch.len() == 0 {
        return [0, 0];
    }
    if ch.len() == 1 {
        let mut sub = dfs2(g, ch[0], v);
        sub[0] = min(max(sub[0], 1), sub[1] + 1);
        return sub;
    }
    let mut ans = [0; 2];
    let mut vecs = vec![vec![]; 2];
    for &w in &ch {
        let sub = dfs2(g, w, v);
