    for i in 0..2 {
        vecs[i].sort();
        for j in i..vecs[i].len() {
            vecs[i][j] = max(vecs[i][j], 1);
        }
        for &a in &vecs[i] {
            ans[i] += a;
        }
    }
    debugln!("{} -> {:?}", v, ans);
    ans
