use std::cmp;

fn dfs(v: usize, prev: Option<(usize, bool)>, adj: &[Vec<usize>], memo: &mut [Vec<Option<u32>>; 2]) -> u32 {
    let index1 = prev.map_or(0, |(_, p)| p as usize);
    memo[index1][v].unwrap_or_else(|| {

        let subs: Vec<u32> = adj[v].iter()
            .filter(|&&u| prev.map_or(true, |(p, _)| p != u))
            .map(|&u| dfs(u, Some((v, true)), adj, memo))
            .collect();
        let placed = subs.iter().sum::<u32>() +
            (subs.iter().filter(|&&n| n == 0).count() as u32).saturating_sub(1);
        let ans = if prev.map_or(false, |(_, p)| p) {
            placed
        } else {
            let children: Vec<usize> = adj[v].iter().cloned()
                .filter(|&u| prev.map_or(true, |(p, _)| p != u))
                .collect();
            let nonplaced = if children.is_empty() {
                1
            } else if children.len() == 1 {
                dfs(children[0], Some((v, false)), adj, memo)
            } else {
                subs.iter().map(|&n| cmp::max(n, 1)).sum()
            };
            cmp::min(1 + placed, nonplaced)
        };
        memo[index1][v] = Some(ans);
        ans
    })
}

