fn calc(v: usize, p: usize, graph: &Vec<Vec<usize>>) -> (usize, bool) {
    let children: Vec<usize> = graph[v].iter().cloned().filter(|&next| next != p).collect();
    match children.len() {
        0 => (1, true),
        1 => calc(children[0], v, graph),
        _ => {
            let mut one_line = false;
            let mut sum = 0;
            for next in children.into_iter() {
                let (next_count, is_line) = calc(next, v, graph);
                sum += next_count;
                one_line |= is_line;
            }
            (sum - if one_line { 1 } else { 0 }, false)
        }
    }
}

